INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85755, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "得", "is_correct": true, "explanation": "正确。得 读轻声 de，用在动词后引出补语。"}, {"text": "德", "is_correct": false, "explanation": "dé（第二声）与 de（轻声）声调不同，意思是“道德”。"}, {"text": "了", "is_correct": false, "explanation": "le（轻声）与 de 只差声母，是表示完成的助词“了”。"}, {"text": "呢", "is_correct": false, "explanation": "ne（轻声）与 de 声母不同，意思是语气词“呢”。"}], "explanations": {"得": "正确。得 读轻声 de，用在动词后引出补语。", "德": "dé（第二声）与 de（轻声）声调不同，意思是“道德”。", "了": "le（轻声）与 de 只差声母，是表示完成的助词“了”。", "呢": "ne（轻声）与 de 声母不同，意思是语气词“呢”。"}, "sentence_index": null, "correct_answer": "得"}, "level_3": {"options": [{"text": "得", "is_correct": true, "explanation": "正确。「得」用在动词后，引出对“跑”的情况的评价“很快”。"}, {"text": "了", "is_correct": false, "explanation": "体貌：「了」表示完成，“他跑了很快”不能用来评价跑的情况。"}, {"text": "着", "is_correct": false, "explanation": "体貌：「着」表示持续状态，“他跑着很快”句意不通，不能用于评价跑的程度。"}, {"text": "之", "is_correct": false, "explanation": "语域：「之」是文言助词，不能用于这样的白话句子。"}], "explanations": {"得": "正确。「得」用在动词后，引出对“跑”的情况的评价“很快”。", "了": "体貌：「了」表示完成，“他跑了很快”不能用来评价跑的情况。", "着": "体貌：「着」表示持续状态，“他跑着很快”句意不通，不能用于评价跑的程度。", "之": "语域：「之」是文言助词，不能用于这样的白话句子。"}, "sentence_index": 0, "correct_answer": "得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他得了第一名。", "explanation": "这里的“得”读 dé，表示获得，是另一个义项，不是引出补语的“得”（de）。"}, {"text": "我们得先走了。", "explanation": "这里的“得”读 děi，表示必须，是另一个义项，不是引出补语的“得”（de）。"}, {"text": "我明天得早起。", "explanation": "这里的“得”读 děi，表示必须，是另一个意思，不是引出补语的“得”（de）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85755, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "得", "is_correct": true, "explanation": "正确。得 读轻声 de，用在动词后引出补语。"}, {"text": "么", "is_correct": false, "explanation": "me（轻声）与 de 只差声母，用于“什么”。"}, {"text": "着", "is_correct": false, "explanation": "zhe（轻声）与 de 只差声母，是表示持续的助词“着”。"}, {"text": "嘚", "is_correct": false, "explanation": "dē（第一声）与 de（轻声）声调不同，用于“嘚瑟”。"}], "explanations": {"得": "正确。得 读轻声 de，用在动词后引出补语。", "么": "me（轻声）与 de 只差声母，用于“什么”。", "着": "zhe（轻声）与 de 只差声母，是表示持续的助词“着”。", "嘚": "dē（第一声）与 de（轻声）声调不同，用于“嘚瑟”。"}, "sentence_index": null, "correct_answer": "得"}, "level_3": {"options": [{"text": "得", "is_correct": true, "explanation": "正确。「得」用在动词后，引出对“讲”的情况的评价“很清楚”。"}, {"text": "所", "is_correct": false, "explanation": "语域：「所」是文言用法，不能用于这类白话句子。"}, {"text": "者", "is_correct": false, "explanation": "语域：「者」是文言用法，用在这里不符合白话语域。"}, {"text": "罢", "is_correct": false, "explanation": "语义：「罢」表示语气或结束，“讲罢很清楚”句意不通，不能引出对讲课情况的评价。"}], "explanations": {"得": "正确。「得」用在动词后，引出对“讲”的情况的评价“很清楚”。", "所": "语域：「所」是文言用法，不能用于这类白话句子。", "者": "语域：「者」是文言用法，用在这里不符合白话语域。", "罢": "语义：「罢」表示语气或结束，“讲罢很清楚”句意不通，不能引出对讲课情况的评价。"}, "sentence_index": 6, "correct_answer": "得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天得第一名了。", "explanation": "这里的“得”读 dé，表示获得，是另一个义项；本句说的不是动作后的补语。"}, {"text": "我们明天得早点出发。", "explanation": "这里的“得”读 děi，表示必须，是另一个义项，不是引出补语的“得”（de）。"}, {"text": "他得了肺炎。", "explanation": "这里的“得”读 dé，表示患上（病），是另一个义项，不是引出补语的“得”（de）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她画画地得很好。", "corrected_sentence": "她画画得很好。", "error_description": "错误形式：「画画地得很好」；正确形式：「画画得很好」。「地」只用于动词前修饰动作，动词后引出评价补语要用「得」，这里多加了「地」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跑步跑得很累得。", "corrected_sentence": "他跑步跑得很累。", "error_description": "错误形式：「跑得很累得」；正确形式：「跑得很累」。「得」只用一次，紧跟动词引出补语「很累」，句末多加的「得」应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
