INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85759, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85759, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“这样”是说像这样子，指我们现在看到的样子。", "primary_collocate": null, "pronunciation": "zhè yàng", "ipa": "ʈʂɤ˥˩ iɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你看，就是这样。", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的房间不是这样的。", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天都是这样。", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说：“对，就是这样。”", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你把手这样放在桌子上。", "target_word": "这样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做给你看，要这样转一下。", "target_word": "这样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样就可以了。", "target_word": "这样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直这样，我也没办法。", "target_word": "这样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "照片里的小狗是这样的，很可爱。", "target_word": "这样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的字写成这样，我看不清。", "target_word": "这样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "这样子", "label": "变体"}, {"form": "這樣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "指示代词这样：单独作谓语或指代眼前看到的样子、做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa09a39c-1dc4-4f09-8ce9-0310badb768d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这样", "is_correct": true, "explanation": "“这样”指眼前看到的样子，“就是这样”表示就是这个样子，语义通顺。"}, {"text": "哪样", "is_correct": false, "explanation": "语义：“哪样”是疑问，问样子如何，不能用于肯定地指出眼前的样子。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”问地点，不能指代样子，句子不通。"}, {"text": "某", "is_correct": false, "explanation": "搭配：“某”要修饰名词，不能单独作“就是”的宾语，句子不通。"}], "explanations": {"这样": "“这样”指眼前看到的样子，“就是这样”表示就是这个样子，语义通顺。", "哪样": "语义：“哪样”是疑问，问样子如何，不能用于肯定地指出眼前的样子。", "哪里": "语义：“哪里”问地点，不能指代样子，句子不通。", "某": "搭配：“某”要修饰名词，不能单独作“就是”的宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "这样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这样是我的书。", "explanation": "这里应该用〈这个〉。“这样”指性质或做法，不能指代一件具体的东西，指东西要用“这个”。"}, {"text": "你的书在这样，快拿走。", "explanation": "这里应该用〈这里〉。“这样”指样子或做法，不表示地点，说书在哪儿要用“这里”。"}, {"text": "我的家在这样，离学校很近。", "explanation": "这里应该用〈这里〉。“这样”表示性质或做法，不表示地点，说家在哪里要用“这里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这样", "is_correct": true, "explanation": "“这样”指做成眼前这个样子，与“就可以了”搭配，表示做法已经足够。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能表示做法，“谁就可以了”意思不通。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”问地点，不能表示做法，“哪里就可以了”意思不通。"}, {"text": "某些", "is_correct": false, "explanation": "搭配：“某些”要修饰名词，不能单独作“就可以了”的主语。"}], "explanations": {"这样": "“这样”指做成眼前这个样子，与“就可以了”搭配，表示做法已经足够。", "谁": "语义：“谁”指人，不能表示做法，“谁就可以了”意思不通。", "哪里": "语义：“哪里”问地点，不能表示做法，“哪里就可以了”意思不通。", "某些": "搭配：“某些”要修饰名词，不能单独作“就可以了”的主语。"}, "sentence_index": 6, "correct_answer": "这样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这样是老师。", "explanation": "“这样”指示性质或做法，不能用来说明人的身份，这里的用法不对。"}, {"text": "我们这样下午三点见面。", "explanation": "“这样”表示做法，不表示时间，说时间要直接说“下午三点”。"}, {"text": "这样是我的老师。", "explanation": "这里应该用〈这位〉。“这样”指性质或做法，不能指代一个人，指人要用“这位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢这样字。", "corrected_sentence": "我喜欢这样的字。", "error_description": "错误：“这样”修饰名词时中间要加“的”，应说“这样的字”，漏掉“的”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你这样的拿，就不会掉了。", "corrected_sentence": "你这样拿，就不会掉了。", "error_description": "错误：“这样”修饰动词作状语时不加“的”，“这样的”只修饰名词，应说“这样拿”，多加“的”不通。正确：“你这样拿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
