INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85761, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“它”是说小动物或者东西，不是人。", "primary_collocate": null, "pronunciation": "tā", "ipa": "tʰa˥", "syllable_count": 1, "sentences": [{"text": "我有一只小猫，它很可爱。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗很大，它叫大黄。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我的新手机，我很喜欢它。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞走了，它去哪儿了？", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书很好看，你看看它吧。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼在水里，它游得很快。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的猫爱睡觉，它一天睡很久。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子是新的，你别打破它。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那只鸟，它的头是红色的。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这棵树，它很高。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "它们", "label": "复数"}, {"form": "它的", "label": "领属"}], "register": "口语", "sense_fingerprint": "指动物或事物的第三人称代词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85761, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "它", "is_correct": true, "explanation": "“它”指代前文的小猫，符合句意。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指复数，前文只有一只小猫，不能用复数。"}, {"text": "你", "is_correct": false, "explanation": "语义：“你”指听话的人，不能指代小猫，句意不通。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”指说话人与他人，不能指代小猫，与前文的“一只小猫”不符。"}], "explanations": {"它": "“它”指代前文的小猫，符合句意。", "它们": "语义：“它们”指复数，前文只有一只小猫，不能用复数。", "你": "语义：“你”指听话的人，不能指代小猫，句意不通。", "我们": "语义：“我们”指说话人与他人，不能指代小猫，与前文的“一只小猫”不符。"}, "sentence_index": 0, "correct_answer": "它"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那些小鸟很漂亮，它在树上唱歌。", "explanation": "这里的“它”指单个的动物或事物，指多只鸟应说〈它们〉，此处用“它”指复数是错误的。"}, {"text": "我的老师很好，它常常帮助我。", "explanation": "语义：“它”不能指代人，此处应用〈他〉或〈她〉。"}, {"text": "我的妹妹很聪明，它总是考第一。", "explanation": "语义：“它”不能指代人，此处应用〈她〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "它", "is_correct": true, "explanation": "“它”指代前文的猫，符合句意。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指复数，前文的“我家的猫”只有一只，不能用复数。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“谁”问人，前文已有“我家的猫”作先行语，不能用于此处指代。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”指听话的人，不能指代猫，句意不通。"}], "explanations": {"它": "“它”指代前文的猫，符合句意。", "它们": "语义：“它们”指复数，前文的“我家的猫”只有一只，不能用复数。", "谁": "配价：“谁”问人，前文已有“我家的猫”作先行语，不能用于此处指代。", "你们": "语义：“你们”指听话的人，不能指代猫，句意不通。"}, "sentence_index": 6, "correct_answer": "它"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈很累，它还在工作。", "explanation": "语义：“它”指事物或动物，不能指代“妈妈”，此处应用“她”。"}, {"text": "我的同学很认真，它每天按时到校。", "explanation": "语义：“它”不能指代人，此处应用〈他〉或〈她〉。"}, {"text": "这位老师很好，它教我们英语。", "explanation": "语义：“它”不能指代人，此处应用〈他〉或〈她〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个杯子掉在地上了，它们摔碎了吗？", "corrected_sentence": "那个杯子掉在地上了，它摔碎了吗？", "error_description": "错误：指一个杯子却用了复数“它们”。正确：“它”指单个事物，应说“它摔碎了吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "太阳很大，它们照在我身上。", "corrected_sentence": "太阳很大，它照在我身上。", "error_description": "错误：指太阳却用了复数“它们”。正确：“它”指单个事物，应说“它照在我身上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
