INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85762, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第三人称代词，指称人以外的事物或动物。", "primary_collocate": null, "pronunciation": "tā", "ipa": "tʰa˥", "syllable_count": 1, "sentences": [{"text": "小狗饿了，快给它吃的。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河很长，它从山里来。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑坏了，我不会修它。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只兔子很白，它在吃草。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子很旧，但我不想扔掉它。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小马跑得快，它不怕人。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳很大，它照在我身上。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花很漂亮，你给它浇水了吗？", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我养了一条鱼，每天都看它游。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个箱子很重，你别一个人搬它。", "target_word": "它", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "它们", "label": "复数"}, {"form": "它的", "label": "领属"}], "register": "口语", "sense_fingerprint": "第三人称代词，指人以外的事物或动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 朵 (Zipf 3.75), 很漂亮 (Zipf 3.82), 浇水 (Zipf 3.27)']::text[], '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85762, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "它", "is_correct": true, "explanation": "“它”指代前文的小狗，符合句意。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指复数，前文只有一只小狗，不能用复数。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“谁”是疑问代词，用在陈述的祈使句中不能指代前文的小狗，“快给谁吃的。”不成立。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”指说话人与他人，不能指代小狗。"}], "explanations": {"它": "“它”指代前文的小狗，符合句意。", "它们": "语义：“它们”指复数，前文只有一只小狗，不能用复数。", "谁": "配价：“谁”是疑问代词，用在陈述的祈使句中不能指代前文的小狗，“快给谁吃的。”不成立。", "我们": "语义：“我们”指说话人与他人，不能指代小狗。"}, "sentence_index": 0, "correct_answer": "它"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那两只羊很大，它在草地上跑。", "explanation": "这里的“它”指单个的动物，指两只羊应说〈它们〉，此处用“它”指复数是错误的。"}, {"text": "我的弟弟很可爱，它常常笑。", "explanation": "语义：“它”不能指代人，此处应用〈他〉。"}, {"text": "我的妈妈很忙，它每天工作。", "explanation": "语义：“它”不能指代人，此处应用〈她〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "它", "is_correct": true, "explanation": "“它”指代前文的太阳，符合句意。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指多个人，不能指代单个的“太阳”。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指说话人，“我照在我身上”句意不通。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指其他的人，不能指代前文的“太阳”。"}], "explanations": {"它": "“它”指代前文的太阳，符合句意。", "他们": "语义：“他们”指多个人，不能指代单个的“太阳”。", "我": "语义：“我”指说话人，“我照在我身上”句意不通。", "别人": "语义：“别人”指其他的人，不能指代前文的“太阳”。"}, "sentence_index": 6, "correct_answer": "它"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈很累，它还在工作。", "explanation": "语义：“它”指事物或动物，不能指代“妈妈”，此处应用“她”。"}, {"text": "那位叔叔很友好，它常常帮助邻居。", "explanation": "语义：“它”不能指代人，此处应用〈他〉。"}, {"text": "这位老师很好，它教我们英语。", "explanation": "语义：“它”不能指代人，此处应用〈他〉或〈她〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那把椅子很旧，它们还能用。", "corrected_sentence": "那把椅子很旧，它还能用。", "error_description": "错误：指一把椅子却用了复数“它们”。正确：“它”指单个事物，应说“它还能用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个箱子很重，它们压坏了地板。", "corrected_sentence": "那个箱子很重，它压坏了地板。", "error_description": "错误：指一个箱子却用了复数“它们”。正确：“它”指单个事物，应说“它压坏了地板”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
