INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85763, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“那”是用来指离我们远一点的人或东西。", "primary_collocate": null, "pronunciation": "nà", "ipa": "na˥˩", "syllable_count": 1, "sentences": [{"text": "这是我的杯子，那是你的杯子。", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是我的书包，不是你的。", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把那本书给我。", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那边山上的那座房子是新盖的。", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裙子很好看，那条也不错。", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买这双鞋，不想买那双。", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那是一只小狗。", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆红色的车是我哥哥的。", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口的那家饭店很有名。", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是你的雨伞吗？", "target_word": "那", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那个", "label": "复合"}, {"form": "那些", "label": "复合"}, {"form": "那里", "label": "复合"}], "register": "口语", "sense_fingerprint": "指示代词：指离说话人较远的人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec8071b-2a1d-4600-a16f-7fee21a7b3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85763, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "那", "is_correct": true, "explanation": "「那」是指示代词，指离说话人较远的人或东西，是这里的正确答案。"}, {"text": "哪", "is_correct": false, "explanation": "「哪」与「那」声调不同（第三声与第四声），意思是疑问代词“哪个”。"}, {"text": "拿", "is_correct": false, "explanation": "「拿」与「那」声调不同（第二声与第四声），意思是拿取。"}, {"text": "辣", "is_correct": false, "explanation": "「辣」与「那」声母不同（l 与 n），意思是辣味。"}, {"text": "腊", "is_correct": false, "explanation": "「腊」与「那」声母不同（l 与 n），意思是腊肉、腊月。"}], "explanations": {"那": "「那」是指示代词，指离说话人较远的人或东西，是这里的正确答案。", "哪": "「哪」与「那」声调不同（第三声与第四声），意思是疑问代词“哪个”。", "拿": "「拿」与「那」声调不同（第二声与第四声），意思是拿取。", "辣": "「辣」与「那」声母不同（l 与 n），意思是辣味。", "腊": "「腊」与「那」声母不同（l 与 n），意思是腊肉、腊月。"}, "sentence_index": null, "correct_answer": "那"}, "level_3": {"options": [{"text": "那", "is_correct": true, "explanation": "「那」指离说话人较远的东西，与前面的“这是我的杯子”对比，句意通顺。"}, {"text": "哪", "is_correct": false, "explanation": "语义：“哪”是疑问代词，句子是陈述，不能说“哪是你的杯子。”"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指人，不能指杯子。"}, {"text": "彼", "is_correct": false, "explanation": "语域：“彼”是书面语，口语里不说“彼是你的杯子”。"}], "explanations": {"那": "「那」指离说话人较远的东西，与前面的“这是我的杯子”对比，句意通顺。", "哪": "语义：“哪”是疑问代词，句子是陈述，不能说“哪是你的杯子。”", "他们": "语义：“他们”指人，不能指杯子。", "彼": "语域：“彼”是书面语，口语里不说“彼是你的杯子”。"}, "sentence_index": 0, "correct_answer": "那"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那本书就在我手边，我一伸手就够得着。", "explanation": "这里应该用〈这〉。那指较远的，书伸手就够得着，离说话人很近，要用这。"}, {"text": "那支笔就在我手里，你看。", "explanation": "这里应该用〈这〉。那指较远的，笔就在我手里，离说话人很近，要用这。"}, {"text": "那个人就坐在我旁边，正在跟我说话。", "explanation": "这里应该用〈这个〉。那个指较远的人，人坐在旁边离说话人很近，要用这个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那", "is_correct": true, "explanation": "「那」指较远的东西，与“是一只小狗”搭配，句意通顺。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能指小狗，且句子是陈述。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”指人，不能指小狗。"}, {"text": "此", "is_correct": false, "explanation": "语域：“此”是书面语，口语里不说“此是一只小狗”。"}], "explanations": {"那": "「那」指较远的东西，与“是一只小狗”搭配，句意通顺。", "谁": "语义：“谁”指人，不能指小狗，且句子是陈述。", "我们": "语义：“我们”指人，不能指小狗。", "此": "语域：“此”是书面语，口语里不说“此是一只小狗”。"}, "sentence_index": 6, "correct_answer": "那"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位同学就坐在我旁边。", "explanation": "这里应该用〈这位〉。那位指较远的人，同学就坐在我旁边，要用这位。"}, {"text": "那张桌子就在我面前，我手放在上面。", "explanation": "这里应该用〈这〉。那指较远的，桌子就在我面前，要用这。"}, {"text": "那道菜就摆在我面前，我伸手就能夹到。", "explanation": "这里应该用〈这道〉。那道指较远的，菜就在面前、伸手可及，离说话人很近，要用这道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棵那树是我种的。", "corrected_sentence": "那棵树是我种的。", "error_description": "指示词“那”应放在量词前，写作“那棵树”，不能说“棵那树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那那把雨伞是我的。", "corrected_sentence": "那把雨伞是我的。", "error_description": "“那”不能重复，应只用一个“那”，写作“那把雨伞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
