INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85765, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“吧”放在句子后面，是请别人一起做事，或者说话时不太肯定。", "primary_collocate": null, "pronunciation": "ba", "ipa": "pa", "syllable_count": 1, "sentences": [{"text": "我们一起去公园吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很好，出去走走吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们先吃饭吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课了，我们回家吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天不会来了吧？", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字你会写吧？", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在大概五点了吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起学汉语吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他应该在家吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我们去看电影吧。", "target_word": "吧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末语气助词，邀请别人一起做事或语气不太肯定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa09a39c-1dc4-4f09-8ce9-0310badb768d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85765, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吧", "is_correct": true, "explanation": "“吧”（轻声）是句末语气助词，用来提建议或表示不太肯定。"}, {"text": "八", "is_correct": false, "explanation": "bā（第一声）与 ba（轻声）声调不同，意思是数字八。"}, {"text": "爸", "is_correct": false, "explanation": "bà（第四声）与 ba（轻声）声调不同，意思是爸爸。"}, {"text": "把", "is_correct": false, "explanation": "bǎ（第三声）与 ba（轻声）声调不同，意思是拿、握，如“把门关上”。"}, {"text": "吗", "is_correct": false, "explanation": "m 与 b 声母不同，ma 意思是疑问语气助词“吗”。"}], "explanations": {"吧": "“吧”（轻声）是句末语气助词，用来提建议或表示不太肯定。", "八": "bā（第一声）与 ba（轻声）声调不同，意思是数字八。", "爸": "bà（第四声）与 ba（轻声）声调不同，意思是爸爸。", "把": "bǎ（第三声）与 ba（轻声）声调不同，意思是拿、握，如“把门关上”。", "吗": "m 与 b 声母不同，ma 意思是疑问语气助词“吗”。"}, "sentence_index": null, "correct_answer": "吧"}, "level_3": {"options": [{"text": "吧", "is_correct": true, "explanation": "“吧”表示提议，与“我们一起去公园”搭配，语气自然。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示持续状态，“去公园着”不能作句子的结尾，句子不通。"}, {"text": "的", "is_correct": false, "explanation": "语义：“的”不表示语气，“我们一起去公园的”不构成完整句子。"}, {"text": "过", "is_correct": false, "explanation": "体貌：“过”要紧跟动词，应说“去过公园”，“去公园过”不通。"}], "explanations": {"吧": "“吧”表示提议，与“我们一起去公园”搭配，语气自然。", "着": "体貌：“着”表示持续状态，“去公园着”不能作句子的结尾，句子不通。", "的": "语义：“的”不表示语气，“我们一起去公园的”不构成完整句子。", "过": "体貌：“过”要紧跟动词，应说“去过公园”，“去公园过”不通。"}, "sentence_index": 0, "correct_answer": "吧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "欢迎光临吧。", "explanation": "“吧”表示建议、请求、同意或不确定，“欢迎光临”是迎客的固定用语，不能加“吧”表达这些语气，这里用法不对。"}, {"text": "早上好吧。", "explanation": "“早上好”是问候语，不表示建议、请求或不确定，加上“吧”不通。"}, {"text": "祝你生日快乐吧。", "explanation": "“祝你生日快乐”是祝福语，不表示建议、请求或不确定，加上“吧”表达这些语气，用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85765, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吧", "is_correct": true, "explanation": "“吧”（轻声）是句末语气助词，用来提建议或表示不太肯定。"}, {"text": "巴", "is_correct": false, "explanation": "bā（第一声）与 ba（轻声）声调不同，意思是盼望，如“巴不得”。"}, {"text": "拔", "is_correct": false, "explanation": "bá（第二声）与 ba（轻声）声调不同，意思是拔出、拉起。"}, {"text": "霸", "is_correct": false, "explanation": "bà（第四声）与 ba（轻声）声调不同，意思是霸占、强横。"}, {"text": "嘛", "is_correct": false, "explanation": "m 与 b 声母不同，ma 意思是语气助词“嘛”，表示显而易见。"}], "explanations": {"吧": "“吧”（轻声）是句末语气助词，用来提建议或表示不太肯定。", "巴": "bā（第一声）与 ba（轻声）声调不同，意思是盼望，如“巴不得”。", "拔": "bá（第二声）与 ba（轻声）声调不同，意思是拔出、拉起。", "霸": "bà（第四声）与 ba（轻声）声调不同，意思是霸占、强横。", "嘛": "m 与 b 声母不同，ma 意思是语气助词“嘛”，表示显而易见。"}, "sentence_index": null, "correct_answer": "吧"}, "level_3": {"options": [{"text": "吧", "is_correct": true, "explanation": "“吧”表示推测，与“现在大概五点了”搭配，语气自然。"}, {"text": "地", "is_correct": false, "explanation": "语义：“地”用在动词前作状语，不能用在“了”后面作句末，句子不通。"}, {"text": "得", "is_correct": false, "explanation": "配价：“得”后要接补语，“五点了得”不能结束句子，不通。"}, {"text": "罢了", "is_correct": false, "explanation": "语义：“罢了”表示“只是这样而已”，与“大概五点”的推测语气不合，句子不通。"}], "explanations": {"吧": "“吧”表示推测，与“现在大概五点了”搭配，语气自然。", "地": "语义：“地”用在动词前作状语，不能用在“了”后面作句末，句子不通。", "得": "配价：“得”后要接补语，“五点了得”不能结束句子，不通。", "罢了": "语义：“罢了”表示“只是这样而已”，与“大概五点”的推测语气不合，句子不通。"}, "sentence_index": 6, "correct_answer": "吧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他来了吗吧。", "explanation": "“吗”已表示疑问，句末不能再接“吧”，“来了吗吧”不通。"}, {"text": "谢谢你吧。", "explanation": "表示感谢时不能用“吧”，“吧”表示建议或不确定，应直接说“谢谢你”。"}, {"text": "对不起吧。", "explanation": "道歉时不能用“吧”，“吧”表示不确定，应直接说“对不起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气冷了，我们多穿点衣服吧了。", "corrected_sentence": "天气冷了，我们多穿点衣服吧。", "error_description": "错误：语气助词“吧”后不能再加“了”，“衣服吧了”不通。正确：句末只用“吧”，写作“多穿点衣服吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天去动物园吧吧。", "corrected_sentence": "我们明天去动物园吧。", "error_description": "错误：句末只用一个“吧”，重复“吧吧”不通。正确：“我们明天去动物园吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
