INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85769, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“其”是指前面说到的那个人或东西，意思是“他的”“它的”。", "primary_collocate": null, "pronunciation": "qí", "ipa": "tɕʰi˧˥", "syllable_count": 1, "sentences": [{"text": "这家店很小，但其味道很好。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有名，其作者是一位老教授。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山不高，但其风景很美。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王工作很认真，大家都喜欢其做事的方法。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花很香，其颜色也很好看。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法很好，其作用很大。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市很大，其人口超过一千万。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司很老，其产品卖到很多国家。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我的朋友，我很了解其性格。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河很长，其水很干净。", "target_word": "其", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面代词：指前面提到的单个人或事物，相当于“他的”“它的”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85769, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "其", "is_correct": true, "explanation": "其（qí）是指代前文的书面代词，是本题的目标词。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是空气。"}, {"text": "习", "is_correct": false, "explanation": "xí 与 qí 声母不同（x/q），意思是学习。"}, {"text": "七", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是七。"}], "explanations": {"其": "其（qí）是指代前文的书面代词，是本题的目标词。", "起": "qǐ（第三声）与 qí（第二声）声调不同，意思是起来。", "气": "qì（第四声）与 qí（第二声）声调不同，意思是空气。", "习": "xí 与 qí 声母不同（x/q），意思是学习。", "七": "qī（第一声）与 qí（第二声）声调不同，意思是七。"}, "sentence_index": null, "correct_answer": "其"}, "level_3": {"options": [{"text": "其", "is_correct": true, "explanation": "“其”指代前文的“这家店”，相当于“它的”，与“味道很好”相符。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”指男性，不能指代店。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“谁”是疑问代词，不能指代前文提到的店。"}, {"text": "她", "is_correct": false, "explanation": "语义：“她”指女性，不能指代店。"}], "explanations": {"其": "“其”指代前文的“这家店”，相当于“它的”，与“味道很好”相符。", "他": "语义：“他”指男性，不能指代店。", "谁": "配价：“谁”是疑问代词，不能指代前文提到的店。", "她": "语义：“她”指女性，不能指代店。"}, "sentence_index": 0, "correct_answer": "其"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很高兴，其朋友都来了。", "explanation": "这里应该用〈我的〉。“其”指代前文提到的第三者，不能指代说话人自己。"}, {"text": "其价格很贵，我们没有买。", "explanation": "这里应该用〈这件东西的〉。“其”只能指代前文已出现的人或事物，句首的“其”前面没有所指对象，应直接说出名词。"}, {"text": "你很努力，其成绩很好。", "explanation": "这里应该用〈你的〉。“其”只指代第三者，不能指代听话人，此处应说“你的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85769, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "其", "is_correct": true, "explanation": "其（qí）是指代前文的书面代词，是本题的目标词。"}, {"text": "启", "is_correct": false, "explanation": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启。"}, {"text": "汽", "is_correct": false, "explanation": "qì（第四声）与 qí（第二声）声调不同，意思是汽车的汽。"}, {"text": "期", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，意思是时期。"}], "explanations": {"其": "其（qí）是指代前文的书面代词，是本题的目标词。", "启": "qǐ（第三声）与 qí（第二声）声调不同，意思是开启。", "汽": "qì（第四声）与 qí（第二声）声调不同，意思是汽车的汽。", "期": "qī（第一声）与 qí（第二声）声调不同，意思是时期。"}, "sentence_index": null, "correct_answer": "其"}, "level_3": {"options": [{"text": "其", "is_correct": true, "explanation": "“其”指代前文的“这个城市”，相当于“它的”，与“人口超过一千万”相符。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指说话人，不能指代城市。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”指说话人一方，不能指代城市。"}, {"text": "这", "is_correct": false, "explanation": "搭配：“这”不能直接修饰“人口”，要说“这个城市的人口”。"}], "explanations": {"其": "“其”指代前文的“这个城市”，相当于“它的”，与“人口超过一千万”相符。", "我": "语义：“我”指说话人，不能指代城市。", "咱们": "语义：“咱们”指说话人一方，不能指代城市。", "这": "搭配：“这”不能直接修饰“人口”，要说“这个城市的人口”。"}, "sentence_index": 6, "correct_answer": "其"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们都很忙，其工作也很多。", "explanation": "这里应该用〈我们的〉。“其”只指代第三者，不能指代说话人一方，此处应说“我们的”。"}, {"text": "其成绩很好，我们都很努力。", "explanation": "这里应该用〈我们的〉。“其”必须指代前文已出现的对象，句首的“其”前无所指，应直接说明是谁的成绩。"}, {"text": "你们常常加班，其压力很大。", "explanation": "这里应该用〈你们的〉。“其”只指代第三者，不能指代听话人一方，此处应说“你们的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家很有名，这其作品很多人喜欢。", "corrected_sentence": "这位画家很有名，其作品很多人喜欢。", "error_description": "错误：“其”前不能再加指示词“这”。正确说法是“其作品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座山很高，山其顶很冷。", "corrected_sentence": "这座山很高，其山顶很冷。", "error_description": "错误：“其”不能插在名词中间。正确说法是“其山顶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
