INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85771, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "“该”是说应当这样做。", "primary_collocate": null, "pronunciation": "gāi", "ipa": "kaɪ˥", "syllable_count": 1, "sentences": [{"text": "你累了，该休息了。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子该睡觉了。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不该骂他。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，你该洗碗了。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们该走了，已经很晚了。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病了就该去看医生。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做错了，该对你说对不起。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，你该多穿衣服。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不该让妈妈知道。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了十点，我们该下班了。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不该", "label": "否定"}, {"form": "应该", "label": "复合"}], "register": "口语", "sense_fingerprint": "表示应当这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85771, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "该", "is_correct": true, "explanation": "正确答案。“该”读 gāi（第一声），表示应当这样做。"}, {"text": "盖", "is_correct": false, "explanation": "gài（第四声）与 gāi（第一声）声调不同，意思是覆盖、盖上。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 gāi（第一声）声调不同，意思是改变。"}, {"text": "开", "is_correct": false, "explanation": "kāi 与 gāi 声母不同（送气的 k 与不送气的 g），意思是打开。"}, {"text": "猜", "is_correct": false, "explanation": "cāi 与 gāi 声母不同（送气的 c 与不送气的 g），意思是猜测。"}], "explanations": {"该": "正确答案。“该”读 gāi（第一声），表示应当这样做。", "盖": "gài（第四声）与 gāi（第一声）声调不同，意思是覆盖、盖上。", "改": "gǎi（第三声）与 gāi（第一声）声调不同，意思是改变。", "开": "kāi 与 gāi 声母不同（送气的 k 与不送气的 g），意思是打开。", "猜": "cāi 与 gāi 声母不同（送气的 c 与不送气的 g），意思是猜测。"}, "sentence_index": null, "correct_answer": "该"}, "level_3": {"options": [{"text": "该", "is_correct": true, "explanation": "正确答案。“该”表示应当这样做，与“累了”的情况相合，句意是该休息了。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有勇气，与“累了”的状态不合。"}, {"text": "会", "is_correct": false, "explanation": "语义：“会”表示将要或推测，句子要说的是应当休息，不是推测。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：“愿意”表示主观意愿，与“累了”需要休息的客观情况不合。"}], "explanations": {"该": "正确答案。“该”表示应当这样做，与“累了”的情况相合，句意是该休息了。", "敢": "语义：“敢”表示有勇气，与“累了”的状态不合。", "会": "语义：“会”表示将要或推测，句子要说的是应当休息，不是推测。", "愿意": "语义：“愿意”表示主观意愿，与“累了”需要休息的客观情况不合。"}, "sentence_index": 0, "correct_answer": "该"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他该的书很多。", "explanation": "“该”是情态动词，不能直接修饰名词，“该的”结构不成立。"}, {"text": "这块石头该会哭。", "explanation": "“该”表示应当这样做，石头不能哭，这里用“该”不符合本义。"}, {"text": "这张桌子该吃饭了。", "explanation": "“该”表示应当这样做，这里动作的主体是桌子，搭配不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85771, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "该", "is_correct": true, "explanation": "正确答案。“该”读 gāi（第一声），表示应当这样做。"}, {"text": "概", "is_correct": false, "explanation": "gài（第四声）与 gāi（第一声）声调不同，意思是大概。"}, {"text": "灾", "is_correct": false, "explanation": "zāi 与 gāi 声母不同（z 与 g），意思是灾难。"}, {"text": "摘", "is_correct": false, "explanation": "zhāi 与 gāi 声母不同（zh 与 g），意思是摘取。"}, {"text": "哎", "is_correct": false, "explanation": "āi 没有声母，与 gāi 的声母不同，意思是表示感叹的“哎”。"}], "explanations": {"该": "正确答案。“该”读 gāi（第一声），表示应当这样做。", "概": "gài（第四声）与 gāi（第一声）声调不同，意思是大概。", "灾": "zāi 与 gāi 声母不同（z 与 g），意思是灾难。", "摘": "zhāi 与 gāi 声母不同（zh 与 g），意思是摘取。", "哎": "āi 没有声母，与 gāi 的声母不同，意思是表示感叹的“哎”。"}, "sentence_index": null, "correct_answer": "该"}, "level_3": {"options": [{"text": "该", "is_correct": true, "explanation": "正确答案。“该”表示应当这样做，与“做错了”的语境相合，句意是应当道歉。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”是表示被动的介词，后面要接施事，“被对你说对不起”不成立。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句子说的是应当道歉，并无转折，语义不合。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量，句子说的是应当道歉，与胆量无关。"}], "explanations": {"该": "正确答案。“该”表示应当这样做，与“做错了”的语境相合，句意是应当道歉。", "被": "语法：“被”是表示被动的介词，后面要接施事，“被对你说对不起”不成立。", "却": "语义：“却”表示转折，句子说的是应当道歉，并无转折，语义不合。", "敢": "语义：“敢”表示有胆量，句子说的是应当道歉，与胆量无关。"}, "sentence_index": 6, "correct_answer": "该"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块饼干该很多，你别抢。", "explanation": "“该”后不能直接接数量短语作谓语，此处用法不成立。"}, {"text": "我们该了吃饭。", "explanation": "“该”是情态动词，后面直接接动词，不能带“了”再接动词。"}, {"text": "我们走该了。", "explanation": "“该”作情态动词须位于动词之前，此处语序颠倒，不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没该迟到。", "corrected_sentence": "他不该迟到。", "error_description": "错误：“没该”；正确：“不该”。“该”表示应当，否定应当要用“不该”，不说“没该”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
