INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85772, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "情态动词，表示应当、理应。", "primary_collocate": null, "pronunciation": "gāi", "ipa": "kaɪ˥", "syllable_count": 1, "sentences": [{"text": "已经八点了，你该起床了。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友不该一个人出门。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我看完了，该还给图书馆了。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天该做什么作业？", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个钱你不该花。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都来了，我们该开始了。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，不该去上班。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天考试，你今晚该早点睡。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友来了，我该做点好吃的。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你该给妈妈打电话了。", "target_word": "该", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不该", "label": "否定"}, {"form": "应该", "label": "复合"}], "register": "口语", "sense_fingerprint": "表示应当、理应，常说该……了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85772, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "该", "is_correct": true, "explanation": "正确答案。“该”读 gāi（第一声），表示应当、理应。"}, {"text": "盖", "is_correct": false, "explanation": "gài（第四声）与 gāi（第一声）声调不同，意思是覆盖、盖上。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 gāi（第一声）声调不同，意思是改变。"}, {"text": "开", "is_correct": false, "explanation": "kāi 与 gāi 声母不同（送气的 k 与不送气的 g），意思是打开。"}, {"text": "猜", "is_correct": false, "explanation": "cāi 与 gāi 声母不同（送气的 c 与不送气的 g），意思是猜测。"}], "explanations": {"该": "正确答案。“该”读 gāi（第一声），表示应当、理应。", "盖": "gài（第四声）与 gāi（第一声）声调不同，意思是覆盖、盖上。", "改": "gǎi（第三声）与 gāi（第一声）声调不同，意思是改变。", "开": "kāi 与 gāi 声母不同（送气的 k 与不送气的 g），意思是打开。", "猜": "cāi 与 gāi 声母不同（送气的 c 与不送气的 g），意思是猜测。"}, "sentence_index": null, "correct_answer": "该"}, "level_3": {"options": [{"text": "该", "is_correct": true, "explanation": "正确答案。“该”表示应当，与“已经八点了”的时间提示相合，句意是该起床了。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示重复，与“已经八点了”的时间提示不合。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，修饰形容词，不能直接修饰“起床”。"}, {"text": "敢", "is_correct": false, "explanation": "搭配：“敢”后接需要勇气的行为，“敢起床”搭配不通。"}], "explanations": {"该": "正确答案。“该”表示应当，与“已经八点了”的时间提示相合，句意是该起床了。", "又": "语义：“又”表示重复，与“已经八点了”的时间提示不合。", "很": "语法：“很”是程度副词，修饰形容词，不能直接修饰“起床”。", "敢": "搭配：“敢”后接需要勇气的行为，“敢起床”搭配不通。"}, "sentence_index": 0, "correct_answer": "该"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他该的书很多。", "explanation": "“该”是情态动词，不能直接修饰名词，“该的”结构不成立。"}, {"text": "这块石头该会哭。", "explanation": "“该”表示应当，这里的主语是石头，石头不能哭，用“该”表达“应当会哭”不符合本义。"}, {"text": "这张桌子该吃饭了。", "explanation": "“该”表示应当，这里动作“吃饭”的施事是桌子，搭配不成立，与“应当”的本义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85772, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "该", "is_correct": true, "explanation": "正确答案。“该”读 gāi（第一声），表示应当、理应。"}, {"text": "概", "is_correct": false, "explanation": "gài（第四声）与 gāi（第一声）声调不同，意思是大概。"}, {"text": "灾", "is_correct": false, "explanation": "zāi 与 gāi 声母不同（z 与 g），意思是灾难。"}, {"text": "摘", "is_correct": false, "explanation": "zhāi 与 gāi 声母不同（zh 与 g），意思是摘取。"}, {"text": "哎", "is_correct": false, "explanation": "āi 没有声母，与 gāi 的声母不同，意思是表示感叹的“哎”。"}], "explanations": {"该": "正确答案。“该”读 gāi（第一声），表示应当、理应。", "概": "gài（第四声）与 gāi（第一声）声调不同，意思是大概。", "灾": "zāi 与 gāi 声母不同（z 与 g），意思是灾难。", "摘": "zhāi 与 gāi 声母不同（zh 与 g），意思是摘取。", "哎": "āi 没有声母，与 gāi 的声母不同，意思是表示感叹的“哎”。"}, "sentence_index": null, "correct_answer": "该"}, "level_3": {"options": [{"text": "该", "is_correct": true, "explanation": "正确答案。“该”表示应当，“不该”与“生病了”一起表示不应去上班。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”表示被动，后面要接施事，“不被去上班”不成立。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”后要接宾语，“不把去上班”不成立。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”修饰形容词，“不很去上班”不成立。"}], "explanations": {"该": "正确答案。“该”表示应当，“不该”与“生病了”一起表示不应去上班。", "被": "语法：“被”表示被动，后面要接施事，“不被去上班”不成立。", "把": "语法：“把”后要接宾语，“不把去上班”不成立。", "很": "语法：“很”修饰形容词，“不很去上班”不成立。"}, "sentence_index": 6, "correct_answer": "该"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在教室里哭该了。", "explanation": "“该”作情态动词须位于动词之前，此处语序颠倒，不成立。"}, {"text": "今天的作业我做完该了吗？", "explanation": "“该”须位于动词之前，此处语序颠倒，不成立。"}, {"text": "这件事我负责该，你不用管。", "explanation": "“该”须位于动词之前，此处语序颠倒，不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你没该吃这么多。", "corrected_sentence": "你不该吃这么多。", "error_description": "错误：“没该”；正确：“不该”。“该”表示应当，否定应当要用“不该”，不说“没该”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我们的该出发了。", "corrected_sentence": "明天我们该出发了。", "error_description": "错误：“我们的该出发”；正确：“我们该出发”。“该”是情态动词，应直接放在主语后、动词前，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
