INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85775, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“向”是说动作、身体或脸朝着某个方向。", "primary_collocate": null, "pronunciation": "xiàng", "ipa": "ɕiɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "请你向左转，再向前走。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向窗外看了一眼。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花儿都向着太阳开放。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟向天空飞去。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们向山上跑。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向我们走过来。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子向北开了。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请向右看，那是图书馆。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向门口看了看。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们向着海边慢慢走去。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "向着", "label": "体标"}], "register": "中性", "sense_fingerprint": "介词，表示动作、身体或脸朝着某个方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85775, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向", "is_correct": true, "explanation": "正确答案：向（xiàng），即本词。"}, {"text": "香", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香。"}, {"text": "想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是想。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同（-n 与 -ng），意思是现在。"}, {"text": "降", "is_correct": false, "explanation": "jiàng 与 xiàng 声母不同（j 与 x），意思是降低。"}, {"text": "箱", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng 声调不同，意思是箱子。"}, {"text": "线", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同，意思是线。"}], "explanations": {"向": "正确答案：向（xiàng），即本词。", "香": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香。", "想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是想。", "现": "xiàn 与 xiàng 韵母不同（-n 与 -ng），意思是现在。", "降": "jiàng 与 xiàng 声母不同（j 与 x），意思是降低。", "箱": "xiāng（第一声）与 xiàng 声调不同，意思是箱子。", "线": "xiàn 与 xiàng 韵母不同，意思是线。"}, "sentence_index": null, "correct_answer": "向"}, "level_3": {"options": [{"text": "向", "is_correct": true, "explanation": "向：介词，引出朝向的方向，“向左转”表示朝左边转，符合句意。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”引出对象，不与“转”搭配，“对左转”不成立。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者，“左转”没有接受者，句子不成立。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替他人，与转向无关，句意不通。"}], "explanations": {"向": "向：介词，引出朝向的方向，“向左转”表示朝左边转，符合句意。", "对": "搭配：“对”引出对象，不与“转”搭配，“对左转”不成立。", "给": "配价：“给”需要接受者，“左转”没有接受者，句子不成立。", "替": "语义：“替”表示代替他人，与转向无关，句意不通。"}, "sentence_index": 0, "correct_answer": "向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们向老师的要求去做。", "explanation": "这里应该用〈按照〉，表示依据。“向”引出朝向或对象，不表示依据别人的要求去做事。"}, {"text": "我向弟弟一起看电影。", "explanation": "这里应该用〈跟〉，表示与某人一起。“向”引出朝向或对象，不表示伴随关系。"}, {"text": "这封信向北京寄来。", "explanation": "这里应该用〈从〉，表示起点。“向”表示朝向终点，与“寄来”已说明的来源方向相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85775, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "向", "is_correct": true, "explanation": "正确答案：向（xiàng），即本词。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是乡村。"}, {"text": "响", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是响声。"}, {"text": "县", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同（-n 与 -ng），意思是县。"}, {"text": "限", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同，意思是限制。"}, {"text": "酱", "is_correct": false, "explanation": "jiàng 与 xiàng 声母不同（j 与 x），意思是酱料。"}, {"text": "详", "is_correct": false, "explanation": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。"}], "explanations": {"向": "正确答案：向（xiàng），即本词。", "乡": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是乡村。", "响": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是响声。", "县": "xiàn 与 xiàng 韵母不同（-n 与 -ng），意思是县。", "限": "xiàn 与 xiàng 韵母不同，意思是限制。", "酱": "jiàng 与 xiàng 声母不同（j 与 x），意思是酱料。", "详": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。"}, "sentence_index": null, "correct_answer": "向"}, "level_3": {"options": [{"text": "向", "is_correct": true, "explanation": "向：介词，引出朝向的方向，“车子向北开了”表示朝北方开，符合句意。"}, {"text": "跟", "is_correct": false, "explanation": "搭配：“跟”表示与某人一起，“车子跟北开”不成立。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示为了或替代，与行进方向无关，句意不通。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”要求带处置对象，“车子把北开”不成立。"}], "explanations": {"向": "向：介词，引出朝向的方向，“车子向北开了”表示朝北方开，符合句意。", "跟": "搭配：“跟”表示与某人一起，“车子跟北开”不成立。", "为": "语义：“为”表示为了或替代，与行进方向无关，句意不通。", "把": "配价：“把”要求带处置对象，“车子把北开”不成立。"}, "sentence_index": 6, "correct_answer": "向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我向妈妈一起去超市。", "explanation": "这里应该用〈跟〉，表示与某人一起。“向”表示朝着某个方向，不表示伴随。"}, {"text": "他向黑板上写字。", "explanation": "这里应该用〈在〉，表示动作发生的地点。“向”引出朝向的对象，不表示在某处写字。"}, {"text": "我向父母去开会。", "explanation": "这里应该用〈替〉，表示代替。“向”不能表示代替他人去做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她给东边走去。", "corrected_sentence": "她向东边走去。", "error_description": "错误：“给东边走去”；正确：“向东边走去”。“给”引出接受者，不能表示方向；表示动作朝着某个方向要用“向”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把西边跑了。", "corrected_sentence": "他向西边跑了。", "error_description": "错误：“把西边跑了”；正确：“向西边跑了”。“把”引出处置对象，不能表示方向；表示朝着某个方向跑要用“向”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
