INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85776, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，引出动作所对的人或事物。", "primary_collocate": null, "pronunciation": "xiàng", "ipa": "ɕiɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我想向老师问好。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向朋友借了一本书。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明向妈妈要钱买书。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请向大家介绍一下你自己。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要向你道歉。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该向他学习。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向经理请了三天假。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生向老师问了一个问题。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向警察说明了情况。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我向公司提出了新办法。", "target_word": "向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "介词，引出动作所对的人，如向某人问好、借东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85776, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向", "is_correct": true, "explanation": "正确答案：向（xiàng），即本词。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是乡村。"}, {"text": "响", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是响声。"}, {"text": "县", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同（-n 与 -ng），意思是县。"}, {"text": "酱", "is_correct": false, "explanation": "jiàng 与 xiàng 声母不同（j 与 x），意思是酱料。"}, {"text": "详", "is_correct": false, "explanation": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。"}, {"text": "限", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同，意思是限制。"}], "explanations": {"向": "正确答案：向（xiàng），即本词。", "乡": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是乡村。", "响": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是响声。", "县": "xiàn 与 xiàng 韵母不同（-n 与 -ng），意思是县。", "酱": "jiàng 与 xiàng 声母不同（j 与 x），意思是酱料。", "详": "xiáng（第二声）与 xiàng（第四声）声调不同，意思是详细。", "限": "xiàn 与 xiàng 韵母不同，意思是限制。"}, "sentence_index": null, "correct_answer": "向"}, "level_3": {"options": [{"text": "向", "is_correct": true, "explanation": "向：介词，引出动作所对的人，“我想向老师问好”表示对老师问好，符合句意。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点，不能引出问候的对象，句意不通。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”要求带处置对象，“问好”不能处置人，句子不成立。"}, {"text": "为", "is_correct": false, "explanation": "搭配：“为”表示为了或替代，“为老师问好”不通顺，不是常用搭配。"}], "explanations": {"向": "向：介词，引出动作所对的人，“我想向老师问好”表示对老师问好，符合句意。", "从": "语义：“从”表示起点，不能引出问候的对象，句意不通。", "把": "配价：“把”要求带处置对象，“问好”不能处置人，句子不成立。", "为": "搭配：“为”表示为了或替代，“为老师问好”不通顺，不是常用搭配。"}, "sentence_index": 0, "correct_answer": "向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向北京住了三年。", "explanation": "这里应该用〈在〉，表示居住的地点。“向”引出方向或对象，不能引出居住的地点。"}, {"text": "我向你的成绩很满意。", "explanation": "这里应该用〈对〉，引出满意的对象。“满意”的对象不用“向”引出，“向你的成绩满意”不成立。"}, {"text": "他向这个标准修改了作文。", "explanation": "这里应该用〈按照〉，表示依据。“向”引出朝向或对象，不表示依据标准去做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85776, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "向", "is_correct": true, "explanation": "正确答案：向（xiàng），即本词。"}, {"text": "香", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香。"}, {"text": "想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是想。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同（-n 与 -ng），意思是现在。"}, {"text": "降", "is_correct": false, "explanation": "jiàng 与 xiàng 声母不同（j 与 x），意思是降低。"}, {"text": "箱", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng 声调不同，意思是箱子。"}, {"text": "线", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同，意思是线。"}], "explanations": {"向": "正确答案：向（xiàng），即本词。", "香": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是香。", "想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是想。", "现": "xiàn 与 xiàng 韵母不同（-n 与 -ng），意思是现在。", "降": "jiàng 与 xiàng 声母不同（j 与 x），意思是降低。", "箱": "xiāng（第一声）与 xiàng 声调不同，意思是箱子。", "线": "xiàn 与 xiàng 韵母不同，意思是线。"}, "sentence_index": null, "correct_answer": "向"}, "level_3": {"options": [{"text": "向", "is_correct": true, "explanation": "向：介词，引出动作所对的对象，“她向经理请假”表示对经理提出请假，符合句意。"}, {"text": "由", "is_correct": false, "explanation": "语义：“由”表示来源或施事，“由经理请假”语义不通。"}, {"text": "凭", "is_correct": false, "explanation": "语义：“凭”表示依据，与请假的对象不符，句意不通。"}, {"text": "按", "is_correct": false, "explanation": "搭配：“按”表示依照，“按经理请假”搭配不当，不是常用说法。"}], "explanations": {"向": "向：介词，引出动作所对的对象，“她向经理请假”表示对经理提出请假，符合句意。", "由": "语义：“由”表示来源或施事，“由经理请假”语义不通。", "凭": "语义：“凭”表示依据，与请假的对象不符，句意不通。", "按": "搭配：“按”表示依照，“按经理请假”搭配不当，不是常用说法。"}, "sentence_index": 6, "correct_answer": "向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我向他一起去北京。", "explanation": "这里应该用〈跟〉，表示与某人一起。“向”不表示伴随关系，此处用法不对。"}, {"text": "这封信向北京寄来。", "explanation": "这里应该用〈从〉，表示起点。“向”表示朝向，不能表示信件的来源。"}, {"text": "我向父母去开会。", "explanation": "这里应该用〈替〉，表示代替。“向”不能表示代替他人去做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在我要了一张地图。", "corrected_sentence": "他向我要了一张地图。", "error_description": "错误：“在我要了”；正确：“向我要了”。“在”引出地点，不能引出索要的对象；引出动作所对的人要用“向”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想把老师请假。", "corrected_sentence": "我想向老师请假。", "error_description": "错误：“把老师请假”；正确：“向老师请假”。“把”引出处置对象，“请假”不能处置老师；引出请假的对象要用“向”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
