INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85777, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "“前”是说脸朝的这一边，或者时间比较早。", "primary_collocate": null, "pronunciation": "qián", "ipa": "tɕʰjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "我家门前有一棵大树。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请往前走，不要停。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向前看，别回头。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭前要先洗手。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三年前我住在上海。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前他喜欢喝杯牛奶。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店前站着一个小孩。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八点前请你到学校。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校前有一家小书店。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向前走了两步。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "方位词，脸朝的一边；时间较早", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa09a39c-1dc4-4f09-8ce9-0310badb768d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85777, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前", "is_correct": true, "explanation": "正确答案：前（qián，第二声），指脸朝的一边，或时间较早。"}, {"text": "千", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是数字“一千”。"}, {"text": "浅", "is_correct": false, "explanation": "qiǎn（第三声）与 qián（第二声）声调不同，意思是“不深”。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn（第四声）与 qián（第二声）声调不同，意思是“欠债”。"}, {"text": "墙", "is_correct": false, "explanation": "qiáng 与 qián 韵母不同（ang 与 an），声调相同，意思是墙壁。"}], "explanations": {"前": "正确答案：前（qián，第二声），指脸朝的一边，或时间较早。", "千": "qiān（第一声）与 qián（第二声）声调不同，意思是数字“一千”。", "浅": "qiǎn（第三声）与 qián（第二声）声调不同，意思是“不深”。", "欠": "qiàn（第四声）与 qián（第二声）声调不同，意思是“欠债”。", "墙": "qiáng 与 qián 韵母不同（ang 与 an），声调相同，意思是墙壁。"}, "sentence_index": null, "correct_answer": "前"}, "level_3": {"options": [{"text": "前", "is_correct": true, "explanation": "正确答案：“门前”指门的正前方，与“有一棵大树”搭配自然。"}, {"text": "上", "is_correct": false, "explanation": "语义：“门上”指门的表面，一棵大树不能立在门上。"}, {"text": "左", "is_correct": false, "explanation": "搭配：“左”单独接在“门”后作处所不自然，要说“门左边”。"}, {"text": "中", "is_correct": false, "explanation": "搭配：“中”单独接在“门”后不成立，要说“门中间”。"}], "explanations": {"前": "正确答案：“门前”指门的正前方，与“有一棵大树”搭配自然。", "上": "语义：“门上”指门的表面，一棵大树不能立在门上。", "左": "搭配：“左”单独接在“门”后作处所不自然，要说“门左边”。", "中": "搭配：“中”单独接在“门”后不成立，要说“门中间”。"}, "sentence_index": 0, "correct_answer": "前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃完饭前去散步了。", "explanation": "这里应该用〈后〉。“吃完饭”之后才去散步，用“前”表示较早，与先后顺序相反。"}, {"text": "汽车往前退，撞到了树。", "explanation": "这里应该用〈后〉。“后退”指向后移动，“往前”与“退”的方向相反。"}, {"text": "他先洗了澡，洗澡前又去吃了饭。", "explanation": "这里应该用〈后〉。“先洗了澡”之后才去吃饭，用“前”与先后顺序相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85777, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "前", "is_correct": true, "explanation": "正确答案：前（qián，第二声），指脸朝的一边，或时间较早。"}, {"text": "签", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是“签字”。"}, {"text": "强", "is_correct": false, "explanation": "qiáng 与 qián 韵母不同（ang 与 an），声调相同，意思是“强大”。"}, {"text": "歉", "is_correct": false, "explanation": "qiàn（第四声）与 qián（第二声）声调不同，意思是“抱歉”。"}, {"text": "勤", "is_correct": false, "explanation": "qín 与 qián 韵母不同（in 与 ian），声调相同，意思是“勤奋”。"}, {"text": "铅", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是“铅”。"}], "explanations": {"前": "正确答案：前（qián，第二声），指脸朝的一边，或时间较早。", "签": "qiān（第一声）与 qián（第二声）声调不同，意思是“签字”。", "强": "qiáng 与 qián 韵母不同（ang 与 an），声调相同，意思是“强大”。", "歉": "qiàn（第四声）与 qián（第二声）声调不同，意思是“抱歉”。", "勤": "qín 与 qián 韵母不同（in 与 ian），声调相同，意思是“勤奋”。", "铅": "qiān（第一声）与 qián（第二声）声调不同，意思是“铅”。"}, "sentence_index": null, "correct_answer": "前"}, "level_3": {"options": [{"text": "前", "is_correct": true, "explanation": "正确答案：“商店前”指店门外的正前方，与“站着一个小孩”搭配自然。"}, {"text": "面", "is_correct": false, "explanation": "语法：“面”不能单独接在“商店”后作处所，要说“前面”。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”是助词，不能接在“商店”后作处所，句子不通。"}, {"text": "的", "is_correct": false, "explanation": "语法：“商店的”后不能直接接“站着”作谓语，句子不通。"}], "explanations": {"前": "正确答案：“商店前”指店门外的正前方，与“站着一个小孩”搭配自然。", "面": "语法：“面”不能单独接在“商店”后作处所，要说“前面”。", "了": "语法：“了”是助词，不能接在“商店”后作处所，句子不通。", "的": "语法：“商店的”后不能直接接“站着”作谓语，句子不通。"}, "sentence_index": 6, "correct_answer": "前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先写完了作业，写作业前又去看了电视。", "explanation": "这里应该用〈后〉。“先写完了作业”之后才看电视，用“前”与先后顺序相反。"}, {"text": "我比你前到了学校。", "explanation": "这里应该用〈早〉。比较到达时间的先后要说“比你早到”，“前”不能这样作状语。"}, {"text": "他正在写作业，前妈妈在做饭。", "explanation": "这里应该用〈同时〉。“前”表示较早的时间或方位，不能表示两件事同时进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他坐在桌子前前写作业。", "corrected_sentence": "他坐在桌子前写作业。", "error_description": "错误形式：“坐在桌子前前写作业”。正确形式：“坐在桌子前写作业”。“前”只需出现一次，句中重复使用不成立，错误直接涉及目标词“前”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司前前停着一辆车。", "corrected_sentence": "公司前停着一辆车。", "error_description": "错误形式：“公司前前停着一辆车”。正确形式：“公司前停着一辆车”。“前”只需出现一次，重复使用不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
