INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85778, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "方位词，表示正面的位置，或指较早的时间，与“后”相对。", "primary_collocate": null, "pronunciation": "qián", "ipa": "tɕʰjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "房子前有一条小河。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在桌子前看书。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来中国前，我没学过汉语。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年前这里没有地铁。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "往前开一百米，然后左转。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前有河，后有山，风景很好。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走到门前，打开了灯。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前我每天复习。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个月前我买了这本书。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请站在黄线前，别过去。", "target_word": "前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "方位词，正面的位置；较早的时间，与后相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa09a39c-1dc4-4f09-8ce9-0310badb768d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85778, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前", "is_correct": true, "explanation": "正确答案：前（qián，第二声），指正面的位置，或较早的时间。"}, {"text": "浅", "is_correct": false, "explanation": "qiǎn（第三声）与 qián（第二声）声调不同，意思是“不深”。"}, {"text": "墙", "is_correct": false, "explanation": "qiáng 与 qián 韵母不同（ang 与 an），声调相同，意思是墙壁。"}, {"text": "勤", "is_correct": false, "explanation": "qín 与 qián 韵母不同（in 与 ian），声调相同，意思是“勤奋”。"}, {"text": "铅", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是“铅”。"}], "explanations": {"前": "正确答案：前（qián，第二声），指正面的位置，或较早的时间。", "浅": "qiǎn（第三声）与 qián（第二声）声调不同，意思是“不深”。", "墙": "qiáng 与 qián 韵母不同（ang 与 an），声调相同，意思是墙壁。", "勤": "qín 与 qián 韵母不同（in 与 ian），声调相同，意思是“勤奋”。", "铅": "qiān（第一声）与 qián（第二声）声调不同，意思是“铅”。"}, "sentence_index": null, "correct_answer": "前"}, "level_3": {"options": [{"text": "前", "is_correct": true, "explanation": "正确答案：“房子前”指房子的正前方，与“有一条小河”搭配自然。"}, {"text": "顶上", "is_correct": false, "explanation": "语义：“房子顶上”指房顶，一条小河不会流在房顶上。"}, {"text": "楼上", "is_correct": false, "explanation": "语义：“房子楼上”指楼层的上部，一条小河不会在楼上。"}, {"text": "的", "is_correct": false, "explanation": "语法：“房子的”后不能直接接动词“有”作谓语，句子不通。"}], "explanations": {"前": "正确答案：“房子前”指房子的正前方，与“有一条小河”搭配自然。", "顶上": "语义：“房子顶上”指房顶，一条小河不会流在房顶上。", "楼上": "语义：“房子楼上”指楼层的上部，一条小河不会在楼上。", "的": "语法：“房子的”后不能直接接动词“有”作谓语，句子不通。"}, "sentence_index": 0, "correct_answer": "前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看完电影前回了家。", "explanation": "这里应该用〈后〉。看完电影之后才回家，用“前”表示较早，与先后顺序相反。"}, {"text": "我们先去买了菜，买菜前又去做了饭。", "explanation": "这里应该用〈后〉。“先去买了菜”之后才做饭，用“前”与先后顺序相反。"}, {"text": "他先睡了午觉，睡午觉前又去跑了步。", "explanation": "这里应该用〈后〉。“先睡了午觉”之后才去跑步，用“前”与先后顺序相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85778, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "前", "is_correct": true, "explanation": "正确答案：前（qián，第二声），指正面的位置，或较早的时间。"}, {"text": "千", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是数字“一千”。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn（第四声）与 qián（第二声）声调不同，意思是“欠债”。"}, {"text": "强", "is_correct": false, "explanation": "qiáng 与 qián 韵母不同（ang 与 an），声调相同，意思是“强大”。"}, {"text": "签", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，意思是“签字”。"}], "explanations": {"前": "正确答案：前（qián，第二声），指正面的位置，或较早的时间。", "千": "qiān（第一声）与 qián（第二声）声调不同，意思是数字“一千”。", "欠": "qiàn（第四声）与 qián（第二声）声调不同，意思是“欠债”。", "强": "qiáng 与 qián 韵母不同（ang 与 an），声调相同，意思是“强大”。", "签": "qiān（第一声）与 qián（第二声）声调不同，意思是“签字”。"}, "sentence_index": null, "correct_answer": "前"}, "level_3": {"options": [{"text": "前", "is_correct": true, "explanation": "正确答案：“门前”指门的正前方，与“走到”搭配自然。"}, {"text": "上", "is_correct": false, "explanation": "语义：“走到门上”指走到门的表面，与后文开灯的动作不合常理。"}, {"text": "下", "is_correct": false, "explanation": "搭配：“门下”不单独作处所，要说“门下面”。"}, {"text": "顶上", "is_correct": false, "explanation": "语义：“门顶上”指门的最高处，走到那里再开灯不合常理。"}], "explanations": {"前": "正确答案：“门前”指门的正前方，与“走到”搭配自然。", "上": "语义：“走到门上”指走到门的表面，与后文开灯的动作不合常理。", "下": "搭配：“门下”不单独作处所，要说“门下面”。", "顶上": "语义：“门顶上”指门的最高处，走到那里再开灯不合常理。"}, "sentence_index": 6, "correct_answer": "前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先吃了饭，吃饭前又去洗了手。", "explanation": "这里应该用〈后〉。“先吃了饭”之后才去洗手，用“前”与先后顺序相反。"}, {"text": "他比我前到了车站。", "explanation": "这里应该用〈早〉。比较到达时间的先后要说“比我早到”，“前”不能这样作状语。"}, {"text": "会议三天前就结束了，我们明天还要参加。", "explanation": "这里应该用〈后〉。“三天前就结束了”与“明天还要参加”矛盾，应说“三天后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDE