INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85779, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“啊”放在话的后面，让话听起来更亲切，或者表示吃惊。", "primary_collocate": null, "pronunciation": "a", "ipa": "a", "syllable_count": 1, "sentences": [{"text": "你好啊，好久不见！", "target_word": "啊", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "快来吃饭啊。", "target_word": "啊", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你怎么才来啊？", "target_word": "啊", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "是你啊，我没看见你。", "target_word": "啊", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你去哪儿啊？", "target_word": "啊", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "慢点走啊。", "target_word": "啊", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这么多人啊！", "target_word": "啊", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你也在这儿啊？", "target_word": "啊", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别忘了带伞啊。", "target_word": "啊", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已经走了啊？", "target_word": "啊", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在句末，使语气亲切或表示吃惊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ac6ae9e-65f2-4cd8-afbe-fbecadfb9dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85779, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啊", "is_correct": true, "explanation": "正确答案。语气助词“啊”，读作 a。"}, {"text": "哎", "is_correct": false, "explanation": "哎读 āi，比 a 多了韵尾 i，是叹词，读音不同。"}, {"text": "哈", "is_correct": false, "explanation": "哈读 hā，比 a 多了声母 h，多指笑声或叹词，读音不同。"}, {"text": "吗", "is_correct": false, "explanation": "吗读 ma，比 a 多了声母 m，是疑问语气词，读音不同。"}], "explanations": {"啊": "正确答案。语气助词“啊”，读作 a。", "哎": "哎读 āi，比 a 多了韵尾 i，是叹词，读音不同。", "哈": "哈读 hā，比 a 多了声母 h，多指笑声或叹词，读音不同。", "吗": "吗读 ma，比 a 多了声母 m，是疑问语气词，读音不同。"}, "sentence_index": null, "correct_answer": "啊"}, "level_3": {"options": [{"text": "啊", "is_correct": true, "explanation": "正确。“啊”放在问候语后，使话语听起来更亲切。"}, {"text": "呢", "is_correct": false, "explanation": "语义：“呢”表示追问或持续，用在问候语后语义不通。"}, {"text": "罢", "is_correct": false, "explanation": "语域：“罢”是文言语气词，口语问候中不用。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，与口语问候的语气不合。"}], "explanations": {"啊": "正确。“啊”放在问候语后，使话语听起来更亲切。", "呢": "语义：“呢”表示追问或持续，用在问候语后语义不通。", "罢": "语域：“罢”是文言语气词，口语问候中不用。", "矣": "语域：“矣”是文言语气词，与口语问候的语气不合。"}, "sentence_index": 0, "correct_answer": "啊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "根据本办法第五条，申请人须于十日内提交相关材料啊。", "explanation": "这里误把〈啊〉的口语语气用于法规条文，应改用书面陈述，去掉“啊”。"}, {"text": "这件事你知道吗啊？", "explanation": "这里“吗”和“啊”不能同时用在句末，应去掉“啊”。"}, {"text": "本研究的结论已经得到验证啊，具有重要的学术价值。", "explanation": "这里误把〈啊〉的口语语气用于学术结论，书面陈述不用“啊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id =