INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85780, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "啊", "is_correct": true, "explanation": "正确答案。语气助词“啊”，读作 a。"}, {"text": "哎", "is_correct": false, "explanation": "哎读 āi，比 a 多了韵尾 i，是叹词，读音不同。"}, {"text": "哈", "is_correct": false, "explanation": "哈读 hā，比 a 多了声母 h，多指笑声或叹词，读音不同。"}, {"text": "吗", "is_correct": false, "explanation": "吗读 ma，比 a 多了声母 m，是疑问语气词，读音不同。"}], "explanations": {"啊": "正确答案。语气助词“啊”，读作 a。", "哎": "哎读 āi，比 a 多了韵尾 i，是叹词，读音不同。", "哈": "哈读 hā，比 a 多了声母 h，多指笑声或叹词，读音不同。", "吗": "吗读 ma，比 a 多了声母 m，是疑问语气词，读音不同。"}, "sentence_index": null, "correct_answer": "啊"}, "level_3": {"options": [{"text": "啊", "is_correct": true, "explanation": "正确。“啊”放在感叹句末，表示赞叹。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示提问，不表示赞叹，与感叹句的语气不合。"}, {"text": "罢", "is_correct": false, "explanation": "语域：“罢”是文言语气词，口语赞叹中不用。"}, {"text": "吧", "is_correct": false, "explanation": "语义：“吧”表示推测或商量，不表示赞叹，与“多好”的感叹语气不合。"}], "explanations": {"啊": "正确。“啊”放在感叹句末，表示赞叹。", "吗": "语义：“吗”表示提问，不表示赞叹，与感叹句的语气不合。", "罢": "语域：“罢”是文言语气词，口语赞叹中不用。", "吧": "语义：“吧”表示推测或商量，不表示赞叹，与“多好”的感叹语气不合。"}, "sentence_index": 6, "correct_answer": "啊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本条例自发布之日起施行啊。", "explanation": "这里误把〈啊〉的口语语气用于法规条文，应去掉“啊”。"}, {"text": "本报讯，全市教育经费今年增长了百分之十啊。", "explanation": "这里误把〈啊〉的口语语气用于新闻报道，应去掉“啊”。"}, {"text": "会议纪要已经整理完毕啊，请各部门签字确认。", "explanation": "这里误把〈啊〉的口语语气用于会议纪要，应去掉“啊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间真啊干净啊。", "corrected_sentence": "这个房间真干净啊。", "error_description": "“啊”一般用在句末，不能插在副词“真”和形容词“干净”之间。正确说法是「这个房间真干净啊。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你可要记啊住这句话。", "corrected_sentence": "你可要记住这句话。", "error_description": "“啊”不能插在动补结构“记住”的中间，应去掉。正确说法是「你可要记住这句话。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bf93d2-1aff-4de8-816f-69d06dabcc5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
