INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85781, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“当”是说事情发生的那个时候。", "primary_collocate": null, "pronunciation": "dāng", "ipa": "tɑŋ˥", "syllable_count": 1, "sentences": [{"text": "当我回到家，天已经黑了。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当妈妈打电话来时，我正在做饭。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当火车开动时，他向我挥手。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当我看到那封信，高兴得哭了。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当太阳出来时，鸟儿都唱起歌来。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当老师走进教室，学生们都站了起来。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当你需要帮助时，请给我打电话。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当我们到车站，车已经走了。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当孩子哭的时候，妈妈总是抱着他。", "target_word": "当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当他说完话，大家都笑了。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "當", "label": "繁体"}], "register": "中性", "sense_fingerprint": "介词，引出事情发生的时间，常与“时”“的时候”搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85781, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "当", "is_correct": true, "explanation": "正确答案。“当”读 dāng（第一声），是介词，引出事情发生的时间。"}, {"text": "挡", "is_correct": false, "explanation": "dǎng（第三声）与 dāng（第一声）声调不同，意思是阻挡。"}, {"text": "档", "is_correct": false, "explanation": "dàng（第四声）与 dāng（第一声）声调不同，意思是档次。"}, {"text": "汤", "is_correct": false, "explanation": "tāng 与 dāng 声母不同（t 与 d），意思是汤。"}, {"text": "担", "is_correct": false, "explanation": "dān 与 dāng 韵母不同（an 与 ang），意思是担负。"}], "explanations": {"当": "正确答案。“当”读 dāng（第一声），是介词，引出事情发生的时间。", "挡": "dǎng（第三声）与 dāng（第一声）声调不同，意思是阻挡。", "档": "dàng（第四声）与 dāng（第一声）声调不同，意思是档次。", "汤": "tāng 与 dāng 声母不同（t 与 d），意思是汤。", "担": "dān 与 dāng 韵母不同（an 与 ang），意思是担负。"}, "sentence_index": null, "correct_answer": "当"}, "level_3": {"options": [{"text": "当", "is_correct": true, "explanation": "正确答案。“当”引出事情发生的时间，与“天已经黑了”的句意相合。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点，不表示“我回到家的那个时候”，句意不通。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示目的或为了，与引出时间不合。"}, {"text": "对", "is_correct": false, "explanation": "配价：“对”后要带对象，“对我回到家”不成立。"}], "explanations": {"当": "正确答案。“当”引出事情发生的时间，与“天已经黑了”的句意相合。", "从": "语义：“从”表示起点，不表示“我回到家的那个时候”，句意不通。", "为": "语义：“为”表示目的或为了，与引出时间不合。", "对": "配价：“对”后要带对象，“对我回到家”不成立。"}, "sentence_index": 0, "correct_answer": "当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当我的时候他很高兴。", "explanation": "“当”引出时间时后面应接事件，“当我的时候”没有时间意义，不符合“当”的本义。"}, {"text": "当他们昨天来。", "explanation": "“当”单独成句时缺少主句，句子不完整，不成立。"}, {"text": "他想家当的时候很难过。", "explanation": "“当”须位于整个时间短语之前，此处插在动词后，语序错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85781, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "当", "is_correct": true, "explanation": "正确答案。“当”读 dāng（第一声），是介词，引出事情发生的时间。"}, {"text": "党", "is_correct": false, "explanation": "dǎng（第三声）与 dāng（第一声）声调不同，意思是政党。"}, {"text": "荡", "is_correct": false, "explanation": "dàng（第四声）与 dāng（第一声）声调不同，意思是摇荡。"}, {"text": "丁", "is_correct": false, "explanation": "dīng 与 dāng 韵母不同（ing 与 ang），意思是丁。"}, {"text": "帮", "is_correct": false, "explanation": "bāng 与 dāng 声母不同（b 与 d），意思是帮助。"}], "explanations": {"当": "正确答案。“当”读 dāng（第一声），是介词，引出事情发生的时间。", "党": "dǎng（第三声）与 dāng（第一声）声调不同，意思是政党。", "荡": "dàng（第四声）与 dāng（第一声）声调不同，意思是摇荡。", "丁": "dīng 与 dāng 韵母不同（ing 与 ang），意思是丁。", "帮": "bāng 与 dāng 声母不同（b 与 d），意思是帮助。"}, "sentence_index": null, "correct_answer": "当"}, "level_3": {"options": [{"text": "当", "is_correct": true, "explanation": "正确答案。“当”引出事情发生的时间，与“需要帮助时”的条件相合。"}, {"text": "比", "is_correct": false, "explanation": "语法：“比”用于比较，“比你需要帮助时”不成立。"}, {"text": "随", "is_correct": false, "explanation": "语义：“随”表示跟随，句意不通。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”要带受益对象并与动词搭配，“替……时”不成立。"}], "explanations": {"当": "正确答案。“当”引出事情发生的时间，与“需要帮助时”的条件相合。", "比": "语法：“比”用于比较，“比你需要帮助时”不成立。", "随": "语义：“随”表示跟随，句意不通。", "替": "配价：“替”要带受益对象并与动词搭配，“替……时”不成立。"}, "sentence_index": 6, "correct_answer": "当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他哭当的时候很开心。", "explanation": "“当”须位于时间短语之前，此处置于动词之后，语序颠倒。"}, {"text": "这个房子当大。", "explanation": "“当”表示时间时后面应接事件，此处只用形容词，不符合本义。"}, {"text": "他当大哭了。", "explanation": "“当”引出时间时后面应接事件，此处不成立，不符合本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当他来的，我们就开始吃饭。", "corrected_sentence": "当他来的时候，我们就开始吃饭。", "error_description": "错误：“当他来的，”缺少“时候”；正确：“当他来的时候，”。“当……的时候”是固定框式，不能省略“时候”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当我到家的时，天已经黑了。", "corrected_sentence": "当我到家的时候，天已经黑了。", "error_description": "错误：“的时”；正确：“的时候”。“当……的时候”或“当……时”，不说“当……的时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
