INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85782, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示事情发生的时间，常与“时”“的时候”连用。", "primary_collocate": null, "pronunciation": "dāng", "ipa": "tɑŋ˥", "syllable_count": 1, "sentences": [{"text": "当我累的时候，我喜欢听音乐。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当春天来到的时候，花都开了。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当他还是学生时，每天骑车上学。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当你想家的时候，就给家里打电话。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当雨停的时候，我们就出去玩。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当客人来时，她总是先倒茶。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当我在国外生活的时候，常常想念家乡。", "target_word": "当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当大家都睡了的时候，他还在看书。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当朋友有困难时，我一定会帮他。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当我第一次见到她时，她正在画画。", "target_word": "当", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "當", "label": "繁体"}], "register": "中性", "sense_fingerprint": "介词，“当……的时候／时”框式结构，表示动作发生的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "当", "is_correct": true, "explanation": "正确答案。“当”读 dāng（第一声），与“的时候”连用，表示动作发生的时间。"}, {"text": "挡", "is_correct": false, "explanation": "dǎng（第三声）与 dāng（第一声）声调不同，意思是阻挡。"}, {"text": "档", "is_correct": false, "explanation": "dàng（第四声）与 dāng（第一声）声调不同，意思是档次。"}, {"text": "汤", "is_correct": false, "explanation": "tāng 与 dāng 声母不同（t 与 d），意思是汤。"}, {"text": "担", "is_correct": false, "explanation": "dān 与 dāng 韵母不同（an 与 ang），意思是担负。"}], "explanations": {"当": "正确答案。“当”读 dāng（第一声），与“的时候”连用，表示动作发生的时间。", "挡": "dǎng（第三声）与 dāng（第一声）声调不同，意思是阻挡。", "档": "dàng（第四声）与 dāng（第一声）声调不同，意思是档次。", "汤": "tāng 与 dāng 声母不同（t 与 d），意思是汤。", "担": "dān 与 dāng 韵母不同（an 与 ang），意思是担负。"}, "sentence_index": null, "correct_answer": "当"}, "level_3": {"options": [{"text": "当", "is_correct": true, "explanation": "正确答案。“当……的时候”引出动作发生的时间，与“我累”的语境相合。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点，句意是从累的时候开始，与“常常听音乐”的时间框架不合。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示目的或为了，与引出时间不合。"}, {"text": "对", "is_correct": false, "explanation": "配价：“对”后要带对象，“对我累的时候”不成立。"}], "explanations": {"当": "正确答案。“当……的时候”引出动作发生的时间，与“我累”的语境相合。", "从": "语义：“从”表示起点，句意是从累的时候开始，与“常常听音乐”的时间框架不合。", "为": "语义：“为”表示目的或为了，与引出时间不合。", "对": "配价：“对”后要带对象，“对我累的时候”不成立。"}, "sentence_index": 0, "correct_answer": "当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很喜欢吃饭的时候当。", "explanation": "“当”不能置于句末，须位于时间短语之前引出时间，此处位置错误。"}, {"text": "当的时候他哭了。", "explanation": "“当”后缺少时间成分或事件，结构不完整，不成立。"}, {"text": "他是朋友当的时候，我很开心。", "explanation": "“当”须位于时间短语之前，此处位置颠倒，语序错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85782, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "当", "is_correct": true, "explanation": "正确答案。“当”读 dāng（第一声），与“的时候”连用，表示动作发生的时间。"}, {"text": "党", "is_correct": false, "explanation": "dǎng（第三声）与 dāng（第一声）声调不同，意思是政党。"}, {"text": "荡", "is_correct": false, "explanation": "dàng（第四声）与 dāng（第一声）声调不同，意思是摇荡。"}, {"text": "丁", "is_correct": false, "explanation": "dīng 与 dāng 韵母不同（ing 与 ang），意思是丁。"}, {"text": "帮", "is_correct": false, "explanation": "bāng 与 dāng 声母不同（b 与 d），意思是帮助。"}], "explanations": {"当": "正确答案。“当”读 dāng（第一声），与“的时候”连用，表示动作发生的时间。", "党": "dǎng（第三声）与 dāng（第一声）声调不同，意思是政党。", "荡": "dàng（第四声）与 dāng（第一声）声调不同，意思是摇荡。", "丁": "dīng 与 dāng 韵母不同（ing 与 ang），意思是丁。", "帮": "bāng 与 dāng 声母不同（b 与 d），意思是帮助。"}, "sentence_index": null, "correct_answer": "当"}, "level_3": {"options": [{"text": "当", "is_correct": true, "explanation": "正确答案。“当……的时候”引出动作发生的时间，与“在国外生活”的语境相合。"}, {"text": "趁", "is_correct": false, "explanation": "语义：“趁”表示利用机会，与“常常想念家乡”的时间框架不合。"}, {"text": "随", "is_correct": false, "explanation": "语义：“随”表示跟随，句意不通。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”要带受益对象并与动词搭配，“替……时”不成立。"}], "explanations": {"当": "正确答案。“当……的时候”引出动作发生的时间，与“在国外生活”的语境相合。", "趁": "语义：“趁”表示利用机会，与“常常想念家乡”的时间框架不合。", "随": "语义：“随”表示跟随，句意不通。", "替": "配价：“替”要带受益对象并与动词搭配，“替……时”不成立。"}, "sentence_index": 6, "correct_answer": "当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当他吃饭的时候时，电话响了。", "explanation": "“的时候”和“时”重复，“当……的时候”后不能再加“时”。"}, {"text": "他累当的时候，就去睡觉。", "explanation": "“当”须位于时间短语之前，此处插在形容词后，语序错误。"}, {"text": "他三年班长当的时候，很开心。", "explanation": "“当”须位于时间短语之前，此处位置颠倒，语序错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当他下班回家时候，孩子已经睡了。", "corrected_sentence": "当他下班回家的时候，孩子已经睡了。", "error_description": "错误：“回家时候”；正确：“回家的时候”。“……的时候”中间要用“的”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当我感到累的时间，我会休息。", "corrected_sentence": "当我感到累的时候，我会休息。", "error_description": "错误：“的时间”；正确：“的时候”。“当……的时候”是固定说法，不说“的时间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
