INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85783, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“们”放在“我”“你”“孩子”后面，说明是好几个人。", "primary_collocate": null, "pronunciation": "men", "ipa": "mən", "syllable_count": 1, "sentences": [{"text": "我们明天去公园玩。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们都是我的好朋友。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在院子里跑来跑去。", "target_word": "们", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们每天坐地铁上班。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同学们，请安静，现在上课。", "target_word": "们", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师们正在开会。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她们一起去商店买衣服了。", "target_word": "们", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们送给我一个蛋糕。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生们都在认真地写字。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "叔叔们在客厅里喝茶。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "們", "label": "繁体"}], "register": "中性", "sense_fingerprint": "放在代词或指人名词后，表示人不止一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85783, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "们", "is_correct": true, "explanation": "们 men（轻声）是复数后缀，接在人称代词或指人名词后。"}, {"text": "门", "is_correct": false, "explanation": "mén（第二声）与 men（轻声）声调不同，意思是门。"}, {"text": "闷", "is_correct": false, "explanation": "mèn（第四声）与 men（轻声）声调不同，意思是闷热、烦闷。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 men（轻声）韵母不同（-eng 与 -en），意思是梦。"}, {"text": "笨", "is_correct": false, "explanation": "bèn（第四声）与 men 声母不同（b 与 m），声调也不同，意思是笨。"}, {"text": "嫩", "is_correct": false, "explanation": "nèn（第四声）与 men 声母不同（n 与 m），声调也不同，意思是嫩。"}, {"text": "满", "is_correct": false, "explanation": "mǎn（第三声）与 men（轻声）韵母不同（-an 与 -en），声调也不同，意思是满。"}], "explanations": {"们": "们 men（轻声）是复数后缀，接在人称代词或指人名词后。", "门": "mén（第二声）与 men（轻声）声调不同，意思是门。", "闷": "mèn（第四声）与 men（轻声）声调不同，意思是闷热、烦闷。", "梦": "mèng（第四声）与 men（轻声）韵母不同（-eng 与 -en），意思是梦。", "笨": "bèn（第四声）与 men 声母不同（b 与 m），声调也不同，意思是笨。", "嫩": "nèn（第四声）与 men 声母不同（n 与 m），声调也不同，意思是嫩。", "满": "mǎn（第三声）与 men（轻声）韵母不同（-an 与 -en），声调也不同，意思是满。"}, "sentence_index": null, "correct_answer": "们"}, "level_3": {"options": [{"text": "的", "is_correct": false, "explanation": "语义：“我的”表示所属，“我的明天去公园玩”说不通，后句需要一个能去公园的主语。"}, {"text": "们", "is_correct": true, "explanation": "“我们”指包括说话人在内的多人，与“明天去公园玩”相符。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”接在形容词后作状语，不能接在代词“我”后。"}, {"text": "之", "is_correct": false, "explanation": "语域：“之”是文言用法，“我之明天去公园玩”不合口语句子。"}], "explanations": {"的": "语义：“我的”表示所属，“我的明天去公园玩”说不通，后句需要一个能去公园的主语。", "们": "“我们”指包括说话人在内的多人，与“明天去公园玩”相符。", "地": "搭配：“地”接在形容词后作状语，不能接在代词“我”后。", "之": "语域：“之”是文言用法，“我之明天去公园玩”不合口语句子。"}, "sentence_index": 0, "correct_answer": "们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们一个人住在山上。", "explanation": "这里不应加“们”。“一个人”指单独一人，与复数的“他们”矛盾，应说“他一个人”。"}, {"text": "我们一个人去了北京。", "explanation": "这里不应加“们”。“一个人”指单独一人，“我们”是复数，应说“我一个人”。"}, {"text": "两个孩子们在院子里玩。", "explanation": "这里不应加“们”。前面已有数量词“两个”，名词后不能再加“们”，应说“两个孩子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85783, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "们", "is_correct": true, "explanation": "们 men（轻声）是复数后缀，接在人称代词或指人名词后。"}, {"text": "猛", "is_correct": false, "explanation": "měng（第三声）与 men 韵母不同（-eng 与 -en），声调也不同，意思是猛烈。"}, {"text": "盟", "is_correct": false, "explanation": "méng（第二声）与 men 韵母不同（-eng 与 -en），声调也不同，意思是盟约、结盟。"}, {"text": "焖", "is_correct": false, "explanation": "mèn（第四声）与 men（轻声）声调不同，意思是用文火慢煮。"}, {"text": "本", "is_correct": false, "explanation": "běn（第三声）与 men 声母不同（b 与 m），声调也不同，意思是本子。"}], "explanations": {"们": "们 men（轻声）是复数后缀，接在人称代词或指人名词后。", "猛": "měng（第三声）与 men 韵母不同（-eng 与 -en），声调也不同，意思是猛烈。", "盟": "méng（第二声）与 men 韵母不同（-eng 与 -en），声调也不同，意思是盟约、结盟。", "焖": "mèn（第四声）与 men（轻声）声调不同，意思是用文火慢煮。", "本": "běn（第三声）与 men 声母不同（b 与 m），声调也不同，意思是本子。"}, "sentence_index": null, "correct_answer": "们"}, "level_3": {"options": [{"text": "得", "is_correct": false, "explanation": "搭配：“得”接在动词或形容词后作补语，不能接在代词“她”后。"}, {"text": "们", "is_correct": true, "explanation": "“她们”指多位女性，与“一起去商店买衣服了”相符。"}, {"text": "着", "is_correct": false, "explanation": "搭配：“着”附着在动词后表示状态，“她着一起去商店”不成立。"}, {"text": "等", "is_correct": false, "explanation": "语义：“等”读作“等待”时，“她等一起去商店买衣服了”句意不通。"}], "explanations": {"得": "搭配：“得”接在动词或形容词后作补语，不能接在代词“她”后。", "们": "“她们”指多位女性，与“一起去商店买衣服了”相符。", "着": "搭配：“着”附着在动词后表示状态，“她着一起去商店”不成立。", "等": "语义：“等”读作“等待”时，“她等一起去商店买衣服了”句意不通。"}, "sentence_index": 6, "correct_answer": "们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人群们在广场上聚会。", "explanation": "这里不应加“们”。“人群”本身已表示许多人，再加“们”是重复，应说“人群在广场上聚会”。"}, {"text": "我的妈妈们在厨房做饭。", "explanation": "这里不应加“们”。“我的妈妈”只指一位，加“们”会变成多位妈妈，应说“我妈妈”。"}, {"text": "三个学生们在教室里看书。", "explanation": "这里不应加“们”。前面已有数量词“三个”，名词后不能再加“们”，应说“三个学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的们朋友很友好。", "corrected_sentence": "我们的朋友很友好。", "error_description": "“们”应紧接在“我”后构成“我们”，再接“的”修饰“朋友”。错写成“我的们朋友”，“们”跟在“的”后面，语序不通。正确形式为“我们的朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我都们在教室里学习。", "corrected_sentence": "我们都在教室里学习。", "error_description": "“们”应紧接在“我”后构成“我们”，再接“都”。错写成“我都们”，“们”跟在“都”后面，语序不通。正确形式为“我们都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85784, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
