INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85784, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "后缀，用在代词或指人的名词后面，表示复数。", "primary_collocate": null, "pronunciation": "men", "ipa": "mən", "syllable_count": 1, "sentences": [{"text": "咱们一起去看电影吧。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们想吃什么？", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人们正在修路。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们家有四口人。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友们手拉着手唱歌。", "target_word": "们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们昨天去了北京。", "target_word": "们", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生们都很忙。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "姐姐们给我买了新书包。", "target_word": "们", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人们坐在沙发上聊天。", "target_word": "们", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "女孩们穿着漂亮的裙子。", "target_word": "们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "們", "label": "繁体"}], "register": "中性", "sense_fingerprint": "复数后缀，接在人称代词或指人名词后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85784, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "们", "is_correct": true, "explanation": "们 men（轻声）是复数后缀，接在人称代词或指人名词后。"}, {"text": "门", "is_correct": false, "explanation": "mén（第二声）与 men（轻声）声调不同，意思是门。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 men（轻声）韵母不同（-eng 与 -en），意思是梦。"}, {"text": "嫩", "is_correct": false, "explanation": "nèn（第四声）与 men 声母不同（n 与 m），声调也不同，意思是嫩。"}, {"text": "满", "is_correct": false, "explanation": "mǎn（第三声）与 men（轻声）韵母不同（-an 与 -en），声调也不同，意思是满。"}], "explanations": {"们": "们 men（轻声）是复数后缀，接在人称代词或指人名词后。", "门": "mén（第二声）与 men（轻声）声调不同，意思是门。", "梦": "mèng（第四声）与 men（轻声）韵母不同（-eng 与 -en），意思是梦。", "嫩": "nèn（第四声）与 men 声母不同（n 与 m），声调也不同，意思是嫩。", "满": "mǎn（第三声）与 men（轻声）韵母不同（-an 与 -en），声调也不同，意思是满。"}, "sentence_index": null, "correct_answer": "们"}, "level_3": {"options": [{"text": "之", "is_correct": false, "explanation": "语域：“之”是文言用法，“咱之一起去看电影吧”不合口语句子。"}, {"text": "的", "is_correct": false, "explanation": "语义：“咱的”表示所属，“咱的一起去看电影吧”句意不通，“一起去”需要复数主语。"}, {"text": "们", "is_correct": true, "explanation": "“咱们”是包括听话人在内的复数，与“一起去看电影吧”相符。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”接在形容词后作状语，不能接在代词“咱”后。"}], "explanations": {"之": "语域：“之”是文言用法，“咱之一起去看电影吧”不合口语句子。", "的": "语义：“咱的”表示所属，“咱的一起去看电影吧”句意不通，“一起去”需要复数主语。", "们": "“咱们”是包括听话人在内的复数，与“一起去看电影吧”相符。", "地": "搭配：“地”接在形容词后作状语，不能接在代词“咱”后。"}, "sentence_index": 0, "correct_answer": "们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她们一个人住在这里。", "explanation": "这里不应加“们”。“一个人”指单独一人，与复数的“她们”矛盾，应说“她一个人”。"}, {"text": "我们班的班主任们今天都来了。", "explanation": "这里不应加“们”。“我们班的班主任”只指一位，加“们”表示多人，应说“我们班的班主任今天来了”。"}, {"text": "老师们一个人在办公室。", "explanation": "这里不应加“们”。“一个人”指单独一人，与“老师们”的复数矛盾，应说“老师一个人在办公室”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85784, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "们", "is_correct": true, "explanation": "们 men（轻声）是复数后缀，接在人称代词或指人名词后。"}, {"text": "猛", "is_correct": false, "explanation": "měng（第三声）与 men 韵母不同（-eng 与 -en），声调也不同，意思是猛烈。"}, {"text": "盟", "is_correct": false, "explanation": "méng（第二声）与 men 韵母不同（-eng 与 -en），声调也不同，意思是盟约、结盟。"}, {"text": "焖", "is_correct": false, "explanation": "mèn（第四声）与 men（轻声）声调不同，意思是用文火慢煮。"}, {"text": "本", "is_correct": false, "explanation": "běn（第三声）与 men 声母不同（b 与 m），声调也不同，意思是本子。"}], "explanations": {"们": "们 men（轻声）是复数后缀，接在人称代词或指人名词后。", "猛": "měng（第三声）与 men 韵母不同（-eng 与 -en），声调也不同，意思是猛烈。", "盟": "méng（第二声）与 men 韵母不同（-eng 与 -en），声调也不同，意思是盟约、结盟。", "焖": "mèn（第四声）与 men（轻声）声调不同，意思是用文火慢煮。", "本": "běn（第三声）与 men 声母不同（b 与 m），声调也不同，意思是本子。"}, "sentence_index": null, "correct_answer": "们"}, "level_3": {"options": [{"text": "得", "is_correct": false, "explanation": "搭配：“得”接在动词或形容词后作补语，不能接在名词“医生”后。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”接在形容词后作状语，不能接在名词“医生”后。"}, {"text": "着", "is_correct": false, "explanation": "搭配：“着”附着在动词后表示状态，“医生着都很忙”不成立。"}, {"text": "们", "is_correct": true, "explanation": "“医生们”指多位医生，与“都很忙”相符。"}], "explanations": {"得": "搭配：“得”接在动词或形容词后作补语，不能接在名词“医生”后。", "地": "搭配：“地”接在形容词后作状语，不能接在名词“医生”后。", "着": "搭配：“着”附着在动词后表示状态，“医生着都很忙”不成立。", "们": "“医生们”指多位医生，与“都很忙”相符。"}, "sentence_index": 6, "correct_answer": "们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人群们在广场上跳舞。", "explanation": "这里不应加“们”。“人群”本身已表示许多人，再加“们”是重复，应说“人群在广场上跳舞”。"}, {"text": "我的爸爸们昨天去医院了。", "explanation": "这里不应加“们”。“我的爸爸”只指一位，加“们”会变成多位爸爸，应说“我爸爸”。"}, {"text": "我的妈妈们在厨房做饭。", "explanation": "这里不应加“们”。“我的妈妈”只指一位，加“们”会变成多位妈妈，应说“我妈妈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的们老师很和气。", "corrected_sentence": "我们的老师很和气。", "error_description": "“们”应紧接在“我”后构成“我们”，再接“的”修饰“老师”。错写成“我的们老师”，“们”跟在“的”后面，语序不通。正确形式为“我们的老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个医生们都很忙。", "corrected_sentence": "每个医生都很忙。", "error_description": "“每个”指每一位，是单数，不能与“们”同用。错写成“每个医生们”，正确形式为“每个医生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
