INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85785, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“但是”是说后面的话和前面的话不一样。", "primary_collocate": null, "pronunciation": "dàn shì", "ipa": "tan˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "我想买那双鞋，但是钱不够。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很想去，但是妈妈不同意。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆不大，但是菜很好吃。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会游泳，但是游得不太好。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨很大，但是他还是来了。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这本书，但是看不懂。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子不高，但是跑得很快。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给他打了电话，但是他没接。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很忙，但是每天都看书。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里冬天很冷，但是夏天很舒服。", "target_word": "但是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "转折连词：后面的话和前面的话意思不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec8071b-2a1d-4600-a16f-7fee21a7b3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85785, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "但是", "is_correct": true, "explanation": "表示转折：“想买那双鞋”与“钱不够”意思相反，符合句意。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”要和“不是”配合，前文没有否定，不能这样用。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，“想买鞋”与“钱不够”不是二选一的关系。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，“想买鞋”不能导致“钱不够”，句意说不通。"}], "explanations": {"但是": "表示转折：“想买那双鞋”与“钱不够”意思相反，符合句意。", "而是": "搭配：“而是”要和“不是”配合，前文没有否定，不能这样用。", "或者": "语义：“或者”表示选择，“想买鞋”与“钱不够”不是二选一的关系。", "所以": "语义：“所以”表示因果，“想买鞋”不能导致“钱不够”，句意说不通。"}, "sentence_index": 0, "correct_answer": "但是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上有书，但是笔，还有纸。", "explanation": "这里是并列列举，应该用〈和〉。“但是”表示转折，前后没有对比，用在列举里不对。"}, {"text": "他生病了，但是没来上课。", "explanation": "这里是因果关系，应该用〈所以〉。生病不来上课很自然，前后没有转折。"}, {"text": "我饿了，但是去吃饭了。", "explanation": "这里是因果关系，应该用〈所以〉。饿了去吃饭很自然，前后没有转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "但是", "is_correct": true, "explanation": "表示转折：“个子不高”与“跑得很快”形成对比，符合句意。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示因果，“跑得快”不能是“个子不高”的原因，句意说不通。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”表示递进，后面通常接“而且”“还”，且与前文的对比语义不合，句意不通。"}, {"text": "故而", "is_correct": false, "explanation": "语域：“故而”是书面语，且表示因果，与此句的转折关系不符。"}], "explanations": {"但是": "表示转折：“个子不高”与“跑得很快”形成对比，符合句意。", "因为": "语义：“因为”表示因果，“跑得快”不能是“个子不高”的原因，句意说不通。", "不但": "搭配：“不但”表示递进，后面通常接“而且”“还”，且与前文的对比语义不合，句意不通。", "故而": "语域：“故而”是书面语，且表示因果，与此句的转折关系不符。"}, "sentence_index": 6, "correct_answer": "但是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很渴，但是他喝了很多水。", "explanation": "这里是因果关系，应该用〈所以〉。“但是”表示转折，而渴了喝水是很自然的事，没有对比。"}, {"text": "我下班了，但是去了超市。", "explanation": "这里表示先后顺序，应该用〈然后〉。“但是”表示转折，前后没有对比，这样说不对。"}, {"text": "今天你喝茶，但是喝咖啡？", "explanation": "这里是在两者之间选一个，应该用〈还是〉。“但是”表示转折，这里不是对立的关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想喝咖啡，但是但是现在太晚了。", "corrected_sentence": "我想喝咖啡，但是现在太晚了。", "error_description": "“但是”不能重复叠用，一个转折只用一次。应去掉重复的“但是”，写作“但是现在太晚了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "虽然他很累，所以但是他很开心。", "corrected_sentence": "虽然他很累，但是他很开心。", "error_description": "“虽然”与“但是”搭配表转折，中间不能再加“所以”表因果。应去掉“所以”，写作“虽然他很累，但是他很开心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
