INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85789, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“谁”是用来问是哪一个人的。", "primary_collocate": null, "pronunciation": "shéi", "ipa": "ʂei˧˥", "syllable_count": 1, "sentences": [{"text": "你是谁？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谁在门口等我？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是谁的书包？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天谁给你打电话了？", "target_word": "谁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁想喝茶？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你在跟谁说话？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谁会说中文？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不知道那个人是谁。", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天谁做饭？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你想请谁来我家吃饭？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "誰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "疑问代词，用来问人是哪一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85789, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谁", "is_correct": true, "explanation": "shéi（第二声）是疑问代词，用来问人是哪一个。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shéi 韵母不同（-en 与 -ei），声调相同，意思是神。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是身体。"}, {"text": "晒", "is_correct": false, "explanation": "shài（第四声）与 shéi 韵母不同（-ai 与 -ei），声调也不同，意思是晒太阳。"}, {"text": "水", "is_correct": false, "explanation": "shuǐ（第三声）与 shéi 韵母与声调都不同，意思是水。"}], "explanations": {"谁": "shéi（第二声）是疑问代词，用来问人是哪一个。", "神": "shén（第二声）与 shéi 韵母不同（-en 与 -ei），声调相同，意思是神。", "身": "shēn（第一声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是身体。", "晒": "shài（第四声）与 shéi 韵母不同（-ai 与 -ei），声调也不同，意思是晒太阳。", "水": "shuǐ（第三声）与 shéi 韵母与声调都不同，意思是水。"}, "sentence_index": null, "correct_answer": "谁"}, "level_3": {"options": [{"text": "大家", "is_correct": false, "explanation": "语义：“大家”指众人，不能作“你是”的表语，与单数的“你”不合。"}, {"text": "谁", "is_correct": true, "explanation": "“谁”是疑问代词，用来问“你”是哪一个人，句意完整。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“是”之后接“自己”，不能构成询问身份的问句。"}, {"text": "人家", "is_correct": false, "explanation": "语义：“人家”指别人或他们，不能用来问“你”是哪一个人。"}], "explanations": {"大家": "语义：“大家”指众人，不能作“你是”的表语，与单数的“你”不合。", "谁": "“谁”是疑问代词，用来问“你”是哪一个人，句意完整。", "自己": "搭配：“是”之后接“自己”，不能构成询问身份的问句。", "人家": "语义：“人家”指别人或他们，不能用来问“你”是哪一个人。"}, "sentence_index": 0, "correct_answer": "谁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你昨天吃了谁？", "explanation": "这里应该用“什么”：“吃”的对象是东西，“谁”只用来问人。"}, {"text": "这个城市是谁？", "explanation": "这里“谁”问的是城市，“谁”只用来问人，应改用“什么”。"}, {"text": "今天的天气是谁？", "explanation": "这里“谁”问的是天气，“谁”只用来问人，应改用“怎么样”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85789, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "谁", "is_correct": true, "explanation": "shéi（第二声）是疑问代词，用来问人是哪一个。"}, {"text": "贼", "is_correct": false, "explanation": "zéi（第二声）与 shéi 声母不同（z 与 sh），声调相同，意思是小偷。"}, {"text": "慎", "is_correct": false, "explanation": "shèn（第四声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是谨慎。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是深。"}], "explanations": {"谁": "shéi（第二声）是疑问代词，用来问人是哪一个。", "贼": "zéi（第二声）与 shéi 声母不同（z 与 sh），声调相同，意思是小偷。", "慎": "shèn（第四声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是谨慎。", "深": "shēn（第一声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是深。"}, "sentence_index": null, "correct_answer": "谁"}, "level_3": {"options": [{"text": "地", "is_correct": false, "explanation": "语法：“地”是结构助词，用在状语后，不能作主语，“地会说中文？”不成立。"}, {"text": "谁", "is_correct": true, "explanation": "“谁”作主语，问会说中文的是哪一个人，句意完整。"}, {"text": "的", "is_correct": false, "explanation": "语法：“的”是结构助词，不能充当句子的主语，“的会说中文？”不成立。"}, {"text": "某人", "is_correct": false, "explanation": "搭配：“某人”泛指不确定的人，不能用来提问“是哪一个人”。"}], "explanations": {"地": "语法：“地”是结构助词，用在状语后，不能作主语，“地会说中文？”不成立。", "谁": "“谁”作主语，问会说中文的是哪一个人，句意完整。", "的": "语法：“的”是结构助词，不能充当句子的主语，“的会说中文？”不成立。", "某人": "搭配：“某人”泛指不确定的人，不能用来提问“是哪一个人”。"}, "sentence_index": 6, "correct_answer": "谁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果是谁？", "explanation": "这里“谁”问的是苹果，“谁”只用来问人，应改用“什么”。"}, {"text": "这部电影叫谁？", "explanation": "这里“谁”问的是电影，“谁”只用来问人，应改用“什么”。"}, {"text": "这张桌子是谁？", "explanation": "这里“谁”问的是桌子，“谁”只用来问人，应改用“什么”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你打算找谁们帮忙？", "corrected_sentence": "你打算找谁帮忙？", "error_description": "错误：“谁们”；正确：“谁”。“谁”是疑问代词，后面不能加“们”，不说“谁们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是谁吗？", "corrected_sentence": "他是谁？", "error_description": "“谁”本身就是疑问词，句末不需要再加“吗”。错写成“他是谁吗”，两个疑问标记重复，正确形式为“他是谁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
