INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85790, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问人是哪一个。", "primary_collocate": null, "pronunciation": "shéi", "ipa": "ʂei˧˥", "syllable_count": 1, "sentences": [{"text": "谁是你们的老师？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看见谁了？", "target_word": "谁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁把我的杯子拿走了？", "target_word": "谁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是谁买的？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谁住在你隔壁？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你昨晚和谁一起吃饭？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谁来过这里？", "target_word": "谁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给了谁一个红包？", "target_word": "谁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门外站着一个人，你知道他是谁吗？", "target_word": "谁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁能告诉我现在几点？", "target_word": "谁", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "誰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "疑问代词，询问某人的身份或动作的施行者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85790, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谁", "is_correct": true, "explanation": "shéi（第二声）是疑问代词，用来问人是哪一个。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shéi 韵母不同（-en 与 -ei），声调相同，意思是神。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是身体。"}, {"text": "晒", "is_correct": false, "explanation": "shài（第四声）与 shéi 韵母不同（-ai 与 -ei），声调也不同，意思是晒太阳。"}, {"text": "水", "is_correct": false, "explanation": "shuǐ（第三声）与 shéi 韵母与声调都不同，意思是水。"}], "explanations": {"谁": "shéi（第二声）是疑问代词，用来问人是哪一个。", "神": "shén（第二声）与 shéi 韵母不同（-en 与 -ei），声调相同，意思是神。", "身": "shēn（第一声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是身体。", "晒": "shài（第四声）与 shéi 韵母不同（-ai 与 -ei），声调也不同，意思是晒太阳。", "水": "shuǐ（第三声）与 shéi 韵母与声调都不同，意思是水。"}, "sentence_index": null, "correct_answer": "谁"}, "level_3": {"options": [{"text": "某人", "is_correct": false, "explanation": "语义：“某人”指不确定的人，不能用来询问“是哪一个人”，与问句冲突。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”指本人，不能与“你们的老师”构成询问身份的句子。"}, {"text": "谁", "is_correct": true, "explanation": "“谁”作主语，问“你们的老师”是哪一个人，句意完整。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”是动态助词，附着在动词后，不能作主语，“着是你们的老师？”不成立。"}], "explanations": {"某人": "语义：“某人”指不确定的人，不能用来询问“是哪一个人”，与问句冲突。", "自己": "搭配：“自己”指本人，不能与“你们的老师”构成询问身份的句子。", "谁": "“谁”作主语，问“你们的老师”是哪一个人，句意完整。", "着": "语法：“着”是动态助词，附着在动词后，不能作主语，“着是你们的老师？”不成立。"}, "sentence_index": 0, "correct_answer": "谁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山是谁？", "explanation": "这里“谁”问的是山，“谁”只用来问人，应改用“什么”。"}, {"text": "这碗饭是谁？", "explanation": "这里“谁”问的是饭，“谁”只用来问人，应改用“什么”。"}, {"text": "这间教室是谁？", "explanation": "这里“谁”问的是教室，“谁”只用来问人，应改用“什么”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85790, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "谁", "is_correct": true, "explanation": "shéi（第二声）是疑问代词，用来问人是哪一个。"}, {"text": "贼", "is_correct": false, "explanation": "zéi（第二声）与 shéi 声母不同（z 与 sh），声调相同，意思是小偷。"}, {"text": "慎", "is_correct": false, "explanation": "shèn（第四声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是谨慎。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是深。"}], "explanations": {"谁": "shéi（第二声）是疑问代词，用来问人是哪一个。", "贼": "zéi（第二声）与 shéi 声母不同（z 与 sh），声调相同，意思是小偷。", "慎": "shèn（第四声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是谨慎。", "深": "shēn（第一声）与 shéi 韵母不同（-en 与 -ei），声调也不同，意思是深。"}, "sentence_index": null, "correct_answer": "谁"}, "level_3": {"options": [{"text": "地", "is_correct": false, "explanation": "语法：“地”是结构助词，用在状语后，不能作主语，“地来过这里？”不成立。"}, {"text": "谁", "is_correct": true, "explanation": "“谁”作主语，问是哪一个人来过这里，句意完整。"}, {"text": "着", "is_correct": false, "explanation": "搭配：“着”附着在动词后表示状态，“着来过这里”不成立。"}, {"text": "的", "is_correct": false, "explanation": "语法：“的”是结构助词，不能充当句子的主语，“的来过这里”不成立。"}], "explanations": {"地": "语法：“地”是结构助词，用在状语后，不能作主语，“地来过这里？”不成立。", "谁": "“谁”作主语，问是哪一个人来过这里，句意完整。", "着": "搭配：“着”附着在动词后表示状态，“着来过这里”不成立。", "的": "语法：“的”是结构助词，不能充当句子的主语，“的来过这里”不成立。"}, "sentence_index": 6, "correct_answer": "谁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河是谁？", "explanation": "这里“谁”问的是河，“谁”只用来问人，应改用“什么”。"}, {"text": "这把椅子叫谁？", "explanation": "这里“谁”问的是椅子，“谁”只用来问人，应改用“什么”。"}, {"text": "这个季节是谁？", "explanation": "这里“谁”问的是季节，“谁”只用来问人，应改用“什么”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你是谁跟一起来的？", "corrected_sentence": "你是跟谁一起来的？", "error_description": "“谁”作“跟”的宾语，应放在“跟”后，写作“跟谁一起来”。错写成“谁跟”，把“谁”放到“跟”前，语序不通。正确形式为“跟谁一起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事到底是谁告诉你的吗？", "corrected_sentence": "这件事到底是谁告诉你的？", "error_description": "错误：句末多出“吗”；正确：去掉“吗”。“谁”本身已是疑问词，句末不需要再加“吗”，两个疑问标记重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
