INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85791, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“以及”可以把好几样东西连在一起，一样一样说下去。", "primary_collocate": null, "pronunciation": "yǐ jí", "ipa": "i˨˩˦ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "桌子上有苹果、香蕉以及西瓜。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了面包、牛奶、鸡蛋以及水果。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包里有书、本子以及一支笔。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要老师、医生以及工程师。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去过北京、上海以及广州。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会说汉语、英语以及日语。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里卖米、面、油以及各种饮料。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里有桌子、椅子以及一台电脑。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要带水、帽子以及雨伞。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢音乐、电影以及运动。", "target_word": "以及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "并列连词：把几样东西依次连起来，用在最后一项前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec8071b-2a1d-4600-a16f-7fee21a7b3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85791, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以及", "is_correct": true, "explanation": "“以及”读作 yǐ jí（第三声），连接并列的几项，放在最后一项之前。"}, {"text": "一级", "is_correct": false, "explanation": "yī（第一声）与 yǐ（第三声）声调不同，“一级”意思是第一等级。"}, {"text": "亿级", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，“亿级”指亿这个数量级。"}, {"text": "一击", "is_correct": false, "explanation": "yī 与 yǐ 声调不同，jī（第一声）与 jí（第二声）声调也不同，“一击”指一次打击。"}, {"text": "易记", "is_correct": false, "explanation": "yì 与 yǐ 声调不同，jì（第四声）与 jí（第二声）声调也不同，“易记”意思是容易记住。"}], "explanations": {"以及": "“以及”读作 yǐ jí（第三声），连接并列的几项，放在最后一项之前。", "一级": "yī（第一声）与 yǐ（第三声）声调不同，“一级”意思是第一等级。", "亿级": "yì（第四声）与 yǐ（第三声）声调不同，“亿级”指亿这个数量级。", "一击": "yī 与 yǐ 声调不同，jī（第一声）与 jí（第二声）声调也不同，“一击”指一次打击。", "易记": "yì 与 yǐ 声调不同，jì（第四声）与 jí（第二声）声调也不同，“易记”意思是容易记住。"}, "sentence_index": null, "correct_answer": "以及"}, "level_3": {"options": [{"text": "以及", "is_correct": true, "explanation": "“以及”连接并列的几样东西，放在最后一项之前，符合句意。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示任选其一，而桌上的三样东西是同时都有的。"}, {"text": "或是", "is_correct": false, "explanation": "语义：“或是”表示任选，与“桌子上有”三样东西的句意矛盾。"}, {"text": "及其", "is_correct": false, "explanation": "搭配：“及其”指前面某一方的成员，这里三样东西并列，不能用“及其”。"}], "explanations": {"以及": "“以及”连接并列的几样东西，放在最后一项之前，符合句意。", "或者": "语义：“或者”表示任选其一，而桌上的三样东西是同时都有的。", "或是": "语义：“或是”表示任选，与“桌子上有”三样东西的句意矛盾。", "及其": "搭配：“及其”指前面某一方的成员，这里三样东西并列，不能用“及其”。"}, "sentence_index": 0, "correct_answer": "以及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天很累以及想早点睡觉。", "explanation": "“以及”一般连接名词性的并列成分，不连接同一主语的两个谓语。这里应改用〈而且〉或〈还〉，即“我今天很累，而且想早点睡觉”。"}, {"text": "我去了银行，以及他们去了医院。", "explanation": "这里连接的是两个主谓分句，“以及”不用于此，应该用〈而且〉或〈并且〉。"}, {"text": "这把椅子很舒服以及很结实。", "explanation": "“以及”不连接形容词，这里应说“又舒服又结实”，或用〈而且〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以及", "is_correct": true, "explanation": "“以及”连接并列的几样商品，放在最后一项之前，符合句意。"}, {"text": "还是", "is_correct": false, "explanation": "语义：“还是”多用于选择，超市卖的这几样东西并非任选其一。"}, {"text": "抑或", "is_correct": false, "explanation": "语义：“抑或”表示选择（“或者”），而超市是同时卖这些东西，不合句意。"}, {"text": "或", "is_correct": false, "explanation": "语义：“或”表示任选其一，而超市是同时卖这些东西。"}], "explanations": {"以及": "“以及”连接并列的几样商品，放在最后一项之前，符合句意。", "还是": "语义：“还是”多用于选择，超市卖的这几样东西并非任选其一。", "抑或": "语义：“抑或”表示选择（“或者”），而超市是同时卖这些东西，不合句意。", "或": "语义：“或”表示任选其一，而超市是同时卖这些东西。"}, "sentence_index": 6, "correct_answer": "以及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很努力，以及没有考好。", "explanation": "这里是转折的意思，应该用〈但是〉。“以及”只表示并列，不能表示转折。"}, {"text": "以及，他也喜欢旅行。", "explanation": "“以及”不能单独放在句首引出新的内容，这里应说“另外，他也喜欢旅行”。"}, {"text": "他工作很忙，以及今天没有来。", "explanation": "这里是因果的意思，应该用〈因此〉。“以及”只表示并列，不能用来表示因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冰箱里有牛奶、鸡蛋和以及蔬菜。", "corrected_sentence": "冰箱里有牛奶、鸡蛋以及蔬菜。", "error_description": "“和”与“以及”都是并列连词，不能叠用。应去掉“和”，写作“冰箱里有牛奶、鸡蛋以及蔬菜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们准备了茶、咖啡以及、点心。", "corrected_sentence": "我们准备了茶、咖啡以及点心。", "error_description": "“以及”后面直接接最后一项，不加顿号。应去掉“、”，写作“我们准备了茶、咖啡以及点心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
