INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“人民”是一个国家里的很多很多人。", "primary_collocate": null, "pronunciation": "rén mín", "ipa": "ʐən˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "这个国家的人民都很友好。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人民喜欢在春节回家。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国人民都看了这场比赛。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人民大多喜欢喝茶。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国人民的关系很好。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的人民生活得很快乐。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界各国人民都想要和平。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们国家的人民很爱吃米饭。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小国的人民都很热情。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了各国人民的生活。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "一个国家里的很多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25afb08-42c1-4494-8c54-317012e5d40c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85793, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人民", "is_correct": true, "explanation": "正确答案。人民 rén mín，指一个国家里的很多人。"}, {"text": "人名", "is_correct": false, "explanation": "mín（第二声）与 míng（第二声）韵母不同（in/ing），意思是人的名字。"}, {"text": "人命", "is_correct": false, "explanation": "mín（第二声）与 mìng（第四声）韵母不同（in/ing）且声调不同，意思是人的生命。"}, {"text": "任命", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同；mín 与 mìng 韵母不同（in/ing），意思是委任官职。"}, {"text": "人们", "is_correct": false, "explanation": "mín（第二声）与 men（轻声）声调不同，意思是泛指的人们。"}], "explanations": {"人民": "正确答案。人民 rén mín，指一个国家里的很多人。", "人名": "mín（第二声）与 míng（第二声）韵母不同（in/ing），意思是人的名字。", "人命": "mín（第二声）与 mìng（第四声）韵母不同（in/ing）且声调不同，意思是人的生命。", "任命": "rén（第二声）与 rèn（第四声）声调不同；mín 与 mìng 韵母不同（in/ing），意思是委任官职。", "人们": "mín（第二声）与 men（轻声）声调不同，意思是泛指的人们。"}, "sentence_index": null, "correct_answer": "人民"}, "level_3": {"options": [{"text": "人民", "is_correct": true, "explanation": "正确答案。人民指一个国家里的很多人，“友好”的对象是人，符合句意。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木是植物，不能用“友好”来形容，句意不通。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“友好”多用来形容人或群体，不能用来形容“房子”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能“友好”，句意不通。"}], "explanations": {"人民": "正确答案。人民指一个国家里的很多人，“友好”的对象是人，符合句意。", "树木": "语义：树木是植物，不能用“友好”来形容，句意不通。", "房子": "搭配：“友好”多用来形容人或群体，不能用来形容“房子”。", "石头": "语义：石头是无生命的物体，不能“友好”，句意不通。"}, "sentence_index": 0, "correct_answer": "人民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区的人民很多。", "explanation": "这里应该用〈居民〉。人民指一个国家的广大群众，不用来指某个小区的住户，后者要说居民。"}, {"text": "这家店的人民都很热情。", "explanation": "这里应该用〈顾客〉。人民指一个国家的广大群众，不用来指光顾某家店铺的人，光顾店铺的人要说顾客。"}, {"text": "这个班的人民大多喜欢喝茶。", "explanation": "这里应该用〈学生〉。人民指广大群众，不用来指一个班里的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人民", "is_correct": true, "explanation": "正确答案。人民指一个国家里的很多人，“想要和平”的主体是人，符合句意。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是有害的微生物，不会“想要和平”，句意荒谬。"}, {"text": "工具", "is_correct": false, "explanation": "语义：工具没有意愿，不能“想要和平”，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“想要”需要有意志的主体，“价格”不能作“想要和平”的主语。"}], "explanations": {"人民": "正确答案。人民指一个国家里的很多人，“想要和平”的主体是人，符合句意。", "病毒": "语义：病毒是有害的微生物，不会“想要和平”，句意荒谬。", "工具": "语义：工具没有意愿，不能“想要和平”，句意不通。", "价格": "搭配：“想要”需要有意志的主体，“价格”不能作“想要和平”的主语。"}, "sentence_index": 6, "correct_answer": "人民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "候车室的人民很多。", "explanation": "这里应该用〈旅客〉。人民指一个国家的广大群众，不用来指候车室里等车的人，这类人要说旅客。"}, {"text": "工厂的人民每天都很忙。", "explanation": "这里应该用〈工人〉。人民指广大群众，不用来指在工厂里做工的人，工厂里做工的人要说工人。"}, {"text": "学校的人民都很认真。", "explanation": "这里应该用〈老师〉。人民不用来指学校里的教师，教师要说老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们相信人民们是最有力量的。", "corrected_sentence": "我们相信人民是最有力量的。", "error_description": "错误：人民们；正确：人民。“人民”已表示群众的集合，不能再加“们”，加“们”是把“人民”当作“人们”来用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家有十亿个人民。", "corrected_sentence": "这个国家有十亿人民。", "error_description": "错误：十亿个人民；正确：十亿人民。“人民”是集合名词，不能用个体量词“个”来计数，数词可以直接放在“人民”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85794, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
