INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在一个国家或地区中生活的广大群众，常与“政府”相对。", "primary_collocate": null, "pronunciation": "rén mín", "ipa": "ʐən˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "政府要为人民办实事。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民选出了自己的代表。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位市长一直关心人民的生活。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府的政策让人民过上了好日子。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民对政府的新政策很满意。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的政府应该听人民的话。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府和人民一起努力，国家才会更好。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民需要安全的食品，政府要认真检查。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的政府帮人民修了路。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，政府的钱来自人民交的税。", "target_word": "人民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "与政府相对的广大群众", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25afb08-42c1-4494-8c54-317012e5d40c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85794, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人民", "is_correct": true, "explanation": "正确答案。人民 rén mín，指与政府相对的广大群众。"}, {"text": "人名", "is_correct": false, "explanation": "mín（第二声）与 míng（第二声）韵母不同（in/ing），意思是人的名字。"}, {"text": "人命", "is_correct": false, "explanation": "mín（第二声）与 mìng（第四声）韵母不同（in/ing）且声调不同，意思是人的生命。"}, {"text": "任命", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同；mín 与 mìng 韵母不同（in/ing），意思是委任官职。"}, {"text": "人们", "is_correct": false, "explanation": "mín（第二声）与 men（轻声）声调不同，意思是泛指的人们。"}], "explanations": {"人民": "正确答案。人民 rén mín，指与政府相对的广大群众。", "人名": "mín（第二声）与 míng（第二声）韵母不同（in/ing），意思是人的名字。", "人命": "mín（第二声）与 mìng（第四声）韵母不同（in/ing）且声调不同，意思是人的生命。", "任命": "rén（第二声）与 rèn（第四声）声调不同；mín 与 mìng 韵母不同（in/ing），意思是委任官职。", "人们": "mín（第二声）与 men（轻声）声调不同，意思是泛指的人们。"}, "sentence_index": null, "correct_answer": "人民"}, "level_3": {"options": [{"text": "人民", "is_correct": true, "explanation": "正确答案。人民指与政府相对的广大群众，是“办实事”的服务对象，符合句意。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器是物，不能成为“办实事”的服务对象，句意不通。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”指数量，不能作为“为……办实事”的对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是“办实事”的对象，句意不通。"}], "explanations": {"人民": "正确答案。人民指与政府相对的广大群众，是“办实事”的服务对象，符合句意。", "机器": "语义：机器是物，不能成为“办实事”的服务对象，句意不通。", "人数": "搭配：“人数”指数量，不能作为“为……办实事”的对象。", "天气": "语义：天气不是“办实事”的对象，句意不通。"}, "sentence_index": 0, "correct_answer": "人民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医院的人民都很忙。", "explanation": "这里应该用〈医生〉。人民指与政府相对的广大群众，不用来指医院里的工作人员，这类人要说医生。"}, {"text": "教室里的人民都很安静。", "explanation": "这里应该用〈学生〉。人民指与政府相对的广大群众，不用来指教室里上课的人，这类人要说学生。"}, {"text": "剧院里的人民很多。", "explanation": "这里应该用〈观众〉。人民指与政府相对的广大群众，不用来指剧院里看演出的人，这类人要说观众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人民", "is_correct": true, "explanation": "正确答案。人民指与政府相对的广大群众，与“一起努力”的施事相符，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是有意志的施事，不能与政府“一起努力”，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物，不能“一起努力”，句意不通。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“努力”要求有意志的主体，“数字”不能与“政府”并列作“一起努力”的施事。"}], "explanations": {"人民": "正确答案。人民指与政府相对的广大群众，与“一起努力”的施事相符，句意通顺。", "天气": "语义：天气不是有意志的施事，不能与政府“一起努力”，句意不通。", "桌子": "语义：桌子是物，不能“一起努力”，句意不通。", "数字": "搭配：“努力”要求有意志的主体，“数字”不能与“政府”并列作“一起努力”的施事。"}, "sentence_index": 6, "correct_answer": "人民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司的人民都下班了。", "explanation": "这里应该用〈员工〉。人民指与政府相对的广大群众，不指某个公司的工作人员，后者要说员工。"}, {"text": "车上的人民都下车了。", "explanation": "这里应该用〈乘客〉。人民指广大群众，不用来指某一辆车里的乘客，这类人要说乘客。"}, {"text": "体育场里的人民很多。", "explanation": "这里应该用〈观众〉。人民指广大群众，不用来指体育场里观看比赛的人，这类人要说观众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该相信人民们。", "corrected_sentence": "我们应该相信人民。", "error_description": "错误：人民们；正确：人民。“人民”本身已是指广大群众的集合名词，不能再加“们”。“们”不能直接用在“人民”后面，把“人民”当作“人们”来用是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的政府人民服务。", "corrected_sentence": "我们的政府为人民服务。", "error_description": "错误：漏掉介词“为”；正确：“为人民服务”。“人民”是“服务”的对象，需要用介词“为”引出，去掉“为”后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85795, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
