INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85795, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“其他”是说除了刚才说的以外，别的人或东西。", "primary_collocate": null, "pronunciation": "qí tā", "ipa": "tɕʰi˧˥ tʰa˥", "syllable_count": 2, "sentences": [{"text": "今天只有小明迟到，其他人都到了。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢猫，不喜欢其他动物。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一本书，其他东西都不见了。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了我，其他人都吃过这道菜。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我会，其他的我不知道。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只买了票，其他的钱都存起来了。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了鱼，其他菜在冰箱里。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先走吧，其他事我来做。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有三个门，其他两个门今天关着。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只带了伞，其他东西都放在家里。", "target_word": "其他", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "其他的", "label": "复合"}, {"form": "其它", "label": "异体"}], "register": "中性", "sense_fingerprint": "除刚才说的以外的别的人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25afb08-42c1-4494-8c54-317012e5d40c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "其他", "is_correct": true, "explanation": "正确答案。“其他”指除了刚才说的小明以外的别的人，符合句意。"}, {"text": "所有", "is_correct": false, "explanation": "语义：“所有”包括小明，与“只有小明迟到”矛盾，句意不通。"}, {"text": "任何", "is_correct": false, "explanation": "语义：“任何”包括小明，与“只有小明迟到”矛盾，句意不通。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”包括小明在内，与“只有小明迟到”矛盾，句意不通。"}], "explanations": {"其他": "正确答案。“其他”指除了刚才说的小明以外的别的人，符合句意。", "所有": "语义：“所有”包括小明，与“只有小明迟到”矛盾，句意不通。", "任何": "语义：“任何”包括小明，与“只有小明迟到”矛盾，句意不通。", "全部": "语义：“全部”包括小明在内，与“只有小明迟到”矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "其他"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有两只猫，其他一只很可爱。", "explanation": "这里应该用〈另一只〉。其他指所说以外的别的东西，指两只中的另一只要说“另一只”，“其他”不能与“一只”搭配。"}, {"text": "我买了两杯水，其他一杯给你。", "explanation": "这里应该用〈另一杯〉。其他指别的东西，两杯中的另一杯要说“另一杯”，不说“其他一杯”。"}, {"text": "我有两件衣服，其他一件很贵。", "explanation": "这里应该用〈另一件〉。其他指所说以外的别的东西，指两件中的另一件要说“另一件”，不说“其他一件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其他", "is_correct": true, "explanation": "正确答案。“其他”指妈妈做的鱼以外的别的菜，符合句意。"}, {"text": "其中", "is_correct": false, "explanation": "搭配：“其中”不能直接修饰名词作定语，“其中菜”不成立，句子不通。"}, {"text": "同", "is_correct": false, "explanation": "搭配：“同”不能单独修饰名词，需说“同样的菜”，“同菜”不成立。"}, {"text": "每", "is_correct": false, "explanation": "搭配：“每”后须接量词，应说“每道菜”，“每菜”不成立，句子不能成立。"}], "explanations": {"其他": "正确答案。“其他”指妈妈做的鱼以外的别的菜，符合句意。", "其中": "搭配：“其中”不能直接修饰名词作定语，“其中菜”不成立，句子不通。", "同": "搭配：“同”不能单独修饰名词，需说“同样的菜”，“同菜”不成立。", "每": "搭配：“每”后须接量词，应说“每道菜”，“每菜”不成立，句子不能成立。"}, "sentence_index": 6, "correct_answer": "其他"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架上有三本书，其他一本是我的。", "explanation": "这里应该用〈其中〉。三本里的一本要说“其中一本”，“其他”不能用来指其中的一个。"}, {"text": "我有两个哥哥，其他一个在北京工作。", "explanation": "这里应该用〈另一个〉。其他指所说以外的别的人，指两个中的另一个要说“另一个”，不说“其他一个”。"}, {"text": "我想请假，其他一个原因是我昨天病了。", "explanation": "这里应该用〈另外一个〉。其他指所说以外的别的事物，不能与“一个”搭配来引出补充的理由，补充理由要说“另外一个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经回家了，其他们还在学校。", "corrected_sentence": "他已经回家了，其他人还在学校。", "error_description": "错误：其他们；正确：其他人。“其他”后面要接名词，加“们”不成立，应说“其他人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈做了鱼，其他个菜都做好了。", "corrected_sentence": "妈妈做了鱼，其他菜都做好了。", "error_description": "错误：其他个菜；正确：其他菜。“其他”是代词，修饰名词时不能直接加量词“个”，应直接说“其他菜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85797, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "次要", "is_correct": true, "explanation": "次要：与“主要”构成反义，指不占核心地位的部分。"}, {"text": "普通", "is_correct": false, "explanation": "普通指一般、不特别，与“主要”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "简单指不复杂，与“主要”没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松指不紧张、不费力，与“主要”没有反义关系。"}], "correct_answer": "次要", "explanations": {"次要": "次要：与“主要”构成反义，指不占核心地位的部分。", "普通": "普通指一般、不特别，与“主要”没有反义关系。", "简单": "简单指不复杂，与“主要”没有反义关系。", "轻松": "轻松指不紧张、不费力，与“主要”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85797, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "次要", "is_correct": true, "explanation": "次要：与“主要”构成反义，指不占核心地位的部分。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、分明，与“主要”没有反义关系。"}, {"text": "灵活", "is_correct": false, "explanation": "灵活指不呆板、能变通，与“主要”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静指没有声音或不活跃，与“主要”没有反义关系。"}], "correct_answer": "次要", "explanations": {"次要": "次要：与“主要”构成反义，指不占核心地位的部分。", "清楚": "清楚指明白、分明，与“主要”没有反义关系。", "灵活": "灵活指不呆板、能变通，与“主要”没有反义关系。", "安静": "安静指没有声音或不活跃，与“主要”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85797, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“主要”是说最重要、最大的那一个。", "primary_collocate": null, "pronunciation": "zhǔ yào", "ipa": "ʈʂu˨˩ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "米饭是我们的主要食物。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的主要问题是时间太少。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的主要爱好是看书。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习汉语的主要办法是多说。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的主要街道很干净。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到的主要原因是下雨。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的主要客人是学生。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的主要意思很清楚。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请说一下你们的主要想法。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的主要收入来自爸爸的工作。", "target_word": "主要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词，最重要、最大的那一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主要", "is_correct": true, "explanation": "主要：形容词，指最重要、占最大比重的，修饰“食物”，填入后句意通顺。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或人的状态，不能修饰食物。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人或动物，不说“聪明食物”。"}, {"text": "灵活", "is_correct": false, "explanation": "语义：“灵活”指动作或思路敏捷，不能用来形容食物。"}], "explanations": {"主要": "主要：形容词，指最重要、占最大比重的，修饰“食物”，填入后句意通顺。", "安静": "语义：“安静”形容环境或人的状态，不能修饰食物。", "聪明": "搭配：“聪明”形容人或动物，不说“聪明食物”。", "灵活": "语义：“灵活”指动作或思路敏捷，不能用来形容食物。"}, "sentence_index": 0, "correct_answer": "主要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的主要眼睛近视了。", "explanation": "这里应该用〈左〉或〈右〉，指明是哪一只眼睛。“主要”表示最重要、最大的，不用来区分身体部位，此处搭配不成立。"}, {"text": "这位画家的风格很主要。", "explanation": "这里应该用〈突出〉。“主要”不用来形容风格的显著程度，此处用法不对。"}, {"text": "这次事故的后果很主要。", "explanation": "这里应该用〈严重〉。“主要”说明最核心的部分，不表示后果的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主要", "is_correct": true, "explanation": "主要：形容词，指占最大比重的，修饰“客人”，填入后句意通顺。"}, {"text": "丰富", "is_correct": false, "explanation": "搭配：“丰富”多修饰内容、经验，不修饰人群，不说“丰富的客人”。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”形容明白、分明，不能说明客人的类别。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”形容刀具等物体的尖锐，不能修饰客人。"}], "explanations": {"主要": "主要：形容词，指占最大比重的，修饰“客人”，填入后句意通顺。", "丰富": "搭配：“丰富”多修饰内容、经验，不修饰人群，不说“丰富的客人”。", "清楚": "语义：“清楚”形容明白、分明，不能说明客人的类别。", "锋利": "语义：“锋利”形容刀具等物体的尖锐，不能修饰客人。"}, "sentence_index": 6, "correct_answer": "主要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行对我来说非常主要。", "explanation": "这里应该用〈重要〉。“主要”指最核心的部分，不用来表示事情对人的重要程度。"}, {"text": "他的印象很主要。", "explanation": "这里应该用〈深刻〉。“主要”不用来形容印象的深浅，此处用法不对。"}, {"text": "这本书的内容很主要。", "explanation": "这里应该用〈丰富〉。“主要”表示最核心的部分，不用来形容内容的多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的很主要内容是历史。", "corrected_sentence": "这本书的主要内容是历史。", "error_description": "错误：“很主要内容”；正确：“主要内容”。“主要”直接放在名词前作定语，前面不加“很”，去掉“很”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛的很主要选手来自北京。", "corrected_sentence": "这次比赛的主要选手来自北京。", "error_description": "错误：“很主要选手”；正确：“主要选手”。“主要”直接放在名词前作定语，前面不加“很”，去掉“很”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
