INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85799, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网站是在电脑或手机上看的一个地方，那里有很多文字和图片。", "primary_collocate": null, "pronunciation": "wǎng zhàn", "ipa": "wɑŋ˨˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "我常常上这个网站看新闻。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站有很多图片。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网站上买了一双鞋。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你打开学校的网站。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的字太小了。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网站上找到了地图。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这个网站的名字吗？", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天在网站上看电影。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站可以学英语。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机看了那个网站。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个网站", "label": "量词"}, {"form": "购物网站", "label": "复合"}, {"form": "網站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，在电脑或手机上看的、有文字和图片的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网站", "is_correct": true, "explanation": "正确：网站是可以在上面看新闻的地方，符合句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不能用来看新闻，与“看新闻”冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“上”后面接冰箱说不通，冰箱也不能用来看新闻。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是可以看新闻的地方，与句意不符。"}], "explanations": {"网站": "正确：网站是可以在上面看新闻的地方，符合句意。", "蛋糕": "语义：蛋糕不能用来看新闻，与“看新闻”冲突。", "冰箱": "搭配：“上”后面接冰箱说不通，冰箱也不能用来看新闻。", "书包": "语义：书包不是可以看新闻的地方，与句意不符。"}, "sentence_index": 0, "correct_answer": "网站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在网站吃饭。", "explanation": "这里应该用〈饭馆〉。吃饭要去饭馆，网站不能用来吃饭。"}, {"text": "我们在网站下车。", "explanation": "这里应该用〈车站〉。下车要在车站，网站不是乘车的地方。"}, {"text": "他住在一个大网站里。", "explanation": "这里应该用〈房子〉。人住的地方是房子，网站是网上的站点，不能住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网站", "is_correct": true, "explanation": "正确：网站是有名字的，可以问，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气没有可以问的名字，与“的名字”冲突。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空一般不说“的名字”，与句意不符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”一般不说“的名字”，与“你知道……吗”的问法不搭。"}], "explanations": {"网站": "正确：网站是有名字的，可以问，符合句意。", "空气": "语义：空气没有可以问的名字，与“的名字”冲突。", "天空": "语义：天空一般不说“的名字”，与句意不符。", "天气": "搭配：“天气”一般不说“的名字”，与“你知道……吗”的问法不搭。"}, "sentence_index": 6, "correct_answer": "网站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们新开了一台网站。", "explanation": "这里应该用〈个〉。“台”多用于机器、电器，网站不用“台”。"}, {"text": "我买了一张网站。", "explanation": "这里应该用〈个〉。“张”多用于纸张、桌子等平面的东西，网站不用“张”。"}, {"text": "妈妈有一本网站。", "explanation": "这里应该用〈个〉。“本”用于书籍、杂志，网站不用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我常常在学校网站下查成绩。", "corrected_sentence": "我常常在学校网站上查成绩。", "error_description": "错误：方位词用错。“网站”后面应用“上”，说“在学校网站上查成绩”，不能用“下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校新建了一只网站。", "corrected_sentence": "我们学校新建了一个网站。", "error_description": "错误：量词用错。“只”多用于动物，网站应该用“个”，说“一个网站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
