INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "互联网上由若干网页组成、提供信息或服务的站点。", "primary_collocate": null, "pronunciation": "wǎng zhàn", "ipa": "wɑŋ˨˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司的网站每天更新信息。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府网站提供免费的服务。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们新做了一个购物网站。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户要先在网站上注册。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的访问量很大。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的网站出了问题。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校网站上有招生信息。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新闻网站有很多读者。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的网站支持手机登录。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请到银行网站查看账单。", "target_word": "网站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个网站", "label": "量词"}, {"form": "购物网站", "label": "复合"}, {"form": "網站", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，互联网上由网页组成、提供信息或服务的站点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网站", "is_correct": true, "explanation": "正确：网站可以每天更新信息，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会更新信息，与句意冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是发布信息的地方，不会每天更新信息。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“每天更新信息”一般不与花园搭配。"}], "explanations": {"网站": "正确：网站可以每天更新信息，符合句意。", "石头": "语义：石头不会更新信息，与句意冲突。", "冰箱": "语义：冰箱不是发布信息的地方，不会每天更新信息。", "花园": "搭配：“每天更新信息”一般不与花园搭配。"}, "sentence_index": 0, "correct_answer": "网站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在网站散步。", "explanation": "这里应该用〈公园〉。散步要去公园，网站不是可以散步的地方。"}, {"text": "我在网站等了十分钟的车。", "explanation": "这里应该用〈车站〉。等车要在车站，网站不是等车的地方。"}, {"text": "我们在网站里吃饭。", "explanation": "这里应该用〈饭馆〉。吃饭要去饭馆，网站不能用来吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网站", "is_correct": true, "explanation": "正确：学校网站上可以有招生信息，符合句意。"}, {"text": "树林", "is_correct": false, "explanation": "语义：树林上不会有招生信息，与句意冲突。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“招生信息”一般不印在饼干上，与“上有……信息”不搭。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕上不会有学校的招生信息，句意不通。"}], "explanations": {"网站": "正确：学校网站上可以有招生信息，符合句意。", "树林": "语义：树林上不会有招生信息，与句意冲突。", "饼干": "搭配：“招生信息”一般不印在饼干上，与“上有……信息”不搭。", "蛋糕": "语义：蛋糕上不会有学校的招生信息，句意不通。"}, "sentence_index": 6, "correct_answer": "网站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家银行新建了一张网站。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，网站不用“张”。"}, {"text": "我家有一本网站。", "explanation": "这里应该用〈个〉。“本”用于书籍，网站不用“本”。"}, {"text": "我们班有一条网站。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，网站不用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们可以网站上下载文件。", "corrected_sentence": "我们可以在网站上下载文件。", "error_description": "错误：处所介词“在”不能省。“网站”作下载的处所，要说“在网站上下载文件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司新做了一台网站。", "corrected_sentence": "这家公司新做了一个网站。", "error_description": "错误：量词用错。“台”用于机器、电器，网站应该用“个”，说“一个网站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
