INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来表示次序的数字或标记，如排队号、床号、球衣号码。", "primary_collocate": null, "pronunciation": "hào", "ipa": "xɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "医生在叫五十号。", "target_word": "号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我取了一个号，在门口等。", "target_word": "号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人在三号床。", "target_word": "号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在叫到二十号了。", "target_word": "号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的号是多少？", "target_word": "号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的球衣是十号。", "target_word": "号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "先拿号，再排队。", "target_word": "号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我排在第三十号。", "target_word": "号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个号已经叫过了。", "target_word": "号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面还有十个号，请等一下。", "target_word": "号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示次序的数字或标记，如排队号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df888c7e-00bf-4d04-9d58-c326ae2207d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85802, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "号", "is_correct": true, "explanation": "号（hào，第四声）：表示次序的数字或标记，是正确答案。"}, {"text": "厚", "is_correct": false, "explanation": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是厚。"}, {"text": "后", "is_correct": false, "explanation": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是后面。"}, {"text": "害", "is_correct": false, "explanation": "hài 与 hào 只有韵母不同（ai 与 ao），声调相同，意思是伤害。"}, {"text": "嚎", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，意思是大声哭叫。"}], "explanations": {"号": "号（hào，第四声）：表示次序的数字或标记，是正确答案。", "厚": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是厚。", "后": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是后面。", "害": "hài 与 hào 只有韵母不同（ai 与 ao），声调相同，意思是伤害。", "嚎": "háo（第二声）与 hào（第四声）声调不同，意思是大声哭叫。"}, "sentence_index": null, "correct_answer": "号"}, "level_3": {"options": [{"text": "号", "is_correct": true, "explanation": "号：表示次序的数字，“叫五十号”中用它，是正确答案。"}, {"text": "楼", "is_correct": false, "explanation": "语义：“楼”指建筑或楼层，“医生在叫五十楼”不通。"}, {"text": "车", "is_correct": false, "explanation": "语义：“车”是交通工具，不能用来叫号，此处意思不合。"}, {"text": "班", "is_correct": false, "explanation": "搭配：叫号时接序号用“号”，不说“五十班”。"}], "explanations": {"号": "号：表示次序的数字，“叫五十号”中用它，是正确答案。", "楼": "语义：“楼”指建筑或楼层，“医生在叫五十楼”不通。", "车": "语义：“车”是交通工具，不能用来叫号，此处意思不合。", "班": "搭配：叫号时接序号用“号”，不说“五十班”。"}, "sentence_index": 0, "correct_answer": "号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学成绩是三号。", "explanation": "这里应该用〈分〉。成绩用“分”，“号”表示编号或次序，不能表示分数。"}, {"text": "他的身高是一百七十号。", "explanation": "这里应该用〈厘米〉。身高用“厘米”，“号”不能用作长度单位。"}, {"text": "这件衣服的价格是五十号。", "explanation": "这里应该用〈元〉。价格用“元”，“号”不能表示金额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85802, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "号", "is_correct": true, "explanation": "号（hào，第四声）：表示次序的数字或标记，是正确答案。"}, {"text": "好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是好。"}, {"text": "毫", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，意思是毫米。"}, {"text": "豪", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，意思是豪迈。"}, {"text": "候", "is_correct": false, "explanation": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是等候。"}], "explanations": {"号": "号（hào，第四声）：表示次序的数字或标记，是正确答案。", "好": "hǎo（第三声）与 hào（第四声）声调不同，意思是好。", "毫": "háo（第二声）与 hào（第四声）声调不同，意思是毫米。", "豪": "háo（第二声）与 hào（第四声）声调不同，意思是豪迈。", "候": "hòu 与 hào 只有韵母不同（ou 与 ao），声调相同，意思是等候。"}, "sentence_index": null, "correct_answer": "号"}, "level_3": {"options": [{"text": "号", "is_correct": true, "explanation": "号：表示次序的标记，“先拿号”中用它，是正确答案。"}, {"text": "河", "is_correct": false, "explanation": "语义：“河”是自然地物，不能“拿”，此处意思不合。"}, {"text": "桌", "is_correct": false, "explanation": "搭配：“拿”一般搭配小件物品，不能说“拿桌”。"}, {"text": "锅", "is_correct": false, "explanation": "语义：“锅”是炊具，与排队无关，此处意思不合。"}], "explanations": {"号": "号：表示次序的标记，“先拿号”中用它，是正确答案。", "河": "语义：“河”是自然地物，不能“拿”，此处意思不合。", "桌": "搭配：“拿”一般搭配小件物品，不能说“拿桌”。", "锅": "语义：“锅”是炊具，与排队无关，此处意思不合。"}, "sentence_index": 6, "correct_answer": "号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我的银行卡密号。", "explanation": "这里应该用〈码〉。“密码”是固定说法，“号”表示次序或编号，不能用于密码。"}, {"text": "他每天吃两号饭。", "explanation": "这里应该用〈顿〉。吃饭的次数用“顿”，“号”不能用来计数动作。"}, {"text": "这根绳子有三号长。", "explanation": "这里应该用〈米〉。长度要用“米”等单位，“号”表示编号，不能表示长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在门口取了一只号。", "corrected_sentence": "他在门口取了一个号。", "error_description": "量词用错。“取号”的号是一个号码牌，应用量词“个”，不能用“只”（“只”用于小动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你的号是几只号？", "corrected_sentence": "你的号是几号？", "error_description": "量词用错。“只”用于小动物或成对物品中的一个，不能用来计数“号”；询问号码应说“几号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
