INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85807, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85807, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“通过”是说用某个办法或借助某个人、某种东西，做成一件事。", "primary_collocate": null, "pronunciation": "tōng guò", "ipa": "tʰʊŋ˥ kwo˥˩", "syllable_count": 2, "sentences": [{"text": "我通过朋友认识了他。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他通过努力学会了游泳。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过这个网站，你可以买到便宜的书。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们通过电话说了这件事。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她通过看电影学习英语。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过听歌，我学会了很多中文词。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他通过查资料，终于找到了答案。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过这次比赛，我们成了好朋友。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过读书，他知道了很多事情。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过每天练习，他的汉字写得好多了。", "target_word": "通过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "借助某种方法或途径做成事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25afb08-42c1-4494-8c54-317012e5d40c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85807, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通过", "is_correct": true, "explanation": "正确。听到的是“通过”（tōng guò）。"}, {"text": "铜锅", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，guō（第一声）与 guò（第四声）声调也不同，意思是铜锅。"}, {"text": "通货", "is_correct": false, "explanation": "huò 与 guò 的声母不同（h 与 g），声调相同，意思是通货、货币。"}, {"text": "同伙", "is_correct": false, "explanation": "tóng（第二声）与 tōng（第一声）声调不同，huǒ（第三声）与 guò（第四声）声母和声调都不同，意思是同伙。"}], "explanations": {"通过": "正确。听到的是“通过”（tōng guò）。", "铜锅": "tóng（第二声）与 tōng（第一声）声调不同，guō（第一声）与 guò（第四声）声调也不同，意思是铜锅。", "通货": "huò 与 guò 的声母不同（h 与 g），声调相同，意思是通货、货币。", "同伙": "tóng（第二声）与 tōng（第一声）声调不同，huǒ（第三声）与 guò（第四声）声母和声调都不同，意思是同伙。"}, "sentence_index": null, "correct_answer": "通过"}, "level_3": {"options": [{"text": "通过", "is_correct": true, "explanation": "正确。“通过”表示借助朋友这一途径，与句意相符。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”后接规定、计划等标准，不能接“朋友”这样的人。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，不表示认识他的途径，句子说的是通过朋友认识。"}, {"text": "根据", "is_correct": false, "explanation": "搭配：“根据”后接事实、资料等依据，不能接人，这里说的是凭借朋友。"}], "explanations": {"通过": "正确。“通过”表示借助朋友这一途径，与句意相符。", "按照": "搭配：“按照”后接规定、计划等标准，不能接“朋友”这样的人。", "为了": "语义：“为了”表示目的，不表示认识他的途径，句子说的是通过朋友认识。", "根据": "搭配：“根据”后接事实、资料等依据，不能接人，这里说的是凭借朋友。"}, "sentence_index": 0, "correct_answer": "通过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事通过了三年才解决。", "explanation": "这里应该用〈经过〉。“经过”可以表示时间的流逝，“通过”表示借助某种途径或方法，不能接一段时间。"}, {"text": "他通过很累，早早就睡了。", "explanation": "这里应该用〈因为〉。“通过”引出的是方式或途径，不表示原因；应说「因为很累，他早早就睡了」。"}, {"text": "他通过星期天，去了公园。", "explanation": "这里应该用〈在〉。“通过”引出的是方式或途径，不表示时间；应说「他在星期天去了公园」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通过", "is_correct": true, "explanation": "正确。“通过”表示借助查资料这一方法，与句意相符。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，不表示凭借的方法，“对查资料”不能说明找到答案的途径。"}, {"text": "从", "is_correct": false, "explanation": "配价：“从”后接起点或来源名词，不能直接接“查资料”这样的动作。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”后接对象或方向，不能接“查资料”这样的动作。"}], "explanations": {"通过": "正确。“通过”表示借助查资料这一方法，与句意相符。", "对": "语义：“对”引出对象，不表示凭借的方法，“对查资料”不能说明找到答案的途径。", "从": "配价：“从”后接起点或来源名词，不能直接接“查资料”这样的动作。", "向": "配价：“向”后接对象或方向，不能接“查资料”这样的动作。"}, "sentence_index": 6, "correct_answer": "通过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他通过生病请了假。", "explanation": "这里应该用〈因为〉。“通过”引出的是方式或途径，不表示原因；因病请假应说「因为生病请了假」。"}, {"text": "她通过开心笑了起来。", "explanation": "这里应该用〈高兴地〉。“通过”引出方式时不能直接接形容词作方式状语；应说「她高兴地笑了起来」。"}, {"text": "她通过半小时，就做完了作业。", "explanation": "这里应该用〈只用〉。“通过”引出的是方式或途径，不表示所用时间；应说「她只用半小时就做完了作业」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们通过了电话讨论了计划。", "corrected_sentence": "我们通过电话讨论了计划。", "error_description": "错误：“通过了”；正确：“通过”。“通过”作介词引出方式，后面不能加“了”，“了”只用在句末的“讨论了计划”中。正确：「我们通过电话讨论了计划」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明通过了打工挣了钱。", "corrected_sentence": "小明通过打工挣了钱。", "error_description": "错误：“通过了打工”；正确：“通过打工”。“通过”作介词引出方式，后面不能加“了”，“了”只用在句末的“挣了钱”中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
