INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85809, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小学是小朋友上的学校。孩子长到六七岁，就去那里读书。", "primary_collocate": null, "pronunciation": "xiǎo xué", "ipa": "ɕiɑʊ̯˨˩˦ ɕyɛ˧˥", "syllable_count": 2, "sentences": [{"text": "我家旁边有一所小学，每天都有很多孩子去上学。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子六岁就要上小学了。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小学教语文。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学离我家很近，走路五分钟。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟今年小学毕业了。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所小学有三百个孩子。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上七点，小学门口有很多家长来送孩子上学。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我六岁时，妈妈送我去小学报名。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学的老师对孩子们很好。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他小时候在同一所小学读书，今天他来看我。", "target_word": "小学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "小學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小学：六七岁孩子读书的学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '474535a0-0dad-4240-b06c-55efe2468b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85809, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小学", "is_correct": true, "explanation": "正确答案：小学 xiǎo xué，指小朋友上的学校。"}, {"text": "小写", "is_correct": false, "explanation": "小写 xiǎoxiě 与 小学 xiǎoxué 末字韵母不同（ie 与 ue），声调也不同（第三声与第二声），意思是字母的小写形式。"}, {"text": "小雪", "is_correct": false, "explanation": "小雪 xiǎoxuě 与 小学 xiǎoxué 只是末字声调不同（第三声与第二声），意思是二十四节气之一。"}, {"text": "小鞋", "is_correct": false, "explanation": "小鞋 xiǎoxié 与 小学 xiǎoxué 末字韵母不同（ie 与 ue），声调相同，意思是小号的鞋。"}], "explanations": {"小学": "正确答案：小学 xiǎo xué，指小朋友上的学校。", "小写": "小写 xiǎoxiě 与 小学 xiǎoxué 末字韵母不同（ie 与 ue），声调也不同（第三声与第二声），意思是字母的小写形式。", "小雪": "小雪 xiǎoxuě 与 小学 xiǎoxué 只是末字声调不同（第三声与第二声），意思是二十四节气之一。", "小鞋": "小鞋 xiǎoxié 与 小学 xiǎoxué 末字韵母不同（ie 与 ue），声调相同，意思是小号的鞋。"}, "sentence_index": null, "correct_answer": "小学"}, "level_3": {"options": [{"text": "小学", "is_correct": true, "explanation": "正确：小学指小朋友上的学校，与“一所”搭配，符合“我家旁边”的语境。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱是关押罪犯的地方，“我家旁边有一所监狱”与日常居住的语境不符。"}, {"text": "研究所", "is_correct": false, "explanation": "语义：研究所是科研机构，不是孩子上学的地方，与句中“孩子去上学”矛盾。"}, {"text": "疗养院", "is_correct": false, "explanation": "语义：疗养院是供人休养治疗的机构，不是孩子上学的地方，与句中“孩子去上学”矛盾。"}], "explanations": {"小学": "正确：小学指小朋友上的学校，与“一所”搭配，符合“我家旁边”的语境。", "监狱": "语义：监狱是关押罪犯的地方，“我家旁边有一所监狱”与日常居住的语境不符。", "研究所": "语义：研究所是科研机构，不是孩子上学的地方，与句中“孩子去上学”矛盾。", "疗养院": "语义：疗养院是供人休养治疗的机构，不是孩子上学的地方，与句中“孩子去上学”矛盾。"}, "sentence_index": 0, "correct_answer": "小学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我女儿才三岁，每天都去小学。", "explanation": "这里应该用〈幼儿园〉。小学是六七岁以上儿童读书的学校，三岁孩子应去幼儿园。"}, {"text": "我哥哥今年二十岁，正在小学读书。", "explanation": "这里应该用〈大学〉。小学只招收儿童，二十岁的人读的是大学。"}, {"text": "我姐姐十三岁，已经在小学上初一了。", "explanation": "这里应该用〈中学〉。初一属于中学，小学只有一至六年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小学", "is_correct": true, "explanation": "正确：小学是小朋友上的学校，家长聚集在校门口接送孩子，符合句中语境。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理金融业务的地方，早上七点门口聚集很多家长不合常理。"}, {"text": "超市", "is_correct": false, "explanation": "搭配：“家长”多指孩子的父母，超市门口一般不说“很多家长”聚集。"}, {"text": "机场", "is_correct": false, "explanation": "语义：机场门口多是出行的旅客，与“家长”聚集的语境不合。"}], "explanations": {"小学": "正确：小学是小朋友上的学校，家长聚集在校门口接送孩子，符合句中语境。", "银行": "语义：银行是办理金融业务的地方，早上七点门口聚集很多家长不合常理。", "超市": "搭配：“家长”多指孩子的父母，超市门口一般不说“很多家长”聚集。", "机场": "语义：机场门口多是出行的旅客，与“家长”聚集的语境不合。"}, "sentence_index": 6, "correct_answer": "小学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子刚满一岁，每天都去小学。", "explanation": "这里应该用〈托儿所〉。小学招收六七岁以上的儿童，一岁的孩子应去托儿所。"}, {"text": "他今年十七岁，还在小学读书。", "explanation": "这里应该用〈高中〉。小学只招收六七岁以上的儿童，十七岁的学生应读高中。"}, {"text": "他今年二十五岁，正在小学读书。", "explanation": "这里应该用〈研究生院〉。小学招收儿童，二十五岁的人应在研究生院读书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区附近新建了一只小学。", "corrected_sentence": "我们小区附近新建了一所小学。", "error_description": "量词错误：学校这类机构用量词“所”，不用“只”。“一只小学”应改为“一所小学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐从小学了毕业，就去了中学。", "corrected_sentence": "我姐姐从小学毕业，就去了中学。", "error_description": "了的位置错误：“了”插在“小学”和动词“毕业”之间，应删去，说“从小学毕业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85811, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱小", "is_correct": true, "explanation": "“弱小”与“强大”在力量意义上构成反义关系。"}, {"text": "温柔", "is_correct": false, "explanation": "与“强大”没有反义关系，“温柔”指性情柔和。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“强大”没有反义关系，“漂亮”指外貌好看。"}, {"text": "聪明", "is_correct": false, "explanation": "与“强大”没有反义关系，“聪明”指头脑灵活。"}], "correct_answer": "弱小", "explanations": {"弱小": "“弱小”与“强大”在力量意义上构成反义关系。", "温柔": "与“强大”没有反义关系，“温柔”指性情柔和。", "漂亮": "与“强大”没有反义关系，“漂亮”指外貌好看。", "聪明": "与“强大”没有反义关系，“聪明”指头脑灵活。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85811, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱小", "is_correct": true, "explanation": "“弱小”与“强大”在力量意义上构成反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "与“强大”没有反义关系，“美丽”指外貌好看。"}, {"text": "善良", "is_correct": false, "explanation": "与“强大”没有反义关系，“善良”指品性和心地。"}, {"text": "简单", "is_correct": false, "explanation": "与“强大”没有反义关系，“简单”指不复杂。"}], "correct_answer": "弱小", "explanations": {"弱小": "“弱小”与“强大”在力量意义上构成反义关系。", "美丽": "与“强大”没有反义关系，“美丽”指外貌好看。", "善良": "与“强大”没有反义关系，“善良”指品性和心地。", "简单": "与“强大”没有反义关系，“简单”指不复杂。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85811, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "强大就是很有力气，很厉害，别人打不过它。", "primary_collocate": null, "pronunciation": "qiáng dà", "ipa": "t͡ɕʰi̯ɑŋ˧˥ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "这只老虎很强大，别的动物都怕它。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那头狮子非常强大，谁也打不过它。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象很强大，可以推倒一棵树。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩想变得强大，所以每天练习跑步。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条龙强大又可怕，没有人能打赢它。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的大英雄非常强大，坏人都打不过他。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗不大，但是它很强大，大狗也怕它。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很强大，一个人能打败三个坏人。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个强大的巨人一拳打倒了大树。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望自己长大后变得很强大。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "強大", "label": "繁体"}], "register": "中性", "sense_fingerprint": "力气大、很厉害，别人打不过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a956c441-19d3-4000-954b-c5a96b39ceec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强大", "is_correct": true, "explanation": "“强大”形容这只老虎力量大，所以别的动物都怕它，句意通顺。"}, {"text": "弱小", "is_correct": false, "explanation": "语义：“弱小”与“别的动物都怕它”的意思相矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”描述体型，与老虎令其他动物害怕的描述不符。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”与“别的动物都怕它”的意思相矛盾。"}], "explanations": {"强大": "“强大”形容这只老虎力量大，所以别的动物都怕它，句意通顺。", "弱小": "语义：“弱小”与“别的动物都怕它”的意思相矛盾。", "矮小": "体貌：“矮小”描述体型，与老虎令其他动物害怕的描述不符。", "温柔": "语义：“温柔”与“别的动物都怕它”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "强大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间房子很强大，住得下十个人。", "explanation": "这里应该用〈宽敞〉。形容空间大要用“宽敞”，“强大”形容力气或力量，不用来形容房间。"}, {"text": "这首歌很强大，大家都喜欢听。", "explanation": "这里应该用〈动听〉。形容歌曲、声音好听要用“动听”，“强大”形容力气，不用来形容歌。"}, {"text": "阳光很强大，晒得人睁不开眼。", "explanation": "这里应该用〈强烈〉。形容阳光、风等程度高要用“强烈”，“强大”不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强大", "is_correct": true, "explanation": "“强大”与前句“不大”形成转折，说明它力量很大，大狗也怕它。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：句中说“不大”，“高大”与之矛盾。"}, {"text": "胆小", "is_correct": false, "explanation": "语义：“胆小”与“大狗也怕它”的意思相矛盾。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”与“大狗也怕它”的意思相矛盾。"}], "explanations": {"强大": "“强大”与前句“不大”形成转折，说明它力量很大，大狗也怕它。", "高大": "体貌：句中说“不大”，“高大”与之矛盾。", "胆小": "语义：“胆小”与“大狗也怕它”的意思相矛盾。", "脆弱": "语义：“脆弱”与“大狗也怕它”的意思相矛盾。"}, "sentence_index": 6, "correct_answer": "强大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次事故的损失很强大。", "explanation": "这里应该用〈巨大〉。损失、数量等要用“巨大”，“强大”指力量或势力。"}, {"text": "这座桥很强大，车子都能过。", "explanation": "这里应该用〈坚固〉。形容建筑、物体结实要用“坚固”，“强大”不用于此。"}, {"text": "这块石头很强大，可以用来做刀。", "explanation": "这里应该用〈坚硬〉。形容石头、金属等质地硬要用“坚硬”，“强大”形容力气，不用来形容石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只老虎变得很强大着。", "corrected_sentence": "这只老虎变得很强大。", "error_description": "体标错误：“强大”形容力气或力量的状态，“变得很强大”后一般不再加“着”，“很强大着”不自然，应去掉“着”，说“变得很强大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直想让自己强大出来。", "corrected_sentence": "他一直想让自己强大起来。", "error_description": "趋向补语错误：表示“变强”的变化应用“起来”，应说“强大起来”，不能说“强大出来”（“出来”表示由内向外显现）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85812, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱小", "is_correct": true, "explanation": "“弱小”与“强大”是反义词，指力量薄弱、实力弱，与“实力很强”相反。"}, {"text": "温柔", "is_correct": false, "explanation": "与“强大”无反义关系：“温柔”形容性格或态度柔和，与力量无关。"}, {"text": "干净", "is_correct": false, "explanation": "与“强大”无反义关系：“干净”指没有污物，与力量无关。"}, {"text": "清楚", "is_correct": false, "explanation": "与“强大”无反义关系：“清楚”指明白、不模糊，与力量无关。"}], "correct_answer": "弱小", "explanations": {"弱小": "“弱小”与“强大”是反义词，指力量薄弱、实力弱，与“实力很强”相反。", "温柔": "与“强大”无反义关系：“温柔”形容性格或态度柔和，与力量无关。", "干净": "与“强大”无反义关系：“干净”指没有污物，与力量无关。", "清楚": "与“强大”无反义关系：“清楚”指明白、不模糊，与力量无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85812, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱小", "is_correct": true, "explanation": "“弱小”与“强大”是反义词，指力量薄弱、实力弱，与“实力很强”相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“强大”无反义关系：“漂亮”形容外貌好看，与力量无关。"}, {"text": "明亮", "is_correct": false, "explanation": "与“强大”无反义关系：“明亮”指光线充足或颜色鲜明，与力量无关。"}, {"text": "安静", "is_correct": false, "explanation": "与“强大”无反义关系：“安静”指没有声音或动作，与力量无关。"}], "correct_answer": "弱小", "explanations": {"弱小": "“弱小”与“强大”是反义词，指力量薄弱、实力弱，与“实力很强”相反。", "漂亮": "与“强大”无反义关系：“漂亮”形容外貌好看，与力量无关。", "明亮": "与“强大”无反义关系：“明亮”指光线充足或颜色鲜明，与力量无关。", "安静": "与“强大”无反义关系：“安静”指没有声音或动作，与力量无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85812, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "力量雄厚，实力很强。", "primary_collocate": null, "pronunciation": "qiáng dà", "ipa": "t͡ɕʰi̯ɑŋ˧˥ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "中国的经济越来越强大。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司很强大，在世界各地都有工厂。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的球队非常强大，今年又拿了第一。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家强大了，人民的生活也好了。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要建设一个强大的国家。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手的实力强大，我们要认真准备。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司有强大的技术和很多钱。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队强大，别的国家不敢来打。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队阵容强大，很难赢它。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司变得强大以后，开了很多分店。", "target_word": "强大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "強大", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国家、组织等力量雄厚、实力强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a956c441-19d3-4000-954b-c5a96b39ceec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强大", "is_correct": true, "explanation": "“强大”修饰“经济”，指实力雄厚、力量越来越大，与“越来越”表示的增长义相合。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄，不能用来形容经济。"}, {"text": "幼小", "is_correct": false, "explanation": "语义：“幼小”指年纪小、体形小，与“经济越来越……”所表示的发展壮大正好相反。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：“粗壮”形容人或动物的身体，不用于描述经济。"}], "explanations": {"强大": "“强大”修饰“经济”，指实力雄厚、力量越来越大，与“越来越”表示的增长义相合。", "年轻": "搭配：“年轻”说人的年龄，不能用来形容经济。", "幼小": "语义：“幼小”指年纪小、体形小，与“经济越来越……”所表示的发展壮大正好相反。", "粗壮": "体貌：“粗壮”形容人或动物的身体，不用于描述经济。"}, "sentence_index": 0, "correct_answer": "强大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地毯很强大，踩上去很软。", "explanation": "这里应该用〈柔软〉。形容质地软要用“柔软”，“强大”指力量雄厚，不用来形容地毯。"}, {"text": "中国的人口很强大。", "explanation": "这里应该用〈庞大〉。庞大用于数量或规模，人口多要说庞大；强大指力量雄厚，不用来形容人口。"}, {"text": "这座宫殿很强大。", "explanation": "这里应该用〈雄伟〉。雄伟形容建筑、山河的壮观，强大指力量，不用来形容建筑的外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强大", "is_correct": true, "explanation": "“强大”修饰“技术”，指实力雄厚，与“很多钱”的支撑相合。"}, {"text": "贫穷", "is_correct": false, "explanation": "搭配：“贫穷”形容人或地区的经济状况，不修饰“技术”。"}, {"text": "年幼", "is_correct": false, "explanation": "语义：“年幼”指年纪小，不能用来形容技术。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或建筑的体形，不说技术高大。"}], "explanations": {"强大": "“强大”修饰“技术”，指实力雄厚，与“很多钱”的支撑相合。", "贫穷": "搭配：“贫穷”形容人或地区的经济状况，不修饰“技术”。", "年幼": "语义：“年幼”指年纪小，不能用来形容技术。", "高大": "体貌：“高大”形容身材或建筑的体形，不说技术高大。"}, "sentence_index": 6, "correct_answer": "强大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的阳光很强大，记得戴帽子。", "explanation": "这里应该用〈强〉。强可用于光线、风力等程度，强大指力量雄厚，不用来形容光线。"}, {"text": "这盘菜很强大，大家都吃光了。", "explanation": "这里应该用〈美味〉。形容食物好吃要用“美味”，“强大”指力量雄厚，不用来形容菜。"}, {"text": "这座桥很强大，车可以通过。", "explanation": "这里应该用〈结实〉。结实形容物体坚固，强大指力量，不用来形容桥的坚固程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的国家慢慢强大下来了。", "corrected_sentence": "我们的国家慢慢强大起来了。", "error_description": "趋向补语错误：表示由弱到强的变化应用“起来”，不能用“下来”。“下来”多表示由高到低或趋于稳定，不能表示“慢慢变强”，应说“慢慢强大起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家一直很强大着。", "corrected_sentence": "这个国家一直很强大。", "error_description": "体标错误：“强大”描述抽象的实力，不说“很强大着”这种带“着”的持续状态，应去掉“着”，说“一直很强大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
