INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85813, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“同时”是说两件事在一样的时候发生。", "primary_collocate": null, "pronunciation": "tóng shí", "ipa": "tʰʊŋ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他们两个人同时到了学校门口。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不能同时做两件事。", "target_word": "同时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听到铃声，大家同时站了起来。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两辆车同时开到了路口。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说完，学生们同时笑了。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听课的时候，他同时在做笔记。", "target_word": "同时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始时，两个人同时跑了出去。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门一开，孩子们同时跑了进来。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别同时吃这两种药，会不舒服。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥和姐姐同时给我打电话。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "同时:两件事在同一时间发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25afb08-42c1-4494-8c54-317012e5d40c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85813, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同时", "is_correct": true, "explanation": "正确。听到的是“同时”（tóng shí）。"}, {"text": "同事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是同事。"}, {"text": "同志", "is_correct": false, "explanation": "zhì 与 shí 的声母不同（zh 与 sh），声调也不同，意思是同志。"}, {"text": "通史", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，shǐ（第三声）与 shí（第二声）声调也不同，意思是通史。"}, {"text": "通知", "is_correct": false, "explanation": "tōng 与 tóng 声调不同，zhī 与 shí 的声母不同（zh 与 sh）且声调不同，意思是通知。"}], "explanations": {"同时": "正确。听到的是“同时”（tóng shí）。", "同事": "shì（第四声）与 shí（第二声）声调不同，意思是同事。", "同志": "zhì 与 shí 的声母不同（zh 与 sh），声调也不同，意思是同志。", "通史": "tōng（第一声）与 tóng（第二声）声调不同，shǐ（第三声）与 shí（第二声）声调也不同，意思是通史。", "通知": "tōng 与 tóng 声调不同，zhī 与 shí 的声母不同（zh 与 sh）且声调不同，意思是通知。"}, "sentence_index": null, "correct_answer": "同时"}, "level_3": {"options": [{"text": "同时", "is_correct": true, "explanation": "正确。“同时”表示两人在同一时间到达，与句意相符。"}, {"text": "或者", "is_correct": false, "explanation": "语法：“或者”连接可供选择的成分，句中没有可选并列项，不能直接放在动词前。"}, {"text": "而且", "is_correct": false, "explanation": "语法：“而且”连接并列成分，前面没有可并列的内容，不能直接放在动词前。"}, {"text": "遂", "is_correct": false, "explanation": "语域：“遂”是文言用法，现代口语中不用，这里应说得更口语化。"}], "explanations": {"同时": "正确。“同时”表示两人在同一时间到达，与句意相符。", "或者": "语法：“或者”连接可供选择的成分，句中没有可选并列项，不能直接放在动词前。", "而且": "语法：“而且”连接并列成分，前面没有可并列的内容，不能直接放在动词前。", "遂": "语域：“遂”是文言用法，现代口语中不用，这里应说得更口语化。"}, "sentence_index": 0, "correct_answer": "同时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两道题同时难。", "explanation": "这里应该用〈同样〉。“同时”表示两件事在同一时间发生，不用来形容性质或程度。"}, {"text": "他每天早上七点同时起床。", "explanation": "这里应该用〈准时〉。“同时”表示两件事在同一时间发生，这里只有他一个人起床，没有另一件事与之同时，应说「每天早上七点准时起床」。"}, {"text": "我同时就去。", "explanation": "这里应该用〈马上〉。“马上”表示很快发生，“同时”不表示立刻，这里不能说“同时就去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同时", "is_correct": true, "explanation": "正确。“同时”表示两人在比赛开始的同一时刻跑出去，与句意相符。"}, {"text": "唯一", "is_correct": false, "explanation": "语义：“唯一”指只有一个，与“两个人”相矛盾。"}, {"text": "连续", "is_correct": false, "explanation": "搭配：“连续”多与次数、天数等连用，不说“两个人连续跑了出去”。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”指长期以来的习惯，与“比赛开始时”这一时刻不符。"}], "explanations": {"同时": "正确。“同时”表示两人在比赛开始的同一时刻跑出去，与句意相符。", "唯一": "语义：“唯一”指只有一个，与“两个人”相矛盾。", "连续": "搭配：“连续”多与次数、天数等连用，不说“两个人连续跑了出去”。", "一向": "语义：“一向”指长期以来的习惯，与“比赛开始时”这一时刻不符。"}, "sentence_index": 6, "correct_answer": "同时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我同时吃了三个包子。", "explanation": "这里应该用〈一口气〉。“同时”要求两件事在同一时间发生，这里只有吃包子一件事，应说「一口气吃了三个包子」。"}, {"text": "我们吃完饭同时去学校。", "explanation": "这里应该用〈再〉。“同时”表示两件事在同一时间发生，而“吃完饭”和“去学校”有先后，应说「吃完饭再去学校」。"}, {"text": "他先去超市，同时去银行。", "explanation": "这里应该用〈然后〉。“同时”不表示先后顺序，先去超市再去银行应说「他先去超市，然后去银行」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个孩子同时的举起了手。", "corrected_sentence": "两个孩子同时举起了手。", "error_description": "错误：“同时”作状语，后面不能加“的”。正确：「两个孩子同时举起了手。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个人和同时做完了作业。", "corrected_sentence": "三个人同时做完了作业。", "error_description": "错误：“同时”前面加了连词“和”。“和”连接名词性成分，“同时”是副词，应直接放在动词前。正确：「三个人同时做完了作业。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
