INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85814, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示在前述内容之外并且、另外，用于递进补充。", "primary_collocate": null, "pronunciation": "tóng shí", "ipa": "tʰʊŋ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "这份工作很累，同时也很有意思。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我的老师，同时也是我的朋友。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学汉语要多说，同时还要多听。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手机便宜，同时质量也不错。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要努力工作，同时也要注意休息。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很聪明，同时又特别努力。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里空气好，同时离我家很近。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要吃得好，同时也要吃得健康。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的菜好吃，同时价格也不贵。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市很大，同时也很安静。", "target_word": "同时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "同时:连词，并且、另外，表递进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25afb08-42c1-4494-8c54-317012e5d40c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同时", "is_correct": true, "explanation": "正确。听到的是“同时”（tóng shí）。"}, {"text": "同事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是同事。"}, {"text": "同志", "is_correct": false, "explanation": "zhì 与 shí 的声母不同（zh 与 sh），声调也不同，意思是同志。"}, {"text": "通史", "is_correct": false, "explanation": "tōng（第一声）与 tóng（第二声）声调不同，shǐ（第三声）与 shí（第二声）声调也不同，意思是通史。"}, {"text": "通知", "is_correct": false, "explanation": "tōng 与 tóng 声调不同，zhī 与 shí 的声母不同（zh 与 sh）且声调不同，意思是通知。"}], "explanations": {"同时": "正确。听到的是“同时”（tóng shí）。", "同事": "shì（第四声）与 shí（第二声）声调不同，意思是同事。", "同志": "zhì 与 shí 的声母不同（zh 与 sh），声调也不同，意思是同志。", "通史": "tōng（第一声）与 tóng（第二声）声调不同，shǐ（第三声）与 shí（第二声）声调也不同，意思是通史。", "通知": "tōng 与 tóng 声调不同，zhī 与 shí 的声母不同（zh 与 sh）且声调不同，意思是通知。"}, "sentence_index": null, "correct_answer": "同时"}, "level_3": {"options": [{"text": "同时", "is_correct": true, "explanation": "正确。“同时”连接两个并列的特点，表示“并且”，与句意相符。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果关系，“很累”不能导致“有意思”。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示承接、因果，与并列的两种评价不符。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”要与前面的“不是”配套使用，这里没有“不是”。"}], "explanations": {"同时": "正确。“同时”连接两个并列的特点，表示“并且”，与句意相符。", "因此": "语义：“因此”表示因果关系，“很累”不能导致“有意思”。", "于是": "语义：“于是”表示承接、因果，与并列的两种评价不符。", "而是": "搭配：“而是”要与前面的“不是”配套使用，这里没有“不是”。"}, "sentence_index": 0, "correct_answer": "同时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想去，同时没有时间。", "explanation": "这里应该用〈但是〉。“同时”表示并列或递进，不表示转折，这里前后是对立关系。"}, {"text": "这道题很难，同时我会做。", "explanation": "这里应该用〈不过〉。“同时”不表示转折，这里前后是让步转折的关系。"}, {"text": "他吃完饭，同时去了学校。", "explanation": "这里应该用〈然后〉。“同时”表示两件事同时存在或进行，不表示先后顺序；吃完饭后去学校应说「吃完饭然后去了学校」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同时", "is_correct": true, "explanation": "正确。“同时”连接两个并列的优点，表示“并且”，与句意相符。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，“空气好”不是“离我家近”的原因。"}, {"text": "既然", "is_correct": false, "explanation": "搭配：“既然”要与后面的“就”配套使用，这里没有“就”。"}, {"text": "从而", "is_correct": false, "explanation": "语义：“从而”表示由此产生的结果，与两个并列的优点不符。"}], "explanations": {"同时": "正确。“同时”连接两个并列的优点，表示“并且”，与句意相符。", "所以": "语义：“所以”表示因果，“空气好”不是“离我家近”的原因。", "既然": "搭配：“既然”要与后面的“就”配套使用，这里没有“就”。", "从而": "语义：“从而”表示由此产生的结果，与两个并列的优点不符。"}, "sentence_index": 6, "correct_answer": "同时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他同时生病请了假。", "explanation": "这里应该用〈因为〉。“同时”表示两件事同时存在或进行，不表示因果；因病请假应说「因为生病请了假」。"}, {"text": "我们可以坐车，同时走路去。", "explanation": "这里应该用〈或者〉。“同时”表示两件事并存，不表示选择；表示二选一应说「坐车或者走路去」。"}, {"text": "天气很冷，同时我们还是出去了。", "explanation": "这里应该用〈尽管〉。“同时”表示并列或并存，不表示让步；表示“虽然天冷但仍出去”应说「天气很冷，尽管如此我们还是出去了」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间很大，同时又也很亮。", "corrected_sentence": "这个房间很大，同时也很亮。", "error_description": "错误：“又”与“也”重复表示“也”的意思，二者不能连用，多加了“又”。正确：「同时也很亮」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很有才华，同时很也谦虚。", "corrected_sentence": "她很有才华，同时也很谦虚。", "error_description": "错误：“也”位置颠倒，应放在“很”之前。正确：「同时也很谦虚」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
