INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85815, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“为了”引出做事所为的人或事，表示为某人或某事的利益而做。", "primary_collocate": null, "pronunciation": "wèi le", "ipa": "weɪ˥˩ lə", "syllable_count": 2, "sentences": [{"text": "为了孩子，妈妈放弃了去国外工作的机会。", "target_word": "为了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做这些都是为了你。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了健康，医生让爷爷每天散步。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了这次比赛，球队练习了整整一年。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了家人，爸爸每天工作到很晚。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了明年的旅行，我们已经开始存钱了。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为了考试，连周末也在图书馆学习。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了大家的安全，请不要在这里抽烟。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了一个小小的梦想，他离开了家乡。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师为了学生，常常很晚才回家。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "介词，引出做事所为的人或事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85815, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为了", "is_correct": true, "explanation": "「为了」（wèi le）表示为某件事或某个人而做，是本题的目标词。"}, {"text": "废了", "is_correct": false, "explanation": "「废了」的 fèi 与 wèi 声母不同（f 与零声母），意思是失去作用。"}, {"text": "碎了", "is_correct": false, "explanation": "「碎了」的 suì 与 wèi 声母不同（s 与零声母），意思是破碎。"}, {"text": "对了", "is_correct": false, "explanation": "「对了」的 duì 与 wèi 声母不同（d 与零声母），意思是正确。"}], "explanations": {"为了": "「为了」（wèi le）表示为某件事或某个人而做，是本题的目标词。", "废了": "「废了」的 fèi 与 wèi 声母不同（f 与零声母），意思是失去作用。", "碎了": "「碎了」的 suì 与 wèi 声母不同（s 与零声母），意思是破碎。", "对了": "「对了」的 duì 与 wèi 声母不同（d 与零声母），意思是正确。"}, "sentence_index": null, "correct_answer": "为了"}, "level_3": {"options": [{"text": "为了", "is_correct": true, "explanation": "「为了」引出做事所为的人，与句中「孩子」的关系吻合。"}, {"text": "除了", "is_correct": false, "explanation": "语义：「除了」表示排除，句意变成「除了孩子」，与放弃工作的意思不合。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：「尽管」表示让步，「放弃工作」与「孩子」之间没有让步关系，句意不通。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：「按照」后接规定、要求等依据，「孩子」不能作依据，句意不通。"}], "explanations": {"为了": "「为了」引出做事所为的人，与句中「孩子」的关系吻合。", "除了": "语义：「除了」表示排除，句意变成「除了孩子」，与放弃工作的意思不合。", "尽管": "语义：「尽管」表示让步，「放弃工作」与「孩子」之间没有让步关系，句意不通。", "按照": "搭配：「按照」后接规定、要求等依据，「孩子」不能作依据，句意不通。"}, "sentence_index": 0, "correct_answer": "为了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了生病，她请了三天假。", "explanation": "这里应该用〈因为〉。「为了」引出人有意想要得到的目的，生病不是人想要达到的，应该用「因为」说明原因。"}, {"text": "为了地震，学校停了课。", "explanation": "这里应该用〈由于〉。「为了」表示有意的目的，地震是已经发生的原因，不能用「为了」。"}, {"text": "为了天气不好，比赛推迟了。", "explanation": "这里应该用〈由于〉。「为了」表示有意的目的，天气不好是已经发生的原因，不能用「为了」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85815, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "为了", "is_correct": true, "explanation": "「为了」（wèi le）表示为某件事或某个人而做，是本题的目标词。"}, {"text": "围了", "is_correct": false, "explanation": "「围了」的 wéi 是第二声，与 wèi（第四声）声调不同，意思是包围。"}, {"text": "退了", "is_correct": false, "explanation": "「退了」的 tuì 与 wèi 声母不同（t 与零声母），意思是退还。"}, {"text": "累了", "is_correct": false, "explanation": "「累了」的 lèi 与 wèi 声母不同（l 与零声母），意思是疲倦。"}], "explanations": {"为了": "「为了」（wèi le）表示为某件事或某个人而做，是本题的目标词。", "围了": "「围了」的 wéi 是第二声，与 wèi（第四声）声调不同，意思是包围。", "退了": "「退了」的 tuì 与 wèi 声母不同（t 与零声母），意思是退还。", "累了": "「累了」的 lèi 与 wèi 声母不同（l 与零声母），意思是疲倦。"}, "sentence_index": null, "correct_answer": "为了"}, "level_3": {"options": [{"text": "为了", "is_correct": true, "explanation": "「为了」引出目的，与「考试」之间的目的关系吻合。"}, {"text": "随着", "is_correct": false, "explanation": "搭配：「随着」后接随之变化的事物，「考试」不能这样接。"}, {"text": "替", "is_correct": false, "explanation": "语义：「替」表示代替别人做事，「她替考试」讲不通。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：「按照」后接规定、要求等依据，「考试」不能作依据。"}], "explanations": {"为了": "「为了」引出目的，与「考试」之间的目的关系吻合。", "随着": "搭配：「随着」后接随之变化的事物，「考试」不能这样接。", "替": "语义：「替」表示代替别人做事，「她替考试」讲不通。", "按照": "搭配：「按照」后接规定、要求等依据，「考试」不能作依据。"}, "sentence_index": 6, "correct_answer": "为了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了明天下雨，我们就取消活动。", "explanation": "这里应该用〈如果〉。「为了」引出人想要达到的目的，天气不能作为目的，表示条件要用「如果」。"}, {"text": "我为了音乐很感兴趣。", "explanation": "这里应该用〈对〉。感兴趣的对象要用「对」引出，「为了」不能表示兴趣的对象。"}, {"text": "为了天气预报，明天会下雨。", "explanation": "这里应该用〈根据〉。「根据」引出判断的依据，「天气预报」是判断的依据而不是要达到的目的，「为了」表示有意去达到的目的，不能用在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了没迟到，他提前十分钟出门。", "corrected_sentence": "为了不迟到，他提前十分钟出门。", "error_description": "错误在「没迟到」：「为了」后面表示避免的内容要用否定副词「不」，应说「为了不迟到」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为了的赚钱，每天工作十个小时。", "corrected_sentence": "他为了赚钱，每天工作十个小时。", "error_description": "错误在「为了的」：「为了」后面不能直接加「的」。正确说法是「他为了赚钱」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
