INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85816, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示行为的目的。", "primary_collocate": null, "pronunciation": "wèi le", "ipa": "weɪ˥˩ lə", "syllable_count": 2, "sentences": [{"text": "为了赶上早班车，他六点就起床了。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了学好汉语，我每天听半小时录音。", "target_word": "为了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不迟到，她打车去了公司。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了省钱，我们自己在家做饭。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了看清黑板，小明换了前排的座位。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了让妈妈高兴，我给她买了一束花。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了准备明天的考试，他今晚不看电视。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了照顾生病的孩子，她请了三天假。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了不吵醒爸爸，大家说话很小声。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了找到那本书，我跑了好几家书店。", "target_word": "为了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "介词，引出做事的目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 4 words above tier T1 (max 2): 看清 (Zipf 3.77), 黑板 (Zipf 3.41), 小明 (Zipf 3.37), 前排 (Zipf 3.3)']::text[], '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85816, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为了", "is_correct": true, "explanation": "「为了」（wèi le）表示做事的目的，是本题的目标词。"}, {"text": "围了", "is_correct": false, "explanation": "「围了」的 wéi 是第二声，与 wèi（第四声）声调不同，意思是包围。"}, {"text": "累了", "is_correct": false, "explanation": "「累了」的 lèi 与 wèi 声母不同（l 与零声母），意思是疲倦。"}, {"text": "碎了", "is_correct": false, "explanation": "「碎了」的 suì 与 wèi 声母不同（s 与零声母），意思是破碎。"}], "explanations": {"为了": "「为了」（wèi le）表示做事的目的，是本题的目标词。", "围了": "「围了」的 wéi 是第二声，与 wèi（第四声）声调不同，意思是包围。", "累了": "「累了」的 lèi 与 wèi 声母不同（l 与零声母），意思是疲倦。", "碎了": "「碎了」的 suì 与 wèi 声母不同（s 与零声母），意思是破碎。"}, "sentence_index": null, "correct_answer": "为了"}, "level_3": {"options": [{"text": "为了", "is_correct": true, "explanation": "「为了」引出做事的目的，与「赶上早班车」的目的关系吻合。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」引出已经发生的原因，而「赶上早班车」是他要达到的目的，句意颠倒。"}, {"text": "由于", "is_correct": false, "explanation": "语义：「由于」同样表示原因，「赶上早班车」是目的而不是原因，句子说不通。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：「即使」要与「也」「还是」呼应，句中没有这种呼应，且起床也不是让步的结果。"}], "explanations": {"为了": "「为了」引出做事的目的，与「赶上早班车」的目的关系吻合。", "因为": "语义：「因为」引出已经发生的原因，而「赶上早班车」是他要达到的目的，句意颠倒。", "由于": "语义：「由于」同样表示原因，「赶上早班车」是目的而不是原因，句子说不通。", "即使": "搭配：「即使」要与「也」「还是」呼应，句中没有这种呼应，且起床也不是让步的结果。"}, "sentence_index": 0, "correct_answer": "为了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了下雨，我们没去公园。", "explanation": "这里应该用〈因为〉。「为了」引出做事的目的，下雨是已经发生、人无法选择的原因，不能当作目的。"}, {"text": "为了明天不下雨，我们就去公园。", "explanation": "这里应该用〈如果〉。「为了」只用于人有意去达到的目的，天气不能由人安排，表示条件要用「如果」。"}, {"text": "为了他去世，我们很伤心。", "explanation": "这里应该用〈由于〉。「为了」表示有意图的目的，「他去世」不是人为了达到而做的事，只能作为伤心的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85816, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "为了", "is_correct": true, "explanation": "「为了」（wèi le）表示做事的目的，是本题的目标词。"}, {"text": "对了", "is_correct": false, "explanation": "「对了」的 duì 与 wèi 声母不同（d 与零声母），意思是正确。"}, {"text": "醉了", "is_correct": false, "explanation": "「醉了」的 zuì 与 wèi 声母不同（z 与零声母），意思是喝醉。"}, {"text": "退了", "is_correct": false, "explanation": "「退了」的 tuì 与 wèi 声母不同（t 与零声母），意思是退还。"}, {"text": "碎了", "is_correct": false, "explanation": "「碎了」的 suì 与 wèi 声母不同（s 与零声母），意思是破碎。"}], "explanations": {"为了": "「为了」（wèi le）表示做事的目的，是本题的目标词。", "对了": "「对了」的 duì 与 wèi 声母不同（d 与零声母），意思是正确。", "醉了": "「醉了」的 zuì 与 wèi 声母不同（z 与零声母），意思是喝醉。", "退了": "「退了」的 tuì 与 wèi 声母不同（t 与零声母），意思是退还。", "碎了": "「碎了」的 suì 与 wèi 声母不同（s 与零声母），意思是破碎。"}, "sentence_index": null, "correct_answer": "为了"}, "level_3": {"options": [{"text": "为了", "is_correct": true, "explanation": "「为了」引出目的，与「准备明天的考试」的目的关系吻合。"}, {"text": "自从", "is_correct": false, "explanation": "语义：「自从」表示从过去某时开始，而「明天的考试」是将来的事，时间方向相反。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：「按照」后接规定、要求等依据，「准备考试」不能作依据，句意不通。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：「尽管」表示让步，「不看电视」不是与准备考试相对的让步，句意不通。"}], "explanations": {"为了": "「为了」引出目的，与「准备明天的考试」的目的关系吻合。", "自从": "语义：「自从」表示从过去某时开始，而「明天的考试」是将来的事，时间方向相反。", "按照": "搭配：「按照」后接规定、要求等依据，「准备考试」不能作依据，句意不通。", "尽管": "语义：「尽管」表示让步，「不看电视」不是与准备考试相对的让步，句意不通。"}, "sentence_index": 6, "correct_answer": "为了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了天气预报，明天会下雨。", "explanation": "这里应该用〈根据〉。「根据」引出判断的依据，「天气预报」是判断的依据而不是要达到的目的，「为了」表示有意去达到的目的，不能用在这里。"}, {"text": "我为了音乐很感兴趣。", "explanation": "这里应该用〈对〉。感兴趣的对象要用「对」引出，「为了」表示目的，不能表示兴趣的对象。"}, {"text": "为了天气好，我们去爬山。", "explanation": "这里应该用〈趁〉。「趁」表示利用某个时机，「为了」要求是有意去达到的目的，天气好不能作为要去达到的目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了赶上了会议，他提前出发了。", "corrected_sentence": "为了赶上会议，他提前出发了。", "error_description": "错误在「赶上了」：「为了」引出尚未实现的目的，目的部分的动词后不能加「了」。正确说法是「为了赶上会议」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了没耽误会议，他提前出发了。", "corrected_sentence": "为了不耽误会议，他提前出发了。", "error_description": "错误在「没耽误」：表示避免某种结果的目的要用否定副词「不」，「没」表示已经发生的否定，不能用在「为了」引出的目的中。正确说法是「为了不耽误会议」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85817, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离开", "is_correct": true, "explanation": "正确：“离开”与“待”（留在某处不走开）意思相反，是反义词。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”指吃东西，与“待”的留在某处没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指书写，与“待”的留在某处无关，不是反义词。"}, {"text": "读", "is_correct": false, "explanation": "“读”指看书、朗读，与“待”的停留没有反义关系。"}], "correct_answer": "离开", "explanations": {"离开": "正确：“离开”与“待”（留在某处不走开）意思相反，是反义词。", "吃": "“吃”指吃东西，与“待”的留在某处没有反义关系。", "写": "“写”指书写，与“待”的留在某处无关，不是反义词。", "读": "“读”指看书、朗读，与“待”的停留没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85817, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离开", "is_correct": true, "explanation": "正确：“离开”与“待”（留在某处不走开）意思相反，是反义词。"}, {"text": "洗", "is_correct": false, "explanation": "“洗”指清洁，与“待”的留在某处没有反义关系。"}, {"text": "画", "is_correct": false, "explanation": "“画”指绘画或描绘，与“待”无反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "“笑”指表情或发出笑声，与“待”不构成反义关系。"}], "correct_answer": "离开", "explanations": {"离开": "正确：“离开”与“待”（留在某处不走开）意思相反，是反义词。", "洗": "“洗”指清洁，与“待”的留在某处没有反义关系。", "画": "“画”指绘画或描绘，与“待”无反义关系。", "笑": "“笑”指表情或发出笑声，与“待”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85817, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "待是留在一个地方，不走开。", "primary_collocate": null, "pronunciation": "dāi", "ipa": "tai˥", "syllable_count": 1, "sentences": [{"text": "周末我不出门，就在家里待着。", "target_word": "待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太冷，你就待在屋里吧。", "target_word": "待", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一整天都待在房间里，哪儿也没去。", "target_word": "待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别走，在这儿待一会儿。", "target_word": "待", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子病了，只能待在家里不去学校。", "target_word": "待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗一直待在门口，等主人回来。", "target_word": "待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想待在这里，我们出去走走吧。", "target_word": "待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，猫总是待在窗边不动。", "target_word": "待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在图书馆里待着看了一下午书。", "target_word": "待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你病还没好，今天就待在床上休息吧。", "target_word": "待", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "待着", "label": "体标"}, {"form": "待了", "label": "体标"}, {"form": "待过", "label": "体标"}], "register": "口语", "sense_fingerprint": "待：留在某处不离开，常说待在家里、待着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85817, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "待", "is_correct": true, "explanation": "正确答案：待（dāi），指留在某处不走开。"}, {"text": "带", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，“带”意思是携带、带领。"}, {"text": "代", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，“代”意思是代表、替代。"}, {"text": "台", "is_correct": false, "explanation": "tái（第二声）与 dāi（第一声）声调不同，“台”意思是台子、平台。"}, {"text": "胎", "is_correct": false, "explanation": "tāi 与 dāi 声母不同（t 与 d），“胎”意思是胎儿、轮胎。"}], "explanations": {"待": "正确答案：待（dāi），指留在某处不走开。", "带": "dài（第四声）与 dāi（第一声）声调不同，“带”意思是携带、带领。", "代": "dài（第四声）与 dāi（第一声）声调不同，“代”意思是代表、替代。", "台": "tái（第二声）与 dāi（第一声）声调不同，“台”意思是台子、平台。", "胎": "tāi 与 dāi 声母不同（t 与 d），“胎”意思是胎儿、轮胎。"}, "sentence_index": null, "correct_answer": "待"}, "level_3": {"options": [{"text": "待", "is_correct": true, "explanation": "正确：“待着”表示留在家里不出门，与“不出门”相符。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：“旅行”指到外地去，与“不出门”和“在家里”相矛盾。"}, {"text": "驻", "is_correct": false, "explanation": "语域：“驻”多指军队或机构驻守，口语中不用于在家里待着。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”指到外地办事，不能说“在家里出差着”。"}], "explanations": {"待": "正确：“待着”表示留在家里不出门，与“不出门”相符。", "旅行": "语义：“旅行”指到外地去，与“不出门”和“在家里”相矛盾。", "驻": "语域：“驻”多指军队或机构驻守，口语中不用于在家里待着。", "出差": "搭配：“出差”指到外地办事，不能说“在家里出差着”。"}, "sentence_index": 0, "correct_answer": "待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在车站待你半个小时了。", "explanation": "这里应该用〈等〉。“待”不能带人作宾语表示等人，等人要说“等”。"}, {"text": "这种天气待人很好，大家都喜欢出门。", "explanation": "这里的“待”是“对待”的意思，只用于人与人之间的态度，不能用来说天气，不表示留在某处。"}, {"text": "他待着走出了房间，又回来拿东西。", "explanation": "“待着”表示留在某处不动，不能同时“走出了房间”，二者矛盾。应去掉“待着”，说“他走出了房间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85817, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "待", "is_correct": true, "explanation": "正确答案：待（dāi），指留在某处不走开。"}, {"text": "戴", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，“戴”意思是戴帽子、佩戴。"}, {"text": "袋", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，“袋”意思是口袋、袋子。"}, {"text": "抬", "is_correct": false, "explanation": "tái（第二声）与 dāi（第一声）声调不同，“抬”意思是用手或肩膀托起。"}, {"text": "贷", "is_correct": false, "explanation": "dài（第四声）与 dāi（第一声）声调不同，“贷”意思是借钱、借贷。"}], "explanations": {"待": "正确答案：待（dāi），指留在某处不走开。", "戴": "dài（第四声）与 dāi（第一声）声调不同，“戴”意思是戴帽子、佩戴。", "袋": "dài（第四声）与 dāi（第一声）声调不同，“袋”意思是口袋、袋子。", "抬": "tái（第二声）与 dāi（第一声）声调不同，“抬”意思是用手或肩膀托起。", "贷": "dài（第四声）与 dāi（第一声）声调不同，“贷”意思是借钱、借贷。"}, "sentence_index": null, "correct_answer": "待"}, "level_3": {"options": [{"text": "待", "is_correct": true, "explanation": "正确：“待在这里”表示留在这儿不走，与后面的“出去走走”形成对照。"}, {"text": "长", "is_correct": false, "explanation": "语义：“长”指植物生长，人不能“长在这里”。"}, {"text": "挂", "is_correct": false, "explanation": "配价：“挂”需要物品作宾语，人不能“挂在这里”。"}, {"text": "摆", "is_correct": false, "explanation": "配价：“摆”需要物品作宾语，“我不想摆在这里”不成立。"}], "explanations": {"待": "正确：“待在这里”表示留在这儿不走，与后面的“出去走走”形成对照。", "长": "语义：“长”指植物生长，人不能“长在这里”。", "挂": "配价：“挂”需要物品作宾语，人不能“挂在这里”。", "摆": "配价：“摆”需要物品作宾语，“我不想摆在这里”不成立。"}, "sentence_index": 6, "correct_answer": "待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车待修，你先别开。", "explanation": "这里的“待”表示“等着被修理”，常说“待修”，不表示留在某处。"}, {"text": "他待饭很认真，每顿都吃得很慢。", "explanation": "这里的“待”是“对待”的意思，只用于人或事，不能用来说“饭”，不表示留在某处。"}, {"text": "他待着走进邮局，把东西寄出去了。", "explanation": "这里“待着”表示停留，与“走进”的动作矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在家里待着了一天。", "corrected_sentence": "我在家里待了一天。", "error_description": "错误：“待着”和“了”不能同时用。“待着”表示持续的状态，“待了”表示已经完成的停留。正确说法是“我在家里待了一天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把屋里待了一上午。", "corrected_sentence": "她在屋里待了一上午。", "error_description": "错误：“待”是不及物动词，不能用“把”字句。表示停留在某处要说“在屋里待”，不能说“把屋里待”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85819, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85819, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85819, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“所以”是说前面的事是原因，后面是结果。", "primary_collocate": null, "pronunciation": "suǒ yǐ", "ipa": "suɔ˨˩ i˨˩", "syllable_count": 2, "sentences": [{"text": "路很滑，所以你要慢点走。", "target_word": "所以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我饿了，所以先吃点东西。", "target_word": "所以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没睡好，所以今天没精神。", "target_word": "所以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里很安静，所以我常来看书。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是周末，所以路上车很少。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不认识路，所以问了警察。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会说中文，所以当了翻译。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为他病了，所以没来开会。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，所以我没打电话。", "target_word": "所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步，所以身体很好。", "target_word": "所以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连接原因和结果，后面说结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df888c7e-00bf-4d04-9d58-c326ae2207d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85819, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所以", "is_correct": true, "explanation": "正确：“路很滑”是原因，“你要慢点走”是由此得出的结论。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”表让步，要与“但是”或“还是”配合；这里前后是因果，不能用。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，此处后句是由路滑推出的结论，“因为你要慢点走”颠倒了因果。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“如果”引出假设，后句缺少结果，与“路很滑”这一事实不相配。"}], "explanations": {"所以": "正确：“路很滑”是原因，“你要慢点走”是由此得出的结论。", "虽然": "搭配：“虽然”表让步，要与“但是”或“还是”配合；这里前后是因果，不能用。", "因为": "语义：“因为”引出原因，此处后句是由路滑推出的结论，“因为你要慢点走”颠倒了因果。", "如果": "搭配：“如果”引出假设，后句缺少结果，与“路很滑”这一事实不相配。"}, "sentence_index": 0, "correct_answer": "所以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很喜欢运动，所以身体不好。", "explanation": "这里应该用〈但是〉。前后是转折（喜欢运动却身体不好），“所以”只能引出因果结果。"}, {"text": "他去了超市，所以又去了银行。", "explanation": "这里应该用〈然后〉。这是先后顺序，前后不是因果，“所以”把两件事说成了因果。"}, {"text": "这家店很便宜，所以很干净。", "explanation": "这里应该用〈而且〉。这是并列补充（便宜，也干净），前后不是因果，“所以”用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所以", "is_correct": true, "explanation": "正确：“她会说中文”是原因，“当了翻译”是由此而来的结果。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，不表示因果，“她会说中文，或者当了翻译”不成立。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”要与“但是”或“还是”配合表让步，不能接在因果前句之后。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折，前后没有转折关系，这里说不通。"}], "explanations": {"所以": "正确：“她会说中文”是原因，“当了翻译”是由此而来的结果。", "或者": "语义：“或者”表示选择，不表示因果，“她会说中文，或者当了翻译”不成立。", "尽管": "搭配：“尽管”要与“但是”或“还是”配合表让步，不能接在因果前句之后。", "不过": "语义：“不过”表示转折，前后没有转折关系，这里说不通。"}, "sentence_index": 6, "correct_answer": "所以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找了一个小时，所以没找到。", "explanation": "这里应该用〈却〉。“却”引出出乎意料的结局；“所以”把“没找到”说成“找了一个小时”的结果，可找了很久不会导致找不到，说法不通。"}, {"text": "他不喜欢音乐，所以经常听歌。", "explanation": "这里应该用〈却〉。前后是转折（不喜欢音乐，却经常听歌），“所以”把“经常听歌”说成“不喜欢音乐”的结果，说不通。"}, {"text": "我一边做饭，所以听广播。", "explanation": "这里应该用〈同时〉。两个动作同时进行，是并列关系，“所以”表示因果，用在这里说法错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路很滑，所以因为我走得很慢。", "corrected_sentence": "这条路很滑，所以我走得很慢。", "error_description": "错误：“所以”之后多加了“因为”。“因为”只引出原因，与表示结果的“所以”不能叠用，结果分句只用“所以”。错误形式为“所以因为我走得很慢”，正确形式为“这条路很滑，所以我走得很慢。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气很冷，所以所以我多穿了一件衣服。", "corrected_sentence": "天气很冷，所以我多穿了一件衣服。", "error_description": "错误：“所以”重复了一次。“所以”在结果分句中只出现一次，多写一个“所以”不通顺。错误形式为“天气很冷，所以所以我多穿了一件衣服”，正确形式为“天气很冷，所以我多穿了一件衣服。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
