INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85821, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "彻底就是从头到尾，一点都不剩。", "primary_collocate": null, "pronunciation": "chè dǐ", "ipa": "ʈʂʰɤ˥˩ ti˨˩˦", "syllable_count": 2, "sentences": [{"text": "他把房间彻底打扫了一遍。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧东西要彻底扔掉。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把昨天的事彻底忘了。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火彻底烧毁了那间房子。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他彻底输了这场比赛。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机把衣服洗得很彻底。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把桌子彻底擦干净。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她彻底放弃了这个想法。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把教室彻底检查了一遍。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些垃圾要处理得彻底一点。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不彻底", "label": "复合词"}, {"form": "徹底", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做得完全，从头到尾一点不剩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87aa3fbb-5473-40d6-85f3-a36aa4409ac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彻底", "is_correct": true, "explanation": "彻底表示从头到尾、完全，修饰「打扫」，「把房间彻底打扫了一遍」意思通顺，正确。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：「干净」作补语说「打扫干净」，不能直接修饰动词「打扫」。"}, {"text": "崭新", "is_correct": false, "explanation": "语义：「崭新」指全新的状态，不能修饰「打扫」这个动作。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容外形，不能修饰动作「打扫」。"}], "explanations": {"彻底": "彻底表示从头到尾、完全，修饰「打扫」，「把房间彻底打扫了一遍」意思通顺，正确。", "干净": "搭配：「干净」作补语说「打扫干净」，不能直接修饰动词「打扫」。", "崭新": "语义：「崭新」指全新的状态，不能修饰「打扫」这个动作。", "高大": "体貌：「高大」形容外形，不能修饰动作「打扫」。"}, "sentence_index": 0, "correct_answer": "彻底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彻底的钱都花光了。", "explanation": "这里应该用〈全部〉。「彻底」修饰动作，表示做到底，不用来修饰「钱」这类表示数量的名词。"}, {"text": "这次经历让我印象很彻底。", "explanation": "这里应该用〈深刻〉。「彻底」指从头到尾、不剩，不用来形容印象的深浅。"}, {"text": "这把椅子很彻底。", "explanation": "这里应该用〈舒服〉。「彻底」指从头到尾、不剩，不用来形容椅子的舒适程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彻底", "is_correct": true, "explanation": "彻底表示做到底、完全，修饰「擦干净」，「请你把桌子彻底擦干净」意思通顺，正确。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：「圆」描写形状，不能修饰「擦」这个动作。"}, {"text": "冷", "is_correct": false, "explanation": "语义：「冷」指温度，不能修饰「擦」这个动作，句意不通。"}, {"text": "红", "is_correct": false, "explanation": "语义：「红」指颜色，不能修饰「擦」这个动作，句意不通。"}], "explanations": {"彻底": "彻底表示做到底、完全，修饰「擦干净」，「请你把桌子彻底擦干净」意思通顺，正确。", "圆": "体貌：「圆」描写形状，不能修饰「擦」这个动作。", "冷": "语义：「冷」指温度，不能修饰「擦」这个动作，句意不通。", "红": "语义：「红」指颜色，不能修饰「擦」这个动作，句意不通。"}, "sentence_index": 6, "correct_answer": "彻底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你彻底想说什么？", "explanation": "这里应该用〈到底〉。「彻底」指从头到尾、不剩，不用来表示追问的语气。"}, {"text": "这首歌很彻底。", "explanation": "这里应该用〈好听〉。「彻底」指从头到尾、不剩，不用来形容歌曲的动听程度。"}, {"text": "这顿饭很彻底。", "explanation": "这里应该用〈便宜〉。「彻底」指从头到尾、不剩，不用来说明价格的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很彻底改掉了这个坏习惯。", "corrected_sentence": "他很彻底地改掉了这个坏习惯。", "error_description": "错误：「很彻底改掉」，「很彻底」修饰动词时后面要加「地」。正确：「很彻底地改掉」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事他彻底了忘。", "corrected_sentence": "这件事他彻底忘了。", "error_description": "错误：「了忘」，「了」放错了位置。正确：「忘了」，「了」应放在动词「忘」之后表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
