INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85822, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "透彻；一直到底，没有遗漏或保留。", "primary_collocate": null, "pronunciation": "chè dǐ", "ipa": "ʈʂʰɤ˥˩ ti˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个问题要彻底解决。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察对这件事做了彻底的调查。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对这个问题做了彻底的讲解，我都听懂了。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法有了彻底的改变。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一次彻底的改革。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要把这件事想得彻底一点。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事的解释不够彻底，我还是不懂。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司彻底改变了管理方法。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次检查很彻底，没有留下问题。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个道理理解得很彻底。", "target_word": "彻底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不彻底", "label": "复合词"}, {"form": "徹底", "label": "繁体"}], "register": "中性", "sense_fingerprint": "透彻、深入到底，没有遗漏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87aa3fbb-5473-40d6-85f3-a36aa4409ac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彻底", "is_correct": true, "explanation": "彻底：一直到底、没有遗漏，与“要……解决”的要求相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“要……解决”要求全面解决相矛盾。"}, {"text": "乱", "is_correct": false, "explanation": "搭配：“乱”不能修饰“解决”这种有明确目标的动作。"}, {"text": "匆忙", "is_correct": false, "explanation": "语义：“匆忙”表示急促、赶时间，与“要……解决”强调一直到底、不留遗漏的意思不符。"}], "explanations": {"彻底": "彻底：一直到底、没有遗漏，与“要……解决”的要求相符。", "偶尔": "语义：“偶尔”表示不经常，与“要……解决”要求全面解决相矛盾。", "乱": "搭配：“乱”不能修饰“解决”这种有明确目标的动作。", "匆忙": "语义：“匆忙”表示急促、赶时间，与“要……解决”强调一直到底、不留遗漏的意思不符。"}, "sentence_index": 0, "correct_answer": "彻底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块玻璃很彻底。", "explanation": "这里应该用〈通透〉。“彻底”表示做到底、没有遗漏，不用来形容物体的透明程度，玻璃清澈透亮应说〈通透〉。"}, {"text": "这盏灯很彻底。", "explanation": "这里应该用〈亮〉。“彻底”不用来形容光线的明暗，灯光明亮应说〈亮〉。"}, {"text": "西瓜很彻底。", "explanation": "这里应该用〈甜〉。“彻底”不用来形容味道，西瓜味道好应说〈甜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彻底", "is_correct": true, "explanation": "彻底：透彻、没有保留，与“不够……，我还是不懂”的语境相符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能用来形容解释是否透彻，句意不通。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”指声音大而清楚，与解释的深入程度无关。"}, {"text": "柔软", "is_correct": false, "explanation": "体貌：“柔软”描写质地或触感，不能用来说明解释是否透彻。"}], "explanations": {"彻底": "彻底：透彻、没有保留，与“不够……，我还是不懂”的语境相符。", "甜": "语义：“甜”指味道，不能用来形容解释是否透彻，句意不通。", "响亮": "语义：“响亮”指声音大而清楚，与解释的深入程度无关。", "柔软": "体貌：“柔软”描写质地或触感，不能用来说明解释是否透彻。"}, "sentence_index": 6, "correct_answer": "彻底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑得很彻底，一下子就到了终点。", "explanation": "这里应该用〈快〉。“彻底”说的是做到底、没有遗漏，不用来形容跑步的速度。"}, {"text": "这只猫的个子很彻底，比我还高。", "explanation": "这里应该用〈高〉。“彻底”不用来描述身高等外形的程度。"}, {"text": "这间屋子很彻底，住五个人没问题。", "explanation": "这里应该用〈大〉。“彻底”不用来形容房间的面积大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你要把这个问题想很彻底。", "corrected_sentence": "你要把这个问题想得很彻底。", "error_description": "错误：想很彻底；正确：想得很彻底。“彻底”作程度补语，动词和补语之间要用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这份报告检查很彻底。", "corrected_sentence": "他对这份报告检查得很彻底。", "error_description": "错误：检查很彻底；正确：检查得很彻底。“彻底”作程度补语，动词和补语之间要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
