INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85823, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想到是脑子里忽然出现了一个念头。", "primary_collocate": null, "pronunciation": "xiǎng dào", "ipa": "ɕjɑŋ˨˩ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我忽然想到一个好办法。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着窗外，突然想到了小时候的家。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗澡的时候，我想到了明天的会。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这首歌，我想到了老朋友。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚想到一个好主意，就告诉了你。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看见雨伞，才想到今天要下雨。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走到门口，我想到钥匙没带。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么会想到这个问题？", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一下子想到了答案。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时我忽然想到，今天是妈妈的生日。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想到了", "label": "体标"}, {"form": "想到过", "label": "体标"}], "register": "口语", "sense_fingerprint": "脑子里忽然冒出一个念头、主意或回忆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想到", "is_correct": true, "explanation": "正确答案。「忽然」之后出现的是一个念头，「想到」表示脑中忽然冒出主意。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：「吃掉」的宾语须是食物，「办法」不能吃。"}, {"text": "忘掉", "is_correct": false, "explanation": "语义：「忘掉」表示从记忆中消失，与「忽然冒出一个好办法」的意思相反。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：「咬」的宾语须是可以咬的东西，「办法」不能咬。"}], "explanations": {"想到": "正确答案。「忽然」之后出现的是一个念头，「想到」表示脑中忽然冒出主意。", "吃掉": "搭配：「吃掉」的宾语须是食物，「办法」不能吃。", "忘掉": "语义：「忘掉」表示从记忆中消失，与「忽然冒出一个好办法」的意思相反。", "咬": "搭配：「咬」的宾语须是可以咬的东西，「办法」不能咬。"}, "sentence_index": 0, "correct_answer": "想到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在树林里想到了一只兔子，立刻举起了相机。", "explanation": "这里应该用〈看到〉。想到表示心里冒出念头，不能表示用眼睛看见；举起相机说明兔子就在眼前，要用看到。"}, {"text": "我翻遍了箱子，伸手一摸，终于想到了那三本旧书。", "explanation": "这里应该用〈找到〉。想到表示心里冒出念头，不能表示在箱子里摸出书；翻找、伸手摸的动作要用找到。"}, {"text": "他从包里想到了一支笔。", "explanation": "这里应该用〈拿出〉。想到是心里的活动，不能表示从包里取出东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想到", "is_correct": true, "explanation": "正确答案。走到门口时忽然想起钥匙没带，「想到」表示突然想起。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：「放弃」指停止做某事，不能接「钥匙没带」这样的一个念头。"}, {"text": "修理", "is_correct": false, "explanation": "配价：「修理」的宾语须是需要修的物品，不能接一个小句。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：「摸」的宾语须是可以触摸的具体东西，「钥匙没带」不能被摸。"}], "explanations": {"想到": "正确答案。走到门口时忽然想起钥匙没带，「想到」表示突然想起。", "放弃": "语义：「放弃」指停止做某事，不能接「钥匙没带」这样的一个念头。", "修理": "配价：「修理」的宾语须是需要修的物品，不能接一个小句。", "摸": "搭配：「摸」的宾语须是可以触摸的具体东西，「钥匙没带」不能被摸。"}, "sentence_index": 6, "correct_answer": "想到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路上想到了王老师，两人还一起吃了饭。", "explanation": "这里应该用〈遇到〉。想到表示心里想起，不能表示在路上与人碰面；后文两人一起吃饭说明已经见面，要用遇到。"}, {"text": "他在超市想到了一瓶酱油，马上付了钱。", "explanation": "这里应该用〈买到〉。想到表示心里冒出念头，不能表示买下东西；付钱说明是买到，要用买到。"}, {"text": "他在河边想到了一条大鱼，用力拉了上来。", "explanation": "这里应该用〈钓到〉。想到表示心里冒出念头，不能表示把鱼拉上来；拉上来的动作说明是钓到，要用钓到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他突然想到了那只事。", "corrected_sentence": "他突然想到了那件事。", "error_description": "错误：「那只事」。正确：「那件事」。「事」应用量词「件」，「只」用于动物等，不能用来计量「事」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在厨房里想到着一个好办法。", "corrected_sentence": "妈妈在厨房里想到了一个好办法。", "error_description": "「想到着」错误，正确是「想到了」。「着」表示持续状态，与表示忽然出现的「想到」不搭配，完成的念头要用「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
