INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85824, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里考虑到；料到。", "primary_collocate": null, "pronunciation": "xiǎng dào", "ipa": "ɕjɑŋ˨˩ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "做事以前，要想到后果。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没想到你会来。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁能想到今天会下大雪？", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做决定时，要想到家人的感受。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想到了所有的问题，所以很放心。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我真没想到，这么难的题他做对了。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想到过这样的结果吗？", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很细心，什么都想到了。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试这么难，我早就想到了。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时要想到路上的安全。", "target_word": "想到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想到了", "label": "体标"}, {"form": "想到过", "label": "体标"}, {"form": "没想到", "label": "否定式"}], "register": "口语", "sense_fingerprint": "事先考虑到或预料到某件事、某种结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想到", "is_correct": true, "explanation": "正确答案。「做事以前，要……后果」表示事先考虑，与「想到」相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：「做事以前忘记后果」与句中的劝诫意思相反。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：「吃掉」的宾语须是食物，「后果」不能吃。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：「摸」的宾语须是具体的东西，「后果」不能被摸。"}], "explanations": {"想到": "正确答案。「做事以前，要……后果」表示事先考虑，与「想到」相符。", "忘记": "语义：「做事以前忘记后果」与句中的劝诫意思相反。", "吃掉": "搭配：「吃掉」的宾语须是食物，「后果」不能吃。", "摸": "搭配：「摸」的宾语须是具体的东西，「后果」不能被摸。"}, "sentence_index": 0, "correct_answer": "想到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力一推，就想到了那扇门。", "explanation": "这里应该用〈推开〉。想到表示心里考虑或想起，不能表示用力推动门；推门要用推开。"}, {"text": "我在门口想到了一个老朋友，我们高兴地握了手。", "explanation": "这里应该用〈遇到〉。想到表示心里想起，不能表示在门口与人相遇；后文握手说明两人已经见面，要用遇到。"}, {"text": "他在树下想到了一只猫，伸手就把它抱了起来。", "explanation": "这里应该用〈看到〉。想到表示心里想起，不能表示亲眼看见；伸手抱起说明猫就在眼前，要用看到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想到", "is_correct": true, "explanation": "正确答案。「你……过这样的结果吗」问的是有没有想过，与「想到」相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语须是食物，「结果」不能吃。"}, {"text": "买", "is_correct": false, "explanation": "搭配：「买」的宾语须是可以购买的商品，「结果」不能买。"}, {"text": "吵", "is_correct": false, "explanation": "配价：「吵」是不及物动词，不能带「结果」作宾语。"}], "explanations": {"想到": "正确答案。「你……过这样的结果吗」问的是有没有想过，与「想到」相符。", "吃": "搭配：「吃」的宾语须是食物，「结果」不能吃。", "买": "搭配：「买」的宾语须是可以购买的商品，「结果」不能买。", "吵": "配价：「吵」是不及物动词，不能带「结果」作宾语。"}, "sentence_index": 6, "correct_answer": "想到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他挤进车厢，用力一推，想到了最后一个座位。", "explanation": "这里应该用〈抢到〉。想到表示心里考虑或想起，不能表示争抢到座位；挤进车厢、用力一推是抢的动作，要用抢到。"}, {"text": "我伸手在箱子里一摸，想到了一把旧伞。", "explanation": "这里应该用〈找到〉。想到表示心里想起，不能表示在箱子里找出东西；伸手一摸是找的动作，要用找到。"}, {"text": "他靠努力想到了好成绩。", "explanation": "这里应该用〈取得〉。想到不能表示靠努力得到成绩，成绩要用取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没想到了他会来。", "corrected_sentence": "我没想到他会来。", "error_description": "「没想到了」错误，正确是「没想到」。「没」表示否定，已经被否定的动作不能再加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没想到的他会放弃。", "corrected_sentence": "我从来没想到他会放弃。", "error_description": "错误：「没想到的他会放弃」。正确：「没想到他会放弃」。「没想到的」是定语结构，后面须接中心名词（如「没想到的事」），不能直接接主谓小句；「想到」后接「的」本身没有问题（如「想到的办法」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
