INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85825, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "“所有”是说全部，一个也不少。", "primary_collocate": null, "pronunciation": "suǒ yǒu", "ipa": "swɔ˨˩˦ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "所有的同学都参加了今天的会。", "target_word": "所有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把所有的钱都给了妈妈。", "target_word": "所有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有人都在等老师来。", "target_word": "所有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店里所有的东西都很便宜。", "target_word": "所有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他回答对了所有的问题。", "target_word": "所有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经看完所有的书了。", "target_word": "所有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里所有的花都是她种的。", "target_word": "所有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把所有的作业交给老师。", "target_word": "所有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所有的学生都在认真写字。", "target_word": "所有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，所有的车都开得很慢。", "target_word": "所有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "所有的", "label": "复合"}], "register": "中性", "sense_fingerprint": "所有:全部的，一个不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25afb08-42c1-4494-8c54-317012e5d40c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所有", "is_correct": true, "explanation": "“所有”表示全部、一个不少，与“同学都参加了”相符，是唯一能填入的词。"}, {"text": "个别", "is_correct": false, "explanation": "语义：“个别”指很少的一部分，与后面的“都参加了”矛盾。"}, {"text": "少数", "is_correct": false, "explanation": "语义：“少数”指数量很少，与“都参加了”矛盾，不能说“少数的同学都参加了”。"}, {"text": "零星", "is_correct": false, "explanation": "搭配：“零星”多形容散落、少量的事物，不用来修饰“同学”。"}], "explanations": {"所有": "“所有”表示全部、一个不少，与“同学都参加了”相符，是唯一能填入的词。", "个别": "语义：“个别”指很少的一部分，与后面的“都参加了”矛盾。", "少数": "语义：“少数”指数量很少，与“都参加了”矛盾，不能说“少数的同学都参加了”。", "零星": "搭配：“零星”多形容散落、少量的事物，不用来修饰“同学”。"}, "sentence_index": 0, "correct_answer": "所有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天所有下午都在看书。", "explanation": "这里应该用〈整个〉。“所有”指多个对象的全部，“整个”指一个完整的整体；“今天”只有一个下午，要说“整个下午”。"}, {"text": "这次比赛的所有都很顺利。", "explanation": "这里应该用〈一切〉。“一切”可以单独作主语，指全部事情；“所有”后面要接名词，不能单独作主语。"}, {"text": "我所有的钱一点也没花，花光了。", "explanation": "这里不能这样用“所有”。“所有的钱花光了”表示全部用完，与“一点也没花”矛盾；应说「我所有的钱都花光了」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所有", "is_correct": true, "explanation": "“所有”表示全部，与“这里的花都是她种的”相符。"}, {"text": "唯一", "is_correct": false, "explanation": "语义：“唯一”指只有一个，与“花”的复数和“都”矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”多形容负担、心情或重量，不用来修饰“花”。"}, {"text": "野生", "is_correct": false, "explanation": "语义：“野生”指自然生长的，与“她种的”矛盾。"}], "explanations": {"所有": "“所有”表示全部，与“这里的花都是她种的”相符。", "唯一": "语义：“唯一”指只有一个，与“花”的复数和“都”矛盾。", "沉重": "搭配：“沉重”多形容负担、心情或重量，不用来修饰“花”。", "野生": "语义：“野生”指自然生长的，与“她种的”矛盾。"}, "sentence_index": 6, "correct_answer": "所有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把所有的一个苹果都吃光了。", "explanation": "这里应该用〈整〉。“所有”指多个对象的全部，不能修饰“一个苹果”这样的单个对象；指一个苹果的全部要说“整个苹果”。"}, {"text": "他买了所有的两本书。", "explanation": "这里应该说“两本书都买了”。“所有”指全部，不能与“两本”这样确定的数量连用。"}, {"text": "我们班所有的一个同学都没来。", "explanation": "这里应该说“我们班同学都没来”或“一个同学都没来”。“所有”指全部，不能与“一个”这样的单数连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛所有都很努力。", "corrected_sentence": "这次比赛所有选手都很努力。", "error_description": "错误：“所有”是形容词，后面必须接名词，“所有都很努力”漏掉了名词。正确：“所有选手都很努力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "所有本书我都读了。", "corrected_sentence": "所有的书我都读了。", "error_description": "错误：“所有”后面不能直接加量词“本”，要说“所有的书”（或用“每本书”）。正确：「所有的书我都读了。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
