INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85828, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上级对下级的请求、意见或计划表示同意。", "primary_collocate": null, "pronunciation": "pī zhǔn", "ipa": "pʰi˥ ʈ͡ʂu̯n˨˩", "syllable_count": 2, "sentences": [{"text": "经理批准了我的休假申请。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司批准了这个新计划。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府批准在这里建一所学校。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级还没有批准我们的请求。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导批准了他的辞职。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案上级已经批准过了。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府批准了医院的建设计划。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长批准了图书馆延长开放时间的申请。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理批准我们下个月出差。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部门主管批准了这次培训计划。", "target_word": "批准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批准了", "label": "体标"}, {"form": "批准过", "label": "体标"}], "register": "正式", "sense_fingerprint": "上级同意下级的请求或计划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a956c441-19d3-4000-954b-c5a96b39ceec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批准", "is_correct": true, "explanation": "“批准”表示上级同意下级的申请，与“经理……我的休假申请”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能与“申请”搭配，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与“申请”毫无关系。"}, {"text": "祝贺", "is_correct": false, "explanation": "配价：“祝贺”的宾语应是事件或人，不能直接接“休假申请”这类文件。"}], "explanations": {"批准": "“批准”表示上级同意下级的申请，与“经理……我的休假申请”相合。", "吃": "语义：“吃”不能与“申请”搭配，句子说不通。", "唱": "语义：“唱”指发出歌声，与“申请”毫无关系。", "祝贺": "配价：“祝贺”的宾语应是事件或人，不能直接接“休假申请”这类文件。"}, "sentence_index": 0, "correct_answer": "批准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我批准他的看法。", "explanation": "这里应该用〈同意〉。同意可用于平等的人之间表示赞成，批准指有权的上级许可下级的请求或计划，不用于他人的看法。"}, {"text": "同事批准了我的请假。", "explanation": "这里应该用〈同意〉。同意可用于平等的人之间表示赞成；批准指有权的上级对下级的请求表示同意，同事之间不能用批准。"}, {"text": "朋友批准了我的建议。", "explanation": "这里应该用〈赞同〉。赞同指赞成别人的意见；批准指有权的上级对下级的请求或计划表示同意，朋友之间不能说批准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批准", "is_correct": true, "explanation": "“批准”表示政府同意计划，与“政府……医院的建设计划”相合。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是身体动作，不能用于计划。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指擦拭，不能用来对计划做事。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”是不及物动词，不能带“建设计划”作宾语。"}], "explanations": {"批准": "“批准”表示政府同意计划，与“政府……医院的建设计划”相合。", "跳": "语义：“跳”是身体动作，不能用于计划。", "擦": "语义：“擦”指擦拭，不能用来对计划做事。", "游": "配价：“游”是不及物动词，不能带“建设计划”作宾语。"}, "sentence_index": 6, "correct_answer": "批准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小李批准了经理的辞职。", "explanation": "这里应该用〈接受〉。接受指同意或收下别人的辞呈；批准的施事必须是有权的上级，下级不能批准上级的辞职。"}, {"text": "我批准了我自己的休假申请。", "explanation": "这里应该用〈提交〉。提交指把申请交给有权的人审批；自己不能批准自己的申请，批准的施事必须是上级。"}, {"text": "领导批准了他的微笑。", "explanation": "这里应该用〈欣赏〉。欣赏可用于微笑、表情等；批准的对象应是申请、计划等事项，微笑不能被批准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划终于批准起来了。", "corrected_sentence": "这个计划终于批准下来了。", "error_description": "补语错误：“批准”后应接趋向补语“下来”，说“批准下来”，不能说“批准起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府很批准了这个医院计划。", "corrected_sentence": "政府已经批准了这个医院计划。", "error_description": "副词错误：“很”修饰形容词，不能修饰动词“批准”；表示动作已完成应说“已经批准了”，不能说“很批准了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
