INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85830, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85830, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指一部分人或事物。", "primary_collocate": null, "pronunciation": "yǒu de", "ipa": "jou̯˨˩˦ tɤ", "syllable_count": 2, "sentences": [{"text": "有的人喜欢早上跑步。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，有的题很简单。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的水果，有的很新鲜，有的不新鲜。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的老师说话很快，我听不懂。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近的商店，有的晚上不关门。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的孩子怕黑，晚上不敢一个人睡。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些歌，有的我听过，有的没听过。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的人喝咖啡，有的人喝茶。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上的叶子有的黄了，有的还是绿的。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的同事有的会说英语，有的会说日语。", "target_word": "有的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "代词，泛指一部分人或事物，可单用：有的人……", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df888c7e-00bf-4d04-9d58-c326ae2207d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85830, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有的", "is_correct": true, "explanation": "正确：“有的”第二字为轻声，指一部分人或事物。"}, {"text": "有德", "is_correct": false, "explanation": "声调不同：“德”为第二声，“的”为轻声，意思是有道德。"}, {"text": "油的", "is_correct": false, "explanation": "声调不同：“油”为第二声，“有”为第三声，意思是油腻的。"}, {"text": "有地", "is_correct": false, "explanation": "声调不同：“地”为第四声，“的”为轻声，意思是拥有土地。"}], "explanations": {"有的": "正确：“有的”第二字为轻声，指一部分人或事物。", "有德": "声调不同：“德”为第二声，“的”为轻声，意思是有道德。", "油的": "声调不同：“油”为第二声，“有”为第三声，意思是油腻的。", "有地": "声调不同：“地”为第四声，“的”为轻声，意思是拥有土地。"}, "sentence_index": null, "correct_answer": "有的"}, "level_3": {"options": [{"text": "有的", "is_correct": true, "explanation": "正确：“有的人”指一部分人，陈述其中有人喜欢晨跑。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”已含全体义，后接“人”成“大家人”，不成词。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，“谁人喜欢”成了疑问，不能陈述一部分人。"}, {"text": "别人", "is_correct": false, "explanation": "搭配：“别人”本身指他人，后接“人”成“别人人”，重复不成词。"}], "explanations": {"有的": "正确：“有的人”指一部分人，陈述其中有人喜欢晨跑。", "大家": "搭配：“大家”已含全体义，后接“人”成“大家人”，不成词。", "谁": "语义：“谁”是疑问代词，“谁人喜欢”成了疑问，不能陈述一部分人。", "别人": "搭配：“别人”本身指他人，后接“人”成“别人人”，重复不成词。"}, "sentence_index": 0, "correct_answer": "有的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有的老师都很认真。", "explanation": "这里应该用〈所有〉。“所有”指全部，与“都”搭配；“有的”指一部分，与“都”矛盾。"}, {"text": "我的爸爸有的很爱唱歌。", "explanation": "这里应该用〈他〉。“有的”指一部分，需要多个对象；“我的爸爸”只有一个人，应用代词“他”。"}, {"text": "这些票有的都卖完了。", "explanation": "这里应该用〈全部〉。“有的”只指一部分，与“都卖完了”矛盾；若表示全部卖完，应说“全部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85830, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有的", "is_correct": true, "explanation": "正确：“有的”第二字为轻声，指一部分人或事物。"}, {"text": "有底", "is_correct": false, "explanation": "声调不同：“底”为第三声，“的”为轻声，意思是心里有把握，与“有的”不同。"}, {"text": "有毒", "is_correct": false, "explanation": "声调不同：“毒”为第二声，“的”为轻声，意思是含有毒素。"}, {"text": "油滴", "is_correct": false, "explanation": "声调不同：“油”为第二声、“滴”为第一声，意思是一滴油。"}], "explanations": {"有的": "正确：“有的”第二字为轻声，指一部分人或事物。", "有底": "声调不同：“底”为第三声，“的”为轻声，意思是心里有把握，与“有的”不同。", "有毒": "声调不同：“毒”为第二声，“的”为轻声，意思是含有毒素。", "油滴": "声调不同：“油”为第二声、“滴”为第一声，意思是一滴油。"}, "sentence_index": null, "correct_answer": "有的"}, "level_3": {"options": [{"text": "有的", "is_correct": true, "explanation": "正确：“有的”指一部分歌，与后句“有的没听过”相对。"}, {"text": "个个", "is_correct": false, "explanation": "语义：“个个”指每一个人，修饰“歌”不成搭配，且与“有的没听过”的部分之意矛盾。"}, {"text": "每个", "is_correct": false, "explanation": "搭配：歌的量词应为“首”，“每个”不搭配；且“每个”指全体，与后句矛盾。"}, {"text": "有人", "is_correct": false, "explanation": "搭配：“有人”表示存在某人，后接“我听过”不成句，与“这些歌”不相配。"}], "explanations": {"有的": "正确：“有的”指一部分歌，与后句“有的没听过”相对。", "个个": "语义：“个个”指每一个人，修饰“歌”不成搭配，且与“有的没听过”的部分之意矛盾。", "每个": "搭配：歌的量词应为“首”，“每个”不搭配；且“每个”指全体，与后句矛盾。", "有人": "搭配：“有人”表示存在某人，后接“我听过”不成句，与“这些歌”不相配。"}, "sentence_index": 6, "correct_answer": "有的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些学生有的都交了作业。", "explanation": "这里应该用〈全部〉。“有的”只指一部分，与“都交了作业”矛盾；若表示全体交了，应说“全部”。"}, {"text": "我的弟弟有的很爱运动。", "explanation": "这里应该用〈他〉。“有的”指一部分，需要多个对象；“我的弟弟”只有一个人，应用代词“他”。"}, {"text": "我的表哥有的很爱笑。", "explanation": "这里应该用〈他〉。“有的”指一部分，需要多个对象；“我的表哥”只有一个人，应用代词“他”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "有的有的人喜欢晚上看书。", "corrected_sentence": "有的人喜欢晚上看书。", "error_description": "错误：多写了一个“有的”。“有的人”已是完整的代词短语，重复后不成话。正确形式为“有的人喜欢晚上看书。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些衣服，有很便宜，有的很贵。", "corrected_sentence": "这些衣服，有的很便宜，有的很贵。", "error_description": "错误：第一个“有的”漏写了“的”。“有很便宜”不成话，指一部分衣服时应用“有的”。正确形式为“这些衣服，有的很便宜，有的很贵。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
