INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85831, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "早上是太阳刚出来的那段时间。", "primary_collocate": null, "pronunciation": "zǎo shang", "ipa": "tsɑʊ̯˨˩ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "早上太阳刚出来，院子里很安静。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的阳光照在窗户上，很温暖。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢早上在公园里看太阳慢慢升起来。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上太阳出来以后，地上的雾就没有了。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天早上太阳一出来就去河边钓鱼。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的太阳不热，很舒服。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天早上我看见了很红的太阳。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上太阳刚出来，花上还有水珠。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上太阳出来时，我们就出发。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的太阳很红，像一个大苹果。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大早上", "label": "复合"}], "register": "中性", "sense_fingerprint": "早上：太阳刚升起的那段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef0daaba-e68b-4c3c-a684-5319cdf29e05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早上", "is_correct": true, "explanation": "正确：“早上”指太阳刚升起的那段时间，与“太阳刚出来”相符。"}, {"text": "晚上", "is_correct": false, "explanation": "语义：太阳刚出来是清晨，“晚上”与“太阳刚出来”矛盾。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午太阳已经很高，不是“刚出来”的时候。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”指食物，不是时间段，不能作“太阳刚出来”的时间状语。"}], "explanations": {"早上": "正确：“早上”指太阳刚升起的那段时间，与“太阳刚出来”相符。", "晚上": "语义：太阳刚出来是清晨，“晚上”与“太阳刚出来”矛盾。", "中午": "语义：中午太阳已经很高，不是“刚出来”的时候。", "早饭": "搭配：“早饭”指食物，不是时间段，不能作“太阳刚出来”的时间状语。"}, "sentence_index": 0, "correct_answer": "早上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天吃早上以后去上班。", "explanation": "这里应该用〈早饭〉。“早上”是时间，不能作“吃”的宾语；吃的是食物，要说“早饭”。"}, {"text": "我们花了一只早上找钥匙。", "explanation": "这里应该用〈一个〉。“只”用于动物或小件物品等个体，时间段“早上”要用“个”，说“一个早上”。"}, {"text": "妈妈在厨房做早上。", "explanation": "这里应该用〈午饭〉。“做”的对象是饭菜，“早上”是时间，不能作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早上", "is_correct": true, "explanation": "正确：“早上”指太阳刚升起的那段时间，与“看见了很红的太阳”相符。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：半夜没有太阳，与“看见了很红的太阳”矛盾。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜是深夜，不是清晨，与“很红的太阳”矛盾。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“早餐”指食物，不是时间，不能放在“今天”之后作时间状语。"}], "explanations": {"早上": "正确：“早上”指太阳刚升起的那段时间，与“看见了很红的太阳”相符。", "半夜": "语义：半夜没有太阳，与“看见了很红的太阳”矛盾。", "午夜": "语义：午夜是深夜，不是清晨，与“很红的太阳”矛盾。", "早餐": "搭配：“早餐”指食物，不是时间，不能放在“今天”之后作时间状语。"}, "sentence_index": 6, "correct_answer": "早上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷每天准备早上。", "explanation": "这里应该用〈晚饭〉。“准备”的对象是饭菜，“早上”是时间，不能作宾语。"}, {"text": "他们在河边坐了一块早上。", "explanation": "这里应该用〈一个〉。“块”用于成块的东西，不能用来计量时间段；应说“一个早上”。"}, {"text": "朋友们常在宿舍吃早上。", "explanation": "这里应该用〈夜宵〉。“吃”的对象是食物，“早上”是时间，不能作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们整天早上都在忙着搬家。", "corrected_sentence": "我们整个早上都在忙着搬家。", "error_description": "错误形式：“整天早上”；正确形式：“整个早上”。“整天”是时间副词，不能直接修饰“早上”；修饰“早上”这段时间要用“整个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只早上我一直在复习。", "corrected_sentence": "这个早上我一直在复习。", "error_description": "错误形式：“这只早上”；正确形式：“这个早上”。“只”用于动物或小件物品，修饰时间词“早上”要用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
