INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从天快亮到八九点钟的一段时间。", "primary_collocate": null, "pronunciation": "zǎo shang", "ipa": "tsɑʊ̯˨˩ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "早上六点天刚亮，我就起床了。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早上八点以前要到学校。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上跑步，九点才回家。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上天快亮的时候，街上人很少。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上我们八点在门口见面。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈早上五点半起来做早饭。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上从六点到八点，路上车特别多。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天早上我喝了一杯牛奶。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上八点半，商店才开门。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早上七点坐地铁去上班。", "target_word": "早上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大早上", "label": "复合"}], "register": "中性", "sense_fingerprint": "早上：从天快亮到八九点钟的时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef0daaba-e68b-4c3c-a684-5319cdf29e05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早上", "is_correct": true, "explanation": "正确：“早上”指从天快亮到八九点的一段时间，六点天刚亮符合这个时段。"}, {"text": "晚上", "is_correct": false, "explanation": "语义：晚上六点天刚亮，与“天刚亮”矛盾。"}, {"text": "下午", "is_correct": false, "explanation": "语义：下午六点不会是天刚亮的时候，与句意矛盾。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“早饭”指食物，不是时段，不能与“六点天刚亮”搭配。"}], "explanations": {"早上": "正确：“早上”指从天快亮到八九点的一段时间，六点天刚亮符合这个时段。", "晚上": "语义：晚上六点天刚亮，与“天刚亮”矛盾。", "下午": "语义：下午六点不会是天刚亮的时候，与句意矛盾。", "早饭": "搭配：“早饭”指食物，不是时段，不能与“六点天刚亮”搭配。"}, "sentence_index": 0, "correct_answer": "早上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天吃早上以后出门。", "explanation": "这里应该用〈早饭〉。“早上”是时间，不能作“吃”的宾语；吃的是食物，要说“早饭”。"}, {"text": "我们在树下坐了一只早上。", "explanation": "这里应该用〈一个〉。“只”用于动物或小件物品等个体，时间段“早上”要说“一个早上”。"}, {"text": "妈妈每天准备早上。", "explanation": "这里应该用〈早餐〉。“准备”的对象是饭菜，“早上”是时间，不能作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早上", "is_correct": true, "explanation": "正确：“早上”指从六点到八点左右的时段，与句中的“从六点到八点”相符。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午是十二点左右，不在六点到八点之间，与句意矛盾。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：半夜不是六点到八点，与“从六点到八点”矛盾。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“早餐”指食物，不能表示一段时间，不能作“从……到……”的时段主语。"}], "explanations": {"早上": "正确：“早上”指从六点到八点左右的时段，与句中的“从六点到八点”相符。", "中午": "语义：中午是十二点左右，不在六点到八点之间，与句意矛盾。", "半夜": "语义：半夜不是六点到八点，与“从六点到八点”矛盾。", "早餐": "搭配：“早餐”指食物，不能表示一段时间，不能作“从……到……”的时段主语。"}, "sentence_index": 6, "correct_answer": "早上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在厨房忙了一片早上。", "explanation": "这里应该用〈一个〉。“片”用于成片的东西，不能用来计量时间段；应说“一个早上”。"}, {"text": "爷爷每天在院子里吃早上。", "explanation": "这里应该用〈午餐〉。“吃”的对象是食物，“早上”是时间，不能作宾语。"}, {"text": "我们在车站等了一张早上。", "explanation": "这里应该用〈一个〉。“张”用于纸、桌子等平面的东西，不能用来计量时间段；应说“一个早上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我整天早上都在图书馆写作业。", "corrected_sentence": "我整个早上都在图书馆写作业。", "error_description": "错误形式：“整天早上”；正确形式：“整个早上”。“整天”是时间副词，不能直接修饰“早上”；修饰“早上”这段时间要用“整个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只早上我们一直在等车。", "corrected_sentence": "这个早上我们一直在等车。", "error_description": "错误形式：“这只早上”；正确形式：“这个早上”。“只”用于动物或小件物品，修饰时间词“早上”要用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
