INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85833, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“跟”是介词，表示和某个人一起做事。", "primary_collocate": null, "pronunciation": "gēn", "ipa": "kən˥", "syllable_count": 1, "sentences": [{"text": "我跟朋友一起去看电影。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我跟家人去公园玩。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跟同学一起走路上学。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟你一起吃饭。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟妈妈去商店买东西。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跟我一起跑。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你跟我一起走，别怕。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟老师一起排队。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟同事一起去会议室。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟他们一起做作业。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟着", "label": "体标"}, {"form": "跟随", "label": "复合"}], "register": "中性", "sense_fingerprint": "和某人一起做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85833, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跟", "is_correct": true, "explanation": "跟：表示和某人一起做事，与听到的读音一致。"}, {"text": "耕", "is_correct": false, "explanation": "韵母 eng 与 en 不同，意思是耕作，如耕地。"}, {"text": "干", "is_correct": false, "explanation": "韵母 an 与 en 不同，意思是干活或干燥。"}, {"text": "奔", "is_correct": false, "explanation": "声母 b 与 g 不同，意思是奔跑。"}], "explanations": {"跟": "跟：表示和某人一起做事，与听到的读音一致。", "耕": "韵母 eng 与 en 不同，意思是耕作，如耕地。", "干": "韵母 an 与 en 不同，意思是干活或干燥。", "奔": "声母 b 与 g 不同，意思是奔跑。"}, "sentence_index": null, "correct_answer": "跟"}, "level_3": {"options": [{"text": "跟", "is_correct": true, "explanation": "跟：表示和朋友一起做事，符合“一起去看电影”的语境。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”表示对待或面向某人，不能表示和朋友一起做事。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要给予的对象和物品，后接“朋友”不能构成一起去的动作。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向，不能说明和朋友一起去。"}], "explanations": {"跟": "跟：表示和朋友一起做事，符合“一起去看电影”的语境。", "对": "语义：“对”表示对待或面向某人，不能表示和朋友一起做事。", "给": "配价：“给”需要给予的对象和物品，后接“朋友”不能构成一起去的动作。", "向": "语义：“向”表示方向，不能说明和朋友一起去。"}, "sentence_index": 0, "correct_answer": "跟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年的成绩跟去年比，提高了不少。", "explanation": "这里的“跟”表示比较（跟……比），不是和某人一起做事的意思，这种比较用法与该词的本义无关。"}, {"text": "他跟我一样高。", "explanation": "这里的“跟”表示比较（跟……一样），不是和某人一起做事的意思，与该词的本义无关。"}, {"text": "这个问题我们要跟进到底。", "explanation": "这里的“跟”是“跟进”，指持续关注、处理到底，不是和某人一起做事的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85833, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跟", "is_correct": true, "explanation": "跟：表示和某人一起做事，与听到的读音一致。"}, {"text": "甘", "is_correct": false, "explanation": "韵母 an 与 en 不同，意思是甘甜。"}, {"text": "刚", "is_correct": false, "explanation": "韵母 ang 与 en 不同，意思是刚刚、刚好。"}, {"text": "分", "is_correct": false, "explanation": "声母 f 与 g 不同，意思是分开或分钟。"}], "explanations": {"跟": "跟：表示和某人一起做事，与听到的读音一致。", "甘": "韵母 an 与 en 不同，意思是甘甜。", "刚": "韵母 ang 与 en 不同，意思是刚刚、刚好。", "分": "声母 f 与 g 不同，意思是分开或分钟。"}, "sentence_index": null, "correct_answer": "跟"}, "level_3": {"options": [{"text": "跟", "is_correct": true, "explanation": "跟：表示和我一起走，符合“你跟我一起走”的句意。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人，“你替我走”句意不通。"}, {"text": "从", "is_correct": false, "explanation": "配价：“从”需要处所作宾语，“从我走”不能表示跟随的动作。"}, {"text": "比", "is_correct": false, "explanation": "语义：“比”表示比较，“你比我走”句意不通。"}], "explanations": {"跟": "跟：表示和我一起走，符合“你跟我一起走”的句意。", "替": "语义：“替”表示代替某人，“你替我走”句意不通。", "从": "配价：“从”需要处所作宾语，“从我走”不能表示跟随的动作。", "比": "语义：“比”表示比较，“你比我走”句意不通。"}, "sentence_index": 6, "correct_answer": "跟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋的跟很高。", "explanation": "这里的“跟”指鞋后部，是名词，与表示和某人一起做事的介词“跟”无关。"}, {"text": "我跟不上他的速度。", "explanation": "这里的“跟”是动词，意思是赶上，不是介词“跟”，不能引出一起做事的对象。"}, {"text": "他总是跟风买东西。", "explanation": "这里的“跟”指跟随潮流（跟风），是比喻用法，不表示和某人一起做事，与该词的本义无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午跟一起去图书馆。", "corrected_sentence": "我下午跟同学一起去图书馆。", "error_description": "错误：介词“跟”后缺少对象，无法引出一起去的人。正确：应补上对象，即“我下午跟同学一起去图书馆。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我跟在老师聊了很久。", "corrected_sentence": "我跟老师聊了很久。", "error_description": "错误：“跟在”表示紧随在后面，不能再引出聊天的对象；“在”不能加在“跟”后。正确：应说“我跟老师聊了很久。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
