INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85834, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示共同参与动作的对象，相当于“和”。", "primary_collocate": null, "pronunciation": "gēn", "ipa": "kən˥", "syllable_count": 1, "sentences": [{"text": "我跟老师说话。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟我商量这件事。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟姐姐住在一起。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天跟他打过电话。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你跟谁聊天？", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟你见面。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跟我们一起开会。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子跟妈妈玩游戏。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟你一起回家。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹跟我一起去超市。", "target_word": "跟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跟着", "label": "体标"}, {"form": "跟随", "label": "复合"}], "register": "中性", "sense_fingerprint": "引出共同参与动作的对象，相当于“和”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85834, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跟", "is_correct": true, "explanation": "gēn（第一声），介词，表示共同参与的对象，相当于“和”。"}, {"text": "干", "is_correct": false, "explanation": "gān（第一声）与 gēn 的元音不同（ā 与 ē），意思是“干燥”或“做”。"}, {"text": "耕", "is_correct": false, "explanation": "gēng（第一声）与 gēn 的韵尾不同（-ng 与 -n），意思是“耕种”。"}, {"text": "肝", "is_correct": false, "explanation": "gān（第一声）与 gēn 的元音不同，意思是“肝脏”。"}], "explanations": {"跟": "gēn（第一声），介词，表示共同参与的对象，相当于“和”。", "干": "gān（第一声）与 gēn 的元音不同（ā 与 ē），意思是“干燥”或“做”。", "耕": "gēng（第一声）与 gēn 的韵尾不同（-ng 与 -n），意思是“耕种”。", "肝": "gān（第一声）与 gēn 的元音不同，意思是“肝脏”。"}, "sentence_index": null, "correct_answer": "跟"}, "level_3": {"options": [{"text": "跟", "is_correct": true, "explanation": "介词，引出共同参与说话的对象，“我”与“老师”一起说话，句意通顺。"}, {"text": "在", "is_correct": false, "explanation": "搭配：“在”引出处所，“老师”不是地点，不能说“在老师说话”，应说“在老师面前说话”。"}, {"text": "按", "is_correct": false, "explanation": "配价：“按”后接的应是可依照的规定或标准，“老师”不能作依据，“按老师说话”不通。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”引出来源或起点，“说话”与来源无关，不能说“从老师说话”。"}], "explanations": {"跟": "介词，引出共同参与说话的对象，“我”与“老师”一起说话，句意通顺。", "在": "搭配：“在”引出处所，“老师”不是地点，不能说“在老师说话”，应说“在老师面前说话”。", "按": "配价：“按”后接的应是可依照的规定或标准，“老师”不能作依据，“按老师说话”不通。", "从": "语义：“从”引出来源或起点，“说话”与来源无关，不能说“从老师说话”。"}, "sentence_index": 0, "correct_answer": "跟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我跟笔写字。", "explanation": "这里应该用〈用〉。“跟”引出共同参与的人或对象，不能表示用来做事的工具；写字用工具要说“用笔写字”。"}, {"text": "我跟北京工作。", "explanation": "这里应该用〈在〉。“跟”引出共同参与的对象，不能引出地点；表示工作地点要说“在北京工作”。"}, {"text": "我跟三点开始上课。", "explanation": "这里应该用〈从〉。“跟”不能表示时间起点；表示从某个时间开始要说“从三点开始上课”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跟", "is_correct": true, "explanation": "介词，引出共同参与开会的对象，“他”与“我们”一起开会。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替别人，与“一起”表示共同参与相矛盾。"}, {"text": "由", "is_correct": false, "explanation": "语义：“由”引出动作的执行者或负责者，“由我们一起开会”不能表示“他”与“我们”共同参与，句意不通。"}, {"text": "朝", "is_correct": false, "explanation": "语义：“朝”表示朝向某个方向，“一起开会”没有方向，不能说“朝我们一起开会”。"}], "explanations": {"跟": "介词，引出共同参与开会的对象，“他”与“我们”一起开会。", "替": "语义：“替”表示代替别人，与“一起”表示共同参与相矛盾。", "由": "语义：“由”引出动作的执行者或负责者，“由我们一起开会”不能表示“他”与“我们”共同参与，句意不通。", "朝": "语义：“朝”表示朝向某个方向，“一起开会”没有方向，不能说“朝我们一起开会”。"}, "sentence_index": 6, "correct_answer": "跟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跟钱打工。", "explanation": "这里应该用〈为了〉。“跟”引出共同参与的对象，不能表示目的；为了赚钱而打工要说“为了钱打工”。"}, {"text": "我们跟公园散步。", "explanation": "这里应该用〈在〉。“跟”引出共同参与的对象，不能引出地点；表示散步的地点要说“在公园散步”。"}, {"text": "我们跟晚上十点工作。", "explanation": "这里应该用〈到〉。“跟”不能表示时间终点；表示工作到某时要说“工作到晚上十点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下班后跟在一个朋友去看电影。", "corrected_sentence": "我下班后跟一个朋友去看电影。", "error_description": "错误：“在”不能加在“跟”后引出对象；“跟在”表示紧随在后面，与一起去看电影不符。正确：应删去“在”，即“我下班后跟一个朋友去看电影。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天晚上我跟在你视频通话。", "corrected_sentence": "今天晚上我跟你视频通话。", "error_description": "错误：“在”不能加在“跟”后引出对象。“跟在”表示紧随在后面，与视频通话不搭。正确：“今天晚上我跟你视频通话。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
