INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“请”是有礼貌地要别人做一件事。", "primary_collocate": null, "pronunciation": "qǐng", "ipa": "tɕʰiŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "请坐，喝杯茶吧。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把门关上。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再说一遍。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家安静一下。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我地铁站怎么走。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请您先填一下这张表。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别在这里抽烟。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请慢走，路上小心。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我拿一下包。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一杯水。", "target_word": "请", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "請", "label": "繁体"}, {"form": "请了", "label": "完成体"}, {"form": "请过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "动词：有礼貌地请别人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5414130c-939f-47d2-a1d8-a425c962efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85835, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "请", "is_correct": true, "explanation": "正确。“请”（qǐng）意思是有礼貌地请别人做某事。"}, {"text": "轻", "is_correct": false, "explanation": "qīng（第一声）与 qǐng（第三声）声调不同，“轻”意思是重量小。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 qǐng（第三声）声调不同，“情”意思是感情。"}, {"text": "清", "is_correct": false, "explanation": "qīng（第一声）与 qǐng（第三声）声调不同，“清”意思是干净或清楚。"}], "explanations": {"请": "正确。“请”（qǐng）意思是有礼貌地请别人做某事。", "轻": "qīng（第一声）与 qǐng（第三声）声调不同，“轻”意思是重量小。", "情": "qíng（第二声）与 qǐng（第三声）声调不同，“情”意思是感情。", "清": "qīng（第一声）与 qǐng（第三声）声调不同，“清”意思是干净或清楚。"}, "sentence_index": null, "correct_answer": "请"}, "level_3": {"options": [{"text": "请", "is_correct": true, "explanation": "正确。“请坐”是有礼貌地请对方坐下。"}, {"text": "让", "is_correct": false, "explanation": "配价：“让”要求兼语，“让坐”缺少宾语，不成立。"}, {"text": "叫", "is_correct": false, "explanation": "配价：“叫”要求带宾语，“叫坐”缺少宾语，不成立。"}, {"text": "带", "is_correct": false, "explanation": "搭配：“带”指携带，不能与“坐”组成请人坐下的说法。"}], "explanations": {"请": "正确。“请坐”是有礼貌地请对方坐下。", "让": "配价：“让”要求兼语，“让坐”缺少宾语，不成立。", "叫": "配价：“叫”要求带宾语，“叫坐”缺少宾语，不成立。", "带": "搭配：“带”指携带，不能与“坐”组成请人坐下的说法。"}, "sentence_index": 0, "correct_answer": "请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请天气快点变好。", "explanation": "这里应该用〈希望〉。“请”的对象应是能听从请求的人，不能用于天气。"}, {"text": "你请我的礼物，我很感谢。", "explanation": "这里应该用〈送〉。“请”表示邀请或要求，不表示赠送；别人送的礼物应说“你送我的礼物”。"}, {"text": "请太阳晚一点落山。", "explanation": "这里应该用〈希望〉。“请”的对象应是人，不能用于太阳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85835, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "请", "is_correct": true, "explanation": "正确。“请”（qǐng）意思是有礼貌地请别人做某事。"}, {"text": "庆", "is_correct": false, "explanation": "qìng（第四声）与 qǐng（第三声）声调不同，“庆”意思是庆祝。"}, {"text": "青", "is_correct": false, "explanation": "qīng（第一声）与 qǐng（第三声）声调不同，“青”意思是绿色。"}, {"text": "晴", "is_correct": false, "explanation": "qíng（第二声）与 qǐng（第三声）声调不同，“晴”意思是天气晴朗。"}], "explanations": {"请": "正确。“请”（qǐng）意思是有礼貌地请别人做某事。", "庆": "qìng（第四声）与 qǐng（第三声）声调不同，“庆”意思是庆祝。", "青": "qīng（第一声）与 qǐng（第三声）声调不同，“青”意思是绿色。", "晴": "qíng（第二声）与 qǐng（第三声）声调不同，“晴”意思是天气晴朗。"}, "sentence_index": null, "correct_answer": "请"}, "level_3": {"options": [{"text": "请", "is_correct": true, "explanation": "正确。“请别在这里抽烟”是有礼貌地请对方不要抽烟。"}, {"text": "允许", "is_correct": false, "explanation": "语义：“允许”表示准许，与“别在这里抽烟”的禁止语气相矛盾。"}, {"text": "禁止", "is_correct": false, "explanation": "搭配：“禁止”后直接接“在这里抽烟”，与“别”连用是重复否定，一般不这样说。"}, {"text": "阻止", "is_correct": false, "explanation": "配价：“阻止”要带被阻止的动作作宾语，“阻止别在这里抽烟”的结构不成立。"}], "explanations": {"请": "正确。“请别在这里抽烟”是有礼貌地请对方不要抽烟。", "允许": "语义：“允许”表示准许，与“别在这里抽烟”的禁止语气相矛盾。", "禁止": "搭配：“禁止”后直接接“在这里抽烟”，与“别”连用是重复否定，一般不这样说。", "阻止": "配价：“阻止”要带被阻止的动作作宾语，“阻止别在这里抽烟”的结构不成立。"}, "sentence_index": 6, "correct_answer": "请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请太阳照亮这间屋子。", "explanation": "这里应该用〈希望〉。“请”的对象应是人，不能用于太阳。"}, {"text": "你请我的帮助，我很高兴。", "explanation": "这里应该用〈给〉。“请”表示邀请或要求，不表示给予；别人给我的帮助应说“你给我的帮助”。"}, {"text": "请风吹得再轻一点。", "explanation": "这里应该用〈希望〉。“请”的对象应是人，不能用于风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把窗户关上过。", "corrected_sentence": "请把窗户关上。", "error_description": "错误形式：“关上过”；正确形式：“关上”。“请”提出的是还没做的请求，后面的动作不能用经历体“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请给我一杯咖啡了。", "corrected_sentence": "请给我一杯咖啡。", "error_description": "错误形式：“一杯咖啡了”；正确形式：“一杯咖啡”。“请”开头的句子是请求对方做还没做的事，句末不能加表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
