INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用火药或压缩空气发射子弹的武器。", "primary_collocate": null, "pronunciation": "qiāng", "ipa": "tɕʰiɑŋ˥", "syllable_count": 1, "sentences": [{"text": "这支枪用火药发射子弹。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵背着一支枪站在门口。", "target_word": "枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起枪，对准了前面。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察拿出枪，让他别动。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打猎的人需要有枪。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "枪里没有子弹了。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个士兵每天都要擦枪。", "target_word": "枪", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这把枪很重，孩子拿不动。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把枪交给了警察。", "target_word": "枪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多国家不让人买枪。", "target_word": "枪", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一把枪", "label": "量词"}, {"form": "一支枪", "label": "量词"}, {"form": "手枪", "label": "复合"}, {"form": "槍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发射子弹的武器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '537c4520-879d-4465-a1a7-51ade1e4b38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85838, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "枪", "is_correct": true, "explanation": "枪：利用火药发射子弹的武器。"}, {"text": "墙", "is_correct": false, "explanation": "qiáng（第二声）与 qiāng（第一声）声调不同，意思是墙。"}, {"text": "抢", "is_correct": false, "explanation": "qiǎng（第三声）与 qiāng（第一声）声调不同，意思是抢夺。"}, {"text": "千", "is_correct": false, "explanation": "qiān 与 qiāng 韵母不同（an 与 ang），意思是一千。"}, {"text": "江", "is_correct": false, "explanation": "jiāng 与 qiāng 声母不同（j 与 q），意思是江河。"}, {"text": "香", "is_correct": false, "explanation": "xiāng 与 qiāng 声母不同（x 与 q），意思是香气。"}], "explanations": {"枪": "枪：利用火药发射子弹的武器。", "墙": "qiáng（第二声）与 qiāng（第一声）声调不同，意思是墙。", "抢": "qiǎng（第三声）与 qiāng（第一声）声调不同，意思是抢夺。", "千": "qiān 与 qiāng 韵母不同（an 与 ang），意思是一千。", "江": "jiāng 与 qiāng 声母不同（j 与 q），意思是江河。", "香": "xiāng 与 qiāng 声母不同（x 与 q），意思是香气。"}, "sentence_index": null, "correct_answer": "枪"}, "level_3": {"options": [{"text": "枪", "is_correct": true, "explanation": "枪：利用火药发射子弹的武器，量词用“支”，符合句意。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔不能用火药发射子弹，与句中描述冲突。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能发射子弹，与句中描述冲突。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词“支”不用于房子，房子用“座”或“栋”。"}], "explanations": {"枪": "枪：利用火药发射子弹的武器，量词用“支”，符合句意。", "笔": "语义：笔不能用火药发射子弹，与句中描述冲突。", "花": "语义：花不能发射子弹，与句中描述冲突。", "房子": "搭配：量词“支”不用于房子，房子用“座”或“栋”。"}, "sentence_index": 0, "correct_answer": "枪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察拿出一只枪，让他别动。", "explanation": "这里应该用〈把〉或〈支〉。“只”用于动物或成对物件中的一个，不用来计量枪。"}, {"text": "警察用枪剪开了绳子，让他别动。", "explanation": "这里应该用〈剪刀〉。枪是利用火药发射子弹的武器，不能用来剪东西。"}, {"text": "他把枪当成扫帚，在院子里扫落叶。", "explanation": "这里应该用〈扫帚〉。枪是利用火药发射子弹的武器，不能当扫帚用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85838, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "枪", "is_correct": true, "explanation": "枪：利用火药发射子弹的武器。"}, {"text": "强", "is_correct": false, "explanation": "qiáng（第二声）与 qiāng（第一声）声调不同，意思是强大。"}, {"text": "将", "is_correct": false, "explanation": "jiāng 与 qiāng 声母不同（j 与 q），意思是将要。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng 与 qiāng 声母不同（x 与 q），意思是乡村。"}, {"text": "牵", "is_correct": false, "explanation": "qiān 与 qiāng 韵母不同（an 与 ang），意思是牵引。"}], "explanations": {"枪": "枪：利用火药发射子弹的武器。", "强": "qiáng（第二声）与 qiāng（第一声）声调不同，意思是强大。", "将": "jiāng 与 qiāng 声母不同（j 与 q），意思是将要。", "乡": "xiāng 与 qiāng 声母不同（x 与 q），意思是乡村。", "牵": "qiān 与 qiāng 韵母不同（an 与 ang），意思是牵引。"}, "sentence_index": null, "correct_answer": "枪"}, "level_3": {"options": [{"text": "枪", "is_correct": true, "explanation": "枪：可以擦拭保养的武器，士兵常要擦枪，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能擦，与“擦”的对象冲突。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“擦”的对象须为可擦拭之物，“空气”不能擦。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不是可擦拭的物件，与句意冲突。"}], "explanations": {"枪": "枪：可以擦拭保养的武器，士兵常要擦枪，符合句意。", "天空": "语义：天空不能擦，与“擦”的对象冲突。", "空气": "搭配：“擦”的对象须为可擦拭之物，“空气”不能擦。", "星星": "语义：星星不是可擦拭的物件，与句意冲突。"}, "sentence_index": 6, "correct_answer": "枪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在地上捡到了一块枪。", "explanation": "这里应该用〈把〉或〈支〉。“块”用于块状或扁平的东西，不用来计量枪。"}, {"text": "他买了一张枪送给朋友。", "explanation": "这里应该用〈把〉或〈支〉。“张”用于纸、桌子等平面的东西，不用来计量枪。"}, {"text": "他在箱子里找到一颗枪。", "explanation": "这里应该用〈把〉或〈支〉。“颗”用于颗粒状或小而圆的东西，不用来计量枪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一只枪锁进了柜子。", "corrected_sentence": "他把一支枪锁进了柜子。", "error_description": "量词错误：“枪”前不能用量词“只”（“只”多用于动物或成对物件中的一个），应改用“把”或“支”，如“一把枪”“一支枪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察以前过用这种枪。", "corrected_sentence": "警察以前用过这种枪。", "error_description": "“过”的位置错误：经历标记“过”应紧跟动词，应为“用过这种枪”，不能放在动词“用”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
