INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85839, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“一些”是说不太多的几个东西。", "primary_collocate": null, "pronunciation": "yì xiē", "ipa": "i˥˩ ɕje˥", "syllable_count": 2, "sentences": [{"text": "桌子上有一些苹果。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一些水果。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里有一些学生。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给我一些书。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有一些老人在跑步。", "target_word": "一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在市场买了一些菜。", "target_word": "一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友带来一些茶。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里还有一些牛奶。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我一些纸和笔。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院子里种着一些花。", "target_word": "一些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不定量词：放在名词前，指不太多的几个东西（一些苹果）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一些", "is_correct": true, "explanation": "正确。“一些”表示不太多的几个，可以修饰“苹果”。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、楼等大型固定物，不能修饰苹果。"}, {"text": "一头", "is_correct": false, "explanation": "搭配：“头”用于大型牲畜，不能用来计量苹果。"}, {"text": "一台", "is_correct": false, "explanation": "语义：“台”多指机器，与桌上的一堆苹果不相符。"}], "explanations": {"一些": "正确。“一些”表示不太多的几个，可以修饰“苹果”。", "一座": "搭配：“座”用于山、楼等大型固定物，不能修饰苹果。", "一头": "搭配：“头”用于大型牲畜，不能用来计量苹果。", "一台": "语义：“台”多指机器，与桌上的一堆苹果不相符。"}, "sentence_index": 0, "correct_answer": "一些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给我一些书，整整一百本。", "explanation": "这里应该用〈一大批〉。「一些」只指不太多的几个，不能用来说一百本这样的大量。"}, {"text": "他给我一些书，只有一本。", "explanation": "「一些」指不太多的几个，不能指只有一件；这里的意思是单独一件，应该用〈一个〉这类单数说法，而不用「一些」。"}, {"text": "他给我一些书，一本也没有。", "explanation": "「一些」表示存在不太多的几本，而句子说一本也没有，要表达〈零〉，不能用「一些」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一些", "is_correct": true, "explanation": "正确。“一些”表示不太多的几个，与“带来茶”相符。"}, {"text": "一幅", "is_correct": false, "explanation": "搭配：“幅”用于字画，不能用来计量茶。"}, {"text": "一张", "is_correct": false, "explanation": "语义：“张”多用于平面的东西，茶不以这种方式计量。"}, {"text": "一条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，茶不用这个量词。"}], "explanations": {"一些": "正确。“一些”表示不太多的几个，与“带来茶”相符。", "一幅": "搭配：“幅”用于字画，不能用来计量茶。", "一张": "语义：“张”多用于平面的东西，茶不以这种方式计量。", "一条": "搭配：“条”用于细长的东西，茶不用这个量词。"}, "sentence_index": 6, "correct_answer": "一些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里种着一些花，一朵也没有。", "explanation": "「一些」表示存在不太多的几朵，而句子说一朵都不存在，要表达〈零〉，不能用「一些」。"}, {"text": "院子里种着一些花，多得数不清。", "explanation": "「一些」表示不太多的少量，不能用来形容数量极多。"}, {"text": "院子里种着一些花，开得满院都是。", "explanation": "这里应该用〈一大片〉。「一些」只指不太多的几个，不能用来形容开满整个院子的大量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一个一些香蕉。", "corrected_sentence": "我昨天买了一些香蕉。", "error_description": "“一些”本身已是数量修饰语，前面不能再加“一个”。“一个一些香蕉”是错误形式，应为“一些香蕉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天在超市买了很一些橘子。", "corrected_sentence": "我昨天在超市买了一些橘子。", "error_description": "错误：“一些”前不能加副词“很”，“很一些橘子”是错误形式，应为“一些橘子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
