INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85840, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数量词，表示不定的数量，指少量。", "primary_collocate": null, "pronunciation": "yì xiē", "ipa": "i˥˩ ɕje˥", "syllable_count": 2, "sentences": [{"text": "我需要一些时间想想。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给了我一些帮助。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请再加一些水。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想问你一些问题。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些菜太多了，我只吃一些。", "target_word": "一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤有点淡，再放一些盐。", "target_word": "一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她提出了一些好意见。", "target_word": "一些", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我知道一些，但不是全部。", "target_word": "一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里有一些想法，没有说出来。", "target_word": "一些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们聊了一些工作上的事。", "target_word": "一些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量词：表示不定的少量，可修饰抽象或不可数的事物，也可单独使用（一些时间、只吃一些）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一些", "is_correct": true, "explanation": "正确。“一些”表示不定的少量，可以修饰抽象的“时间”。"}, {"text": "一座", "is_correct": false, "explanation": "搭配：“座”用于山、楼等大型固定物，不能修饰时间。"}, {"text": "一台", "is_correct": false, "explanation": "语义：“台”多指机器，与抽象的“时间”不相关。"}, {"text": "一幅", "is_correct": false, "explanation": "搭配：“幅”用于字画，不能用来计量时间。"}], "explanations": {"一些": "正确。“一些”表示不定的少量，可以修饰抽象的“时间”。", "一座": "搭配：“座”用于山、楼等大型固定物，不能修饰时间。", "一台": "语义：“台”多指机器，与抽象的“时间”不相关。", "一幅": "搭配：“幅”用于字画，不能用来计量时间。"}, "sentence_index": 0, "correct_answer": "一些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想问你一些问题，有好几十个。", "explanation": "这里应该用〈一大堆〉。「一些」只指少量，不能用来说好几十个这样的大量。"}, {"text": "我想问你一些问题，只有一个。", "explanation": "这里应该用〈一个〉。「一些」指不太多的几个，不能指只有一个；句子说只有一个问题，应该说“一个问题”。"}, {"text": "我想问你一些问题，一个也没有。", "explanation": "「一些」表示存在不太多的几个，而句子说一个都没有，要表达〈零〉，不能用「一些」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一些", "is_correct": true, "explanation": "正确。“一些”表示不太多的几个，可以修饰“意见”。"}, {"text": "一扇", "is_correct": false, "explanation": "搭配：“扇”用于门窗，不能用来计量意见。"}, {"text": "一片", "is_correct": false, "explanation": "搭配：“片”用于大片平面或区域，不能用来计量意见。"}, {"text": "一根", "is_correct": false, "explanation": "语义：“根”用于细长的东西，意见不属于这一类。"}], "explanations": {"一些": "正确。“一些”表示不太多的几个，可以修饰“意见”。", "一扇": "搭配：“扇”用于门窗，不能用来计量意见。", "一片": "搭配：“片”用于大片平面或区域，不能用来计量意见。", "一根": "语义：“根”用于细长的东西，意见不属于这一类。"}, "sentence_index": 6, "correct_answer": "一些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们聊了一些工作上的事，一件也没有。", "explanation": "「一些」表示存在几件，而句子说一件都没有，要表达〈零〉，不能用「一些」。"}, {"text": "我们聊了一些工作上的事，聊了好几十件。", "explanation": "「一些」表示不太多的少量，不能用来指大量的事情，这种情况应该用〈许多〉。"}, {"text": "我们聊了一些工作上的事，有几百件。", "explanation": "这里应该用〈一大堆〉。「一些」只指少量，不能用来指几百件这样的大量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我需要一个一些时间考虑一下。", "corrected_sentence": "我需要一些时间考虑一下。", "error_description": "“一些”本身已是数量修饰语，前面不能再加“一个”。正确说法是“一些时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天提出了一些了好意见。", "corrected_sentence": "她昨天提出了一些好意见。", "error_description": "“了”只用一个，应紧跟动词“提出”，不能插在“一些”和“好意见”之间。正确说法是“提出了一些好意见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
