INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85841, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“全国”是说一个国家的所有地方。", "primary_collocate": null, "pronunciation": "quán guó", "ipa": "tɕʰyɛn˧˥ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "这种茶在全国都能买到。", "target_word": "全国", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "全国各地的人都来参加比赛。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的歌红遍了全国。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电话号码全国都能用。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想坐火车走遍全国。", "target_word": "全国", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "全国的医院都在帮助病人。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老师的书全国都有人看。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试在全国同时进行。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全国的孩子都喜欢这个动画片。", "target_word": "全国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国庆节那天，全国都放假。", "target_word": "全国", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "全國", "label": "繁体"}, {"form": "全国性", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个国家的所有地方，强调每个地方都包括在内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee9cc0a1-56c1-4470-a8fc-b7afcfb653ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85841, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全国", "is_correct": true, "explanation": "正确：“全国”指一个国家的所有地方，与“这种茶在……都能买到”相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴不是能买茶的地方，不能说“在钢琴都能买到”。"}, {"text": "身体", "is_correct": false, "explanation": "搭配：“身体”不能作“买到”的地点，句子说不通。"}, {"text": "海底", "is_correct": false, "explanation": "语义：“海底”不是一般买茶的地点，与“都能买到”的语境不符。"}], "explanations": {"全国": "正确：“全国”指一个国家的所有地方，与“这种茶在……都能买到”相符。", "钢琴": "搭配：钢琴不是能买茶的地方，不能说“在钢琴都能买到”。", "身体": "搭配：“身体”不能作“买到”的地点，句子说不通。", "海底": "语义：“海底”不是一般买茶的地点，与“都能买到”的语境不符。"}, "sentence_index": 0, "correct_answer": "全国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药在全国十几个国家都有人用。", "explanation": "这里应该用〈全球〉。全国只指一个国家的范围，不能用于十几个国家；涉及多个国家要用全球。"}, {"text": "我们班全国的同学都喜欢这个老师。", "explanation": "这里应该用〈全班〉。全国指国家范围，不能用来指一个班的同学；班里所有人要用全班。"}, {"text": "我们学校全国的老师都参加了培训。", "explanation": "这里应该用〈全校〉。全国不能用于一所学校的范围；学校内所有老师要用全校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全国", "is_correct": true, "explanation": "正确：“全国”作状语，表示在全国范围内都有人看，与句意相符。"}, {"text": "全身", "is_correct": false, "explanation": "搭配：“全身”指身体，不能说“书全身都有人看”。"}, {"text": "全班", "is_correct": false, "explanation": "语义：“全班”只指一个班级，范围太小，与名师著作的读者范围不符。"}, {"text": "全屋", "is_correct": false, "explanation": "语义：“全屋”指整间屋子，与书的读者范围不符。"}], "explanations": {"全国": "正确：“全国”作状语，表示在全国范围内都有人看，与句意相符。", "全身": "搭配：“全身”指身体，不能说“书全身都有人看”。", "全班": "语义：“全班”只指一个班级，范围太小，与名师著作的读者范围不符。", "全屋": "语义：“全屋”指整间屋子，与书的读者范围不符。"}, "sentence_index": 6, "correct_answer": "全国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼全国的住户都搬走了。", "explanation": "这里应该用〈全楼〉。全国指整个国家，不能用于一栋楼；楼里的住户要用全楼。"}, {"text": "这个小镇全国的居民都来看热闹了。", "explanation": "这里应该用〈全镇〉。全国的范围与一个小镇不符；小镇的居民要用全镇。"}, {"text": "医院全国的医生都参加了会议。", "explanation": "这里应该用〈全院〉。全国不能用于一家医院的范围；医院内的医生要用全院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种茶在一个全国各地都能买到。", "corrected_sentence": "这种茶在全国各地都能买到。", "error_description": "“全国”是范围词，不能用数量词“一个”修饰，应删去“一个”，说“全国各地都能买到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个全国小学都开始放假了。", "corrected_sentence": "全国小学都开始放假了。", "error_description": "“全国”是范围词，不能用数量词“一个”修饰，应删去“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
