INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85843, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发动是让机器开始转起来。", "primary_collocate": null, "pronunciation": "fā dòng", "ipa": "fa˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他坐进车里，发动了汽车。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太冷，汽车怎么也发动不了。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸发动摩托车，带我去学校。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先发动船上的机器，再慢慢开船。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅发动拖拉机，下地干活了。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机发动汽车后，慢慢开出了院子。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆旧车很难发动，要试好几次。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力一拉，发动了小船上的机器。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动飞机以前，要先检查油够不够。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了，我们只好推车，因为发动不起来。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发动机", "label": "复合"}], "register": "中性", "sense_fingerprint": "发动：让汽车、机器等开始运转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef0daaba-e68b-4c3c-a684-5319cdf29e05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发动", "is_correct": true, "explanation": "正确：“发动”指使汽车开始运转，与“坐进车里”后启动汽车的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“汽车”作宾语，“吃了汽车”不通。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”用于火、灯等，不能说“熄灭汽车”，汽车只能说“熄火”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能以“汽车”作宾语，“唱了汽车”不通。"}], "explanations": {"发动": "正确：“发动”指使汽车开始运转，与“坐进车里”后启动汽车的语境相符。", "吃": "搭配：“吃”不能以“汽车”作宾语，“吃了汽车”不通。", "熄灭": "搭配：“熄灭”用于火、灯等，不能说“熄灭汽车”，汽车只能说“熄火”。", "唱": "搭配：“唱”不能以“汽车”作宾语，“唱了汽车”不通。"}, "sentence_index": 0, "correct_answer": "发动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他充分发动了自己的特长。", "explanation": "这里应该用〈发挥〉。“发动”指使机器运转或发起行动，不能与“特长”搭配；施展能力要说“发挥”。"}, {"text": "他按下开关，发动了电脑。", "explanation": "这里应该用〈启动〉。“发动”多用于汽车、船、飞机等靠发动机运转的机器，电脑、程序要说“启动”。"}, {"text": "公司发动了一条新闻。", "explanation": "这里应该用〈发布〉。“发动”用于机器、行动或进攻，不能用于新闻，发布消息要说“发布”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发动", "is_correct": true, "explanation": "正确：“发动”指使机器开始运转，与“很难开动”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“旧车”为对象，“很难吃”不通。"}, {"text": "飞", "is_correct": false, "explanation": "语义：汽车不能飞，“很难飞”与句子的语境矛盾。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能用于汽车，“很难煮”不通。"}], "explanations": {"发动": "正确：“发动”指使机器开始运转，与“很难开动”的语境相符。", "吃": "搭配：“吃”不能以“旧车”为对象，“很难吃”不通。", "飞": "语义：汽车不能飞，“很难飞”与句子的语境矛盾。", "煮": "搭配：“煮”不能用于汽车，“很难煮”不通。"}, "sentence_index": 6, "correct_answer": "发动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他发动了一篇文章。", "explanation": "这里应该用〈发表〉。“发动”用于机器、车船或行动，文章要说“发表”。"}, {"text": "这个问题发动了大家的注意。", "explanation": "这里应该用〈引起〉。“发动”不能与“注意”搭配，使人关注要说“引起”。"}, {"text": "他发动了好榜样。", "explanation": "这里应该用〈树立〉。“发动”不能与“榜样”搭配，树立榜样要说“树立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一转钥匙，汽车就发动下来了。", "corrected_sentence": "他一转钥匙，汽车就发动起来了。", "error_description": "错误形式：“发动下来”；正确形式：“发动起来”。表示机器开始并持续运转要用“起来”，不用“下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆旧车他试了三次，都没发动了。", "corrected_sentence": "这辆旧车他试了三次，都没发动起来。", "error_description": "错误形式：“没发动了”；正确形式：“没发动起来”。“没”否定已发生的动作时，动词后不能再加“了”；表示机器没能开始运转，要用“没发动起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
