INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85844, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发起或号召某种行动、活动，如发动群众、发动进攻。", "primary_collocate": null, "pronunciation": "fā dòng", "ipa": "fa˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学校发动同学们给山区小学捐书。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发动大家一起打扫教室。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长发动村民修了一条新路。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们发动了一次很大的植树活动。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家发动战争，百姓过得很苦。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队在早上发动了进攻。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司发动员工提出好办法。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发动朋友们一起去帮助老人。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里发动市民参加爱护环境的活动。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人突然发动进攻，我们只好后退。", "target_word": "发动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发动机", "label": "复合"}], "register": "中性", "sense_fingerprint": "发动：号召、发起某种行动或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef0daaba-e68b-4c3c-a684-5319cdf29e05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发动", "is_correct": true, "explanation": "正确：“发动”指号召、发起某种活动，与“同学们给山区小学捐书”的语境相符。"}, {"text": "捐", "is_correct": false, "explanation": "配价：“捐”的宾语要是财物，不能以“同学们”作宾语，句子不通。"}, {"text": "收留", "is_correct": false, "explanation": "语义：“收留”的对象是人或动物，与“捐书”的语境矛盾。"}, {"text": "逗", "is_correct": false, "explanation": "语义：“逗”指戏弄或逗乐，与“给山区小学捐书”的意思无关，句意不通。"}], "explanations": {"发动": "正确：“发动”指号召、发起某种活动，与“同学们给山区小学捐书”的语境相符。", "捐": "配价：“捐”的宾语要是财物，不能以“同学们”作宾语，句子不通。", "收留": "语义：“收留”的对象是人或动物，与“捐书”的语境矛盾。", "逗": "语义：“逗”指戏弄或逗乐，与“给山区小学捐书”的意思无关，句意不通。"}, "sentence_index": 0, "correct_answer": "发动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次地震发动了山体滑坡。", "explanation": "这里应该用〈引发〉。“发动”用于活动、运动或进攻，不能与“山体滑坡”这类灾害搭配。"}, {"text": "他发动了一把椅子。", "explanation": "这里应该用〈搬〉。“发动”用于机器、活动或进攻，不能用于椅子；挪动椅子要说“搬”。"}, {"text": "他在舞台上发动得很好。", "explanation": "这里应该用〈表演〉。“发动”不用于舞台上的表现，演得好要说“表演得很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发动", "is_correct": true, "explanation": "正确：“发动”指号召、发起活动，与“员工提出好办法”的语境相符。"}, {"text": "颁布", "is_correct": false, "explanation": "配价：“颁布”的宾语要是法规、命令等，不能以“员工”作宾语，句子不通。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：赶走员工后他们不会提出好办法，与句意矛盾。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：辞退员工后他们已经离开公司，不可能提出办法，与句意矛盾。"}], "explanations": {"发动": "正确：“发动”指号召、发起活动，与“员工提出好办法”的语境相符。", "颁布": "配价：“颁布”的宾语要是法规、命令等，不能以“员工”作宾语，句子不通。", "赶走": "语义：赶走员工后他们不会提出好办法，与句意矛盾。", "辞退": "语义：辞退员工后他们已经离开公司，不可能提出办法，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "发动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌发动了他的回忆。", "explanation": "这里应该用〈唤起〉。“发动”不能与“回忆”搭配，唤起回忆要说“唤起”。"}, {"text": "学校发动了新的目标。", "explanation": "这里应该用〈树立〉。“发动”不能与“目标”搭配，确定目标要说“树立”。"}, {"text": "他发动了那扇窗户。", "explanation": "这里应该用〈打开〉。“发动”用于机器、活动或进攻，窗户要说“打开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校发动得一次大型捐书活动。", "corrected_sentence": "学校发动了一次大型捐书活动。", "error_description": "错误形式：“发动得一次”；正确形式：“发动了一次”。表示动作已经完成要用动态助词“了”；“得”后面要接补语，不能直接接数量短语“一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "军方突然很发动了攻击。", "corrected_sentence": "军方突然发动了攻击。", "error_description": "错误形式：“很发动了攻击”；正确形式：“突然发动了攻击”。“很”只修饰形容词或状态词，不能修饰动作动词“发动”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
