INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85849, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“如何”是用来问怎么样或者怎么做的。", "primary_collocate": null, "pronunciation": "rú hé", "ipa": "ɻu˧˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "请问，这个字如何写？", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得这个办法如何？", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道如何回答他的问题。", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道如何去火车站。", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气如何？", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们如何学好汉语。", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜味道如何？", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能告诉我如何用这个手机吗？", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的学习成绩如何？", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在讨论如何保护环境。", "target_word": "如何", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "疑问代词，问方式或情况，相当于怎么、怎么样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df888c7e-00bf-4d04-9d58-c326ae2207d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85849, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如何", "is_correct": true, "explanation": "“如何写”询问写法，符合句意。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，句子问的是写法，不能说“这个字哪儿写”。"}, {"text": "什么", "is_correct": false, "explanation": "搭配：“什么”不能直接修饰“写”来问方式，“什么写”不成立。"}, {"text": "多少", "is_correct": false, "explanation": "搭配：“多少”问数量，不用来问写字的方式。"}], "explanations": {"如何": "“如何写”询问写法，符合句意。", "哪儿": "语义：“哪儿”问地点，句子问的是写法，不能说“这个字哪儿写”。", "什么": "搭配：“什么”不能直接修饰“写”来问方式，“什么写”不成立。", "多少": "搭配：“多少”问数量，不用来问写字的方式。"}, "sentence_index": 0, "correct_answer": "如何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你喜欢如何颜色？", "explanation": "这里应该用〈什么〉。如何问方式或状况，不能直接修饰名词“颜色”，问种类要用“什么”。"}, {"text": "他是如何的人？", "explanation": "这里应该用〈什么样〉。如何不能直接修饰名词，问性质要用“什么样的”。"}, {"text": "这个房间如何这么乱！", "explanation": "这里应该用〈怎么〉。如何只问方式或状况，表示程度的感叹要用“怎么”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如何", "is_correct": true, "explanation": "“味道如何”询问菜的好坏，符合句意。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，句中问的是菜的味道。"}, {"text": "几", "is_correct": false, "explanation": "搭配：“几”要带量词或问数量，不能直接修饰“味道”。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”问地点，与“味道”不搭。"}], "explanations": {"如何": "“味道如何”询问菜的好坏，符合句意。", "谁": "语义：“谁”问人，句中问的是菜的味道。", "几": "搭配：“几”要带量词或问数量，不能直接修饰“味道”。", "哪里": "语义：“哪里”问地点，与“味道”不搭。"}, "sentence_index": 6, "correct_answer": "如何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如何你不去，我就一个人去。", "explanation": "这里应该用〈如果〉。如何是问方式或状况的疑问词，不表示假设。"}, {"text": "我们如何要保护环境？", "explanation": "这里应该用〈为何〉。如何问方式或状况，不问理由。"}, {"text": "如何明天下雨，我们就取消比赛。", "explanation": "这里应该用〈要是〉。如何是问方式或状况的疑问词，不表示假设。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不清楚该怎么如何处理这件事。", "corrected_sentence": "我不清楚该如何处理这件事。", "error_description": "“如何”与“怎么”都是疑问词，不能叠用。错误形式是“怎么如何”，正确形式是只用“如何”：“该如何处理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个政策将如何影响我们吗？", "corrected_sentence": "这个政策将如何影响我们？", "error_description": "错误：“如何”已使句子成为特殊疑问句，句末不能再加“吗”（整句是非问中的“吗”不在此列）。去掉“吗”，正确形式为“这个政策将如何影响我们？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
