INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85851, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“为什么”是用来问原因的。", "primary_collocate": null, "pronunciation": "wèi shén me", "ipa": "weɪ˥˩ ʂən˧˥ mə", "syllable_count": 3, "sentences": [{"text": "你为什么今天没有来上课？", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为什么天空是蓝色的？", "target_word": "为什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不知道他为什么哭了。", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么不喝咖啡？", "target_word": "为什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他为什么总是迟到呢？", "target_word": "为什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请告诉我你为什么喜欢这里。", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为什么今天街上的人这么少？", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹问妈妈为什么要早点睡觉。", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么笑得这么开心？", "target_word": "为什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师问我们为什么昨天没做作业。", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "疑问代词，询问原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85851, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为什么", "is_correct": true, "explanation": "「为什么」用来问原因，与句意「没来上课的原因」吻合。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：「怎样」问方式或情况，不问原因，这里问的是没来的原因，不合。"}, {"text": "哪里", "is_correct": false, "explanation": "搭配：「哪里」作处所时要与「在」搭配，这里缺「在」，句子不成立。"}, {"text": "什么", "is_correct": false, "explanation": "搭配：「什么」问事物，不能充当状语说明原因，「你什么今天没有来」不成立。"}], "explanations": {"为什么": "「为什么」用来问原因，与句意「没来上课的原因」吻合。", "怎样": "语义：「怎样」问方式或情况，不问原因，这里问的是没来的原因，不合。", "哪里": "搭配：「哪里」作处所时要与「在」搭配，这里缺「在」，句子不成立。", "什么": "搭配：「什么」问事物，不能充当状语说明原因，「你什么今天没有来」不成立。"}, "sentence_index": 0, "correct_answer": "为什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜为什么做才好吃？", "explanation": "这里应该用〈怎么〉。问做法要用「怎么」，「为什么」问原因，这句问的是做法，不是原因。"}, {"text": "这个问题为什么解才对？", "explanation": "这里应该用〈怎样〉。问解法要用「怎样」，「为什么」只问原因，不能修饰「解才对」。"}, {"text": "这台机器为什么用才安全？", "explanation": "这里应该用〈怎么〉。问使用方法要用「怎么」，「为什么」只问原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为什么", "is_correct": true, "explanation": "「为什么」用来问原因，与句意「街上人少的原因」吻合。"}, {"text": "谁", "is_correct": false, "explanation": "语义：「谁」问人，不问原因，这里问的是街上人少的原因。"}, {"text": "多少", "is_correct": false, "explanation": "搭配：「多少」问数量，后面要接名词或量词，不能直接接「今天街上的人」作原因。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：「哪儿」问处所，句子问的是人少的原因，不问地点。"}], "explanations": {"为什么": "「为什么」用来问原因，与句意「街上人少的原因」吻合。", "谁": "语义：「谁」问人，不问原因，这里问的是街上人少的原因。", "多少": "搭配：「多少」问数量，后面要接名词或量词，不能直接接「今天街上的人」作原因。", "哪儿": "语义：「哪儿」问处所，句子问的是人少的原因，不问地点。"}, "sentence_index": 6, "correct_answer": "为什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你在为什么地方工作？", "explanation": "这里应该用〈哪儿〉。问处所要用「哪儿」或「什么地方」，「为什么」只问原因，不能修饰「地方」。"}, {"text": "你最喜欢为什么颜色？", "explanation": "这里应该用〈什么〉。问颜色要用「什么」，「为什么」只问原因，不能用来问颜色。"}, {"text": "这个班有为什么同学？", "explanation": "这里应该用〈多少〉。问人数要用「多少」或「几」，「为什么」只问原因，不能表示同学的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你为什么的没来上课？", "corrected_sentence": "你为什么没来上课？", "error_description": "错误在「为什么的」：「为什么」后面不能直接加「的」。正确说法是「你为什么没来上课」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为什么了这么生气？", "corrected_sentence": "他为什么这么生气？", "error_description": "错误在「为什么了」：「为什么」是疑问词，后面不能直接加「了」。正确说法是「他为什么这么生气」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
