INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85852, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问原因或目的。", "primary_collocate": null, "pronunciation": "wèi shén me", "ipa": "weɪ˥˩ ʂən˧˥ mə", "syllable_count": 3, "sentences": [{"text": "你为什么学中文？", "target_word": "为什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他为什么要去北京？", "target_word": "为什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们为什么买这么多水果？", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为什么要带伞？外面没下雨。", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸为什么每天早上跑步？", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为什么给我打电话？", "target_word": "为什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们为什么要坐火车去？", "target_word": "为什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你为什么穿着这么厚的衣服？", "target_word": "为什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为什么没告诉你这件事？", "target_word": "为什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板为什么让大家今天早点回家？", "target_word": "为什么", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "疑问代词，询问做事的原因或目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为什么", "is_correct": true, "explanation": "「为什么」用来问原因，与句意「学中文的原因」吻合。"}, {"text": "几", "is_correct": false, "explanation": "搭配：「几」问数量，后面要接量词，不能直接修饰动词「学」，「你几学中文」不成立。"}, {"text": "哪里", "is_correct": false, "explanation": "搭配：「哪里」作处所时要与「在」搭配，这里缺「在」，句子不成立。"}, {"text": "什么", "is_correct": false, "explanation": "搭配：「什么」问事物，不能充当状语说明原因，「你什么学中文」不成立。"}], "explanations": {"为什么": "「为什么」用来问原因，与句意「学中文的原因」吻合。", "几": "搭配：「几」问数量，后面要接量词，不能直接修饰动词「学」，「你几学中文」不成立。", "哪里": "搭配：「哪里」作处所时要与「在」搭配，这里缺「在」，句子不成立。", "什么": "搭配：「什么」问事物，不能充当状语说明原因，「你什么学中文」不成立。"}, "sentence_index": 0, "correct_answer": "为什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜为什么做才好吃？", "explanation": "这里应该用〈怎么〉。问做法要用「怎么」，「为什么」问原因，这句问的是做法，不是原因。"}, {"text": "这个问题为什么解才对？", "explanation": "这里应该用〈怎样〉。问解法要用「怎样」，「为什么」只问原因，不能修饰「解才对」。"}, {"text": "这台机器为什么用才安全？", "explanation": "这里应该用〈怎么〉。问使用方法要用「怎么」，「为什么」只问原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为什么", "is_correct": true, "explanation": "「为什么」用来问原因，与句意「我们要坐火车去的原因」吻合。"}, {"text": "谁", "is_correct": false, "explanation": "语义：「谁」问人，不问原因，句子问的是为什么要坐火车去。"}, {"text": "多少", "is_correct": false, "explanation": "搭配：「多少」问数量，后面要接名词或量词，不能直接接动词「要坐」。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：「怎样」问方式，这里问的是去的原因，不是怎样去。"}], "explanations": {"为什么": "「为什么」用来问原因，与句意「我们要坐火车去的原因」吻合。", "谁": "语义：「谁」问人，不问原因，句子问的是为什么要坐火车去。", "多少": "搭配：「多少」问数量，后面要接名词或量词，不能直接接动词「要坐」。", "怎样": "语义：「怎样」问方式，这里问的是去的原因，不是怎样去。"}, "sentence_index": 6, "correct_answer": "为什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你在为什么地方工作？", "explanation": "这里应该用〈哪儿〉。问处所要用「哪儿」或「什么地方」，「为什么」只问原因，不能修饰「地方」。"}, {"text": "你最喜欢为什么颜色？", "explanation": "这里应该用〈什么〉。问颜色要用「什么」，「为什么」只问原因，不能用来问颜色。"}, {"text": "这个班有为什么同学？", "explanation": "这里应该用〈多少〉。问人数要用「多少」或「几」，「为什么」只问原因，不能表示同学的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你为什么地喜欢中国菜？", "corrected_sentence": "你为什么喜欢中国菜？", "error_description": "错误在「为什么地」：「为什么」后面不能直接加「地」，「地」只用于修饰动词。正确说法是「你为什么喜欢中国菜」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为什么的没跟我说？", "corrected_sentence": "他为什么没跟我说？", "error_description": "错误在「为什么的」：「为什么」后面不能直接加「的」。正确说法是「他为什么没跟我说」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
