INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "风格是一个人做事或画画写字时，特有的样子。", "primary_collocate": null, "pronunciation": "fēng gé", "ipa": "fɤŋ˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他做事的风格很认真。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢老师讲课的风格。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的工作风格很严格，大家都怕他。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写字的风格很漂亮，一看就知道是她写的。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人画画的风格一直没变。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人做饭的风格都不同。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车的风格很稳，从不急刹车。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不习惯他开会的风格。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师教书的风格很有意思。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸做饭的风格是简单又快。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "風格", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人做事或写画时特有的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef0daaba-e68b-4c3c-a684-5319cdf29e05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风格", "is_correct": true, "explanation": "“风格”指做事时特有的样子，与句意相合。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”指快慢，不能说“做事的速度很认真”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，与做事的样子无关。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的身体特征，不能用来说做事的样子。"}], "explanations": {"风格": "“风格”指做事时特有的样子，与句意相合。", "速度": "搭配：“速度”指快慢，不能说“做事的速度很认真”。", "颜色": "语义：“颜色”指色彩，与做事的样子无关。", "身高": "体貌：“身高”是人的身体特征，不能用来说做事的样子。"}, "sentence_index": 0, "correct_answer": "风格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爷爷的风格很瘦，身上几乎没有肉。", "explanation": "这里应该用〈体形〉。瘦形容身材，“风格”指做事或写画时特有的样子，不能用来形容身材。"}, {"text": "这条河的风格很清，能看见底下的鱼。", "explanation": "这里应该用〈水质〉。清形容水的干净，“风格”指做事或写画时特有的样子，不能用来说水的状况。"}, {"text": "这朵花的风格很香，屋子里都是它的味道。", "explanation": "这里应该用〈气味〉。香形容气味，“风格”指做事或写画时特有的样子，不能用来说花的气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风格", "is_correct": true, "explanation": "“风格”指做事时特有的样子，与句意相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”指商品的金额，不能用来说开车的样子。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的身材，不能用来说开车的样子。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指活了多少岁，不能用“很稳”来形容，也与开车的样子无关。"}], "explanations": {"风格": "“风格”指做事时特有的样子，与句意相合。", "价格": "搭配：“价格”指商品的金额，不能用来说开车的样子。", "身高": "体貌：“身高”是人的身材，不能用来说开车的样子。", "年龄": "语义：“年龄”指活了多少岁，不能用“很稳”来形容，也与开车的样子无关。"}, "sentence_index": 6, "correct_answer": "风格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个女孩的风格很高大，力气也很大。", "explanation": "这里应该用〈体形〉。高大形容身材，“风格”指做事或写画时特有的样子，不能用来形容身材。"}, {"text": "那只猫的风格很凶，谁也不敢摸。", "explanation": "这里应该用〈脾气〉。凶形容性情，“风格”不指猫的性情。"}, {"text": "这锅粥的风格很甜。", "explanation": "这里应该用〈味道〉。甜形容食物的味道，“风格”不指味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做事有一条独特的风格。", "corrected_sentence": "他做事有一种独特的风格。", "error_description": "“风格”的量词要用“种”，不能用“条”。“条”用于长而细的东西，不能用于风格，应说“一种独特的风格”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她做事地风格很利落。", "corrected_sentence": "她做事的风格很利落。", "error_description": "“的”误写成“地”。“地”用来修饰动词，这里“做事”是修饰“风格”的定语，要用“的”，应说“做事的风格”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
