INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "艺术作品或人的言行中表现出来的主要特色。", "primary_collocate": null, "pronunciation": "fēng gé", "ipa": "fɤŋ˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这位画家的作品风格很特别。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子的风格像古代的宫殿。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢听风格轻松的音乐。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位雕塑家的创作风格很独特。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书的写作风格不一样。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手的唱歌风格很有个性。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人的说话风格很幽默。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的风格很像中国的老电影。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的诗风格自然，没有难懂的词。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的建筑风格有很多种。", "target_word": "风格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "風格", "label": "繁体"}], "register": "中性", "sense_fingerprint": "作品或事物表现出来的主要特色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef0daaba-e68b-4c3c-a684-5319cdf29e05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风格", "is_correct": true, "explanation": "“风格”指作品表现出的主要特色，与“作品……很特别”相合。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”说人或动物活了多久，不能用来形容作品。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身材，不能用来形容作品。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，与作品的特点无关。"}], "explanations": {"风格": "“风格”指作品表现出的主要特色，与“作品……很特别”相合。", "年龄": "搭配：“年龄”说人或动物活了多久，不能用来形容作品。", "身高": "体貌：“身高”指人的身材，不能用来形容作品。", "脾气": "语义：“脾气”指人的性情，与作品的特点无关。"}, "sentence_index": 0, "correct_answer": "风格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妹妹的风格很矮，只到我的肩膀。", "explanation": "这里应该用〈身高〉。矮说的是身材，“风格”指作品或人的言行特色，不能用来说身高。"}, {"text": "这间屋子的风格有三十多平方米。", "explanation": "这里应该用〈面积〉。“风格”指作品或人的言行特色，不能用来说屋子有多大的面积。"}, {"text": "这个西瓜的风格很甜。", "explanation": "这里应该用〈味道〉。甜形容食物的味道，“风格”指作品或人的言行特色，不指味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风格", "is_correct": true, "explanation": "“风格”指说话时特有的表达方式，与句意相合。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“声音”指发出的声响，不能说“说话声音很幽默”。"}, {"text": "体形", "is_correct": false, "explanation": "体貌：“体形”指身材，不能用来形容说话的方式。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不是说话时的表达方式。"}], "explanations": {"风格": "“风格”指说话时特有的表达方式，与句意相合。", "声音": "搭配：“声音”指发出的声响，不能说“说话声音很幽默”。", "体形": "体貌：“体形”指身材，不能用来形容说话的方式。", "脾气": "语义：“脾气”指性情，不是说话时的表达方式。"}, "sentence_index": 6, "correct_answer": "风格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个男孩的风格很结实，常常打篮球。", "explanation": "这里应该用〈体形〉。结实形容身体强壮，“风格”不用来描述身体。"}, {"text": "那只小狗的风格很凶，谁也不敢摸。", "explanation": "这里应该用〈脾气〉。凶形容性情暴烈，“风格”指作品或人的言行特色，不指小狗的性情。"}, {"text": "这碗汤的风格很咸。", "explanation": "这里应该用〈味道〉。咸形容食物的味道，“风格”不指味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家有一条朴素的风格。", "corrected_sentence": "这位作家有一种朴素的风格。", "error_description": "“风格”的量词要用“种”，不能用“条”。“条”用于长而细的东西，不能用于风格，应说“一种朴素的风格”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位导演讲课地风格很幽默。", "corrected_sentence": "这位导演讲课的风格很幽默。", "error_description": "“的”误写成“地”。“地”用来修饰动词，这里“讲课”是修饰“风格”的定语，要用“的”，应说“讲课的风格”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
