INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“还是”是在两样东西里问你要哪一样。", "primary_collocate": null, "pronunciation": "hái shi", "ipa": "xaɪ̯˧˥ ʂɻ̩", "syllable_count": 2, "sentences": [{"text": "你喝茶还是喝咖啡？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐地铁还是坐公共汽车去？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是老师还是学生？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想吃米饭还是面条？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天去还是后天去，你决定吧。", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末你在家还是出去玩？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件是红的还是蓝的？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢猫还是喜欢狗？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天看电影还是去公园？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用手机付钱还是用现金？", "target_word": "还是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "连词，用于选择疑问句，A还是B？让人二选一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df888c7e-00bf-4d04-9d58-c326ae2207d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "还是", "is_correct": true, "explanation": "正确答案。hái shi 是表示二选一的连词，意思是在两者之间选择。"}, {"text": "孩子", "is_correct": false, "explanation": "hái 相同，但 shi 与 zi 声母不同，意思是孩子。"}, {"text": "海事", "is_correct": false, "explanation": "hǎi（第三声）与 hái（第二声）声调不同，意思是海上事务。"}, {"text": "海狮", "is_correct": false, "explanation": "hǎi 与 hái 声调不同，shī 与 shi 声调也不同，意思是海狮。"}], "explanations": {"还是": "正确答案。hái shi 是表示二选一的连词，意思是在两者之间选择。", "孩子": "hái 相同，但 shi 与 zi 声母不同，意思是孩子。", "海事": "hǎi（第三声）与 hái（第二声）声调不同，意思是海上事务。", "海狮": "hǎi 与 hái 声调不同，shī 与 shi 声调也不同，意思是海狮。"}, "sentence_index": null, "correct_answer": "还是"}, "level_3": {"options": [{"text": "还是", "is_correct": true, "explanation": "连词“还是”表示二选一，符合选择问句的句意。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表原因，与二选一的问句不符。"}, {"text": "但是", "is_correct": false, "explanation": "搭配：“但是”要连接转折的分句，前面没有对立内容，不能用于选择问句。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表结果，与选择问句的句意不符。"}], "explanations": {"还是": "连词“还是”表示二选一，符合选择问句的句意。", "因为": "语义：“因为”表原因，与二选一的问句不符。", "但是": "搭配：“但是”要连接转折的分句，前面没有对立内容，不能用于选择问句。", "所以": "语义：“所以”表结果，与选择问句的句意不符。"}, "sentence_index": 0, "correct_answer": "还是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你可以坐地铁还是坐公共汽车去。", "explanation": "这里应该用〈或者〉。这是陈述句，说明可以有的选择，不是请对方选择的问句，要用“或者”。"}, {"text": "这个苹果比那个还是甜。", "explanation": "这里应该用〈更〉。还是不表示程度的进一步加深；比较句中表示“更加”要用“更”。"}, {"text": "我们需要苹果、香蕉还是橘子。", "explanation": "这里应该用〈或者〉。还是用于问句请对方选择，陈述句列举可能时要用或者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还是", "is_correct": true, "explanation": "连词“还是”表示二选一，符合句意。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表让步，后面要接转折分句，句意不符。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，不能连接选择问句中的两个选项。"}, {"text": "不然", "is_correct": false, "explanation": "语义：“不然”表示否则，此处没有假设条件。"}], "explanations": {"还是": "连词“还是”表示二选一，符合句意。", "虽然": "语义：“虽然”表让步，后面要接转折分句，句意不符。", "然而": "语义：“然而”表示转折，不能连接选择问句中的两个选项。", "不然": "语义：“不然”表示否则，此处没有假设条件。"}, "sentence_index": 6, "correct_answer": "还是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑比那台还是快。", "explanation": "这里应该用〈更〉。还是不表示程度的进一步加深；比较句中要用“更”。"}, {"text": "他喜欢红的、蓝的还是绿的。", "explanation": "这里应该用〈或者〉。还是用于问句请对方选择，陈述句列举喜好时要用或者。"}, {"text": "我用手机付钱还是用现金。", "explanation": "这里应该用〈或者〉。“还是”在陈述句中一般只见于“X还是Y都行”之类固定格式，此句没有这类格式，应改为“或者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下班以后你是回家或者还是去健身房？", "corrected_sentence": "下班以后你是回家还是去健身房？", "error_description": "多加了连词“或者”，与“还是”叠用。选择问句只用“还是”，应去掉“或者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次出差你坐飞机还是坐火车吗？", "corrected_sentence": "这次出差你坐飞机还是坐火车？", "error_description": "用“还是”的选择问句本身已是问句，句末不能再加“吗”。应去掉“吗”：“你坐飞机还是坐火车？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '114dd942-fece-4863-8a0c-da61251528cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85857, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "“不同”与“一样”意思相反，都指两者有无差别。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容整洁，与“一样”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容没有声音或不吵闹，与“一样”无关。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容智力，与“一样”没有对应的反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "“不同”与“一样”意思相反，都指两者有无差别。", "干净": "“干净”形容整洁，与“一样”没有反义关系。", "安静": "“安静”形容没有声音或不吵闹，与“一样”无关。", "聪明": "“聪明”形容智力，与“一样”没有对应的反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85857, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "“不同”与“一样”意思相反，都指两者有无差别。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”形容价钱低，与“一样”没有反义关系。"}, {"text": "麻烦", "is_correct": false, "explanation": "“麻烦”形容事情费事，与“一样”无关。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜艳，与“一样”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "“不同”与“一样”意思相反，都指两者有无差别。", "便宜": "“便宜”形容价钱低，与“一样”没有反义关系。", "麻烦": "“麻烦”形容事情费事，与“一样”无关。", "明亮": "“明亮”形容光线充足或颜色鲜艳，与“一样”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85857, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“一样”是说两个东西没有不同。", "primary_collocate": null, "pronunciation": "yí yàng", "ipa": "i˧˥ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这两本书的颜色一样。", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我和姐姐的手机一样。", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们俩的名字一样，但是人不一样。", "target_word": "一样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服和那件一样大。", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的想法和我的一样吗？", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天的菜和昨天的一样好吃。", "target_word": "一样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个杯子看起来一样。", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥的个子跟爸爸一样高。", "target_word": "一样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的价钱跟那家一样。", "target_word": "一样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的作业一样，都是写十个字。", "target_word": "一样", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不一样", "label": "否定式"}, {"form": "一模一样", "label": "复合"}], "register": "口语", "sense_fingerprint": "形容词，两个事物比较后没有差别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一样", "is_correct": true, "explanation": "正确答案。“一样”读作 yí yàng，表示两者没有差别。"}, {"text": "异样", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，“异样”意思是与众不同，不是“相同”。"}, {"text": "一向", "is_correct": false, "explanation": "xiàng 与 yàng 声母不同，声调相同，“一向”意思是一直、向来。"}, {"text": "一望", "is_correct": false, "explanation": "wàng 与 yàng 声母不同，声调相同，“一望”意思是看一眼。"}], "explanations": {"一样": "正确答案。“一样”读作 yí yàng，表示两者没有差别。", "异样": "yì（第四声）与 yí（第二声）声调不同，“异样”意思是与众不同，不是“相同”。", "一向": "xiàng 与 yàng 声母不同，声调相同，“一向”意思是一直、向来。", "一望": "wàng 与 yàng 声母不同，声调相同，“一望”意思是看一眼。"}, "sentence_index": null, "correct_answer": "一样"}, "level_3": {"options": [{"text": "一样", "is_correct": true, "explanation": "“一样”表示两本书的颜色没有差别，符合句意。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度，颜色不能说高矮。"}, {"text": "长", "is_correct": false, "explanation": "语义：“长”说长短，与颜色的异同无关。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”只形容人或动物的体形，不用于书本的颜色。"}], "explanations": {"一样": "“一样”表示两本书的颜色没有差别，符合句意。", "高": "搭配：“高”说高度，颜色不能说高矮。", "长": "语义：“长”说长短，与颜色的异同无关。", "胖": "体貌：“胖”只形容人或动物的体形，不用于书本的颜色。"}, "sentence_index": 0, "correct_answer": "一样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆的菜我觉得很一样，不值得再去。", "explanation": "这里应该用〈一般〉。“一样”只表示没有差别，不表示“不好不坏、平平”；评价菜品平平要用“一般”。"}, {"text": "他们俩的看法很一样，所以天天吵架。", "explanation": "这里应该用〈相反〉。“一样”表示没有差别，看法一致不会天天吵架；说两人的看法对立要用“相反”。"}, {"text": "这两个孩子的身高一样，哥哥却比弟弟矮十厘米。", "explanation": "这里应该用〈不同〉。“一样”说没有差别，后半句说哥哥比弟弟矮十厘米，两人身高不同，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85857, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一样", "is_correct": true, "explanation": "正确答案。“一样”读作 yí yàng，表示两者没有差别。"}, {"text": "遗殃", "is_correct": false, "explanation": "yāng（第一声）与 yàng（第四声）声调不同，“遗殃”意思是留下的祸害。"}, {"text": "颐养", "is_correct": false, "explanation": "yǎng（第三声）与 yàng（第四声）声调不同，“颐养”意思是保养身体。"}, {"text": "依样", "is_correct": false, "explanation": "yī（第一声）与 yí（第二声）声调不同，“依样”意思是照着原来的样子。"}], "explanations": {"一样": "正确答案。“一样”读作 yí yàng，表示两者没有差别。", "遗殃": "yāng（第一声）与 yàng（第四声）声调不同，“遗殃”意思是留下的祸害。", "颐养": "yǎng（第三声）与 yàng（第四声）声调不同，“颐养”意思是保养身体。", "依样": "yī（第一声）与 yí（第二声）声调不同，“依样”意思是照着原来的样子。"}, "sentence_index": null, "correct_answer": "一样"}, "level_3": {"options": [{"text": "一样", "is_correct": true, "explanation": "“一样”表示两个杯子看起来没有差别，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：杯子不会聪明，“聪明”只形容人的智力。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”是人的情绪，杯子不能害羞。"}, {"text": "年轻", "is_correct": false, "explanation": "体貌：“年轻”形容人的年龄和外貌，不用于描述杯子。"}], "explanations": {"一样": "“一样”表示两个杯子看起来没有差别，符合句意。", "聪明": "语义：杯子不会聪明，“聪明”只形容人的智力。", "害羞": "语义：“害羞”是人的情绪，杯子不能害羞。", "年轻": "体貌：“年轻”形容人的年龄和外貌，不用于描述杯子。"}, "sentence_index": 6, "correct_answer": "一样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两双鞋很一样，我们却觉得差别很远。", "explanation": "这里应该用〈不同〉。“一样”说没有差别，说两者有差别要用“不同”；这句既说“一样”又说“差别很远”，自相矛盾。"}, {"text": "这家店的衣服很一样，没什么特色。", "explanation": "这里应该用〈普通〉。“一样”只表示相同，不表示平常、没有特色；形容东西平庸时要用“普通”。"}, {"text": "我们俩的成绩很一样，可他比我高出四十分。", "explanation": "这里应该用〈悬殊〉。“一样”说完全相同，成绩相差很大时要用“悬殊”或直接说差距。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他比我一样高。", "corrected_sentence": "他跟我一样高。", "error_description": "错误在于“比”不能与“一样”搭配。表示与某人相同要用“跟/和……一样”，应说“他跟我一样高”，不说“他比我一样高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的作业他的一样。", "corrected_sentence": "我的作业跟他的一样。", "error_description": "错误在于漏掉了“跟”。表示与某人相同要用“跟……一样”，应说“我的作业跟他的一样”，不说“我的作业他的一样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
