INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85858, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，表示相同，没有差别。", "primary_collocate": null, "pronunciation": "yí yàng", "ipa": "i˧˥ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这里的房子都一样，很难找到我家。", "target_word": "一样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个孩子长得一样。", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们的意见完全一样。", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们俩的爱好一样，都喜欢打篮球。", "target_word": "一样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双胞胎的声音几乎一样。", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些杯子的样子都一样。", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们的答案一样吗？", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们俩的生日一样，都是五月一号。", "target_word": "一样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "无论大人小孩，在法律面前都一样。", "target_word": "一样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买的鞋和你买的一样，真巧。", "target_word": "一样", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不一样", "label": "否定式"}, {"form": "一模一样", "label": "复合"}], "register": "口语", "sense_fingerprint": "形容词，表示相同、没有差别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一样", "is_correct": true, "explanation": "正确答案。“一样”读作 yí yàng，表示两者没有差别。"}, {"text": "异样", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，“异样”意思是与众不同，不是“相同”。"}, {"text": "一向", "is_correct": false, "explanation": "xiàng 与 yàng 声母不同，声调相同，“一向”意思是一直、向来。"}, {"text": "一望", "is_correct": false, "explanation": "wàng 与 yàng 声母不同，声调相同，“一望”意思是看一眼。"}], "explanations": {"一样": "正确答案。“一样”读作 yí yàng，表示两者没有差别。", "异样": "yì（第四声）与 yí（第二声）声调不同，“异样”意思是与众不同，不是“相同”。", "一向": "xiàng 与 yàng 声母不同，声调相同，“一向”意思是一直、向来。", "一望": "wàng 与 yàng 声母不同，声调相同，“一望”意思是看一眼。"}, "sentence_index": null, "correct_answer": "一样"}, "level_3": {"options": [{"text": "一样", "is_correct": true, "explanation": "“一样”表示房子没有差别，所以难以分辨我家，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：房子不会聪明，“聪明”只形容人的智力。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”是人的情绪，房子不能害羞。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不用于房子。"}], "explanations": {"一样": "“一样”表示房子没有差别，所以难以分辨我家，符合句意。", "聪明": "语义：房子不会聪明，“聪明”只形容人的智力。", "害羞": "语义：“害羞”是人的情绪，房子不能害羞。", "胖": "体貌：“胖”形容人或动物的体形，不用于房子。"}, "sentence_index": 0, "correct_answer": "一样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们的做法很一样，却总是互相反对。", "explanation": "这里应该用〈对立〉。“一样”表示没有差别，两人互相反对说明做法对立，要用“对立”。"}, {"text": "我们班的同学都一样，每个人都很有个性。", "explanation": "这里应该用〈不同〉。“一样”强调没有差别，后半句强调每人有个性，应说“都不同”。"}, {"text": "这些练习我觉得很一样，没什么意思。", "explanation": "这里应该用〈一般〉。“一样”只表示相同，不表示“平常、没意思”；评价练习平平要用“一般”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85858, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一样", "is_correct": true, "explanation": "正确答案。“一样”读作 yí yàng，表示两者没有差别。"}, {"text": "遗殃", "is_correct": false, "explanation": "yāng（第一声）与 yàng（第四声）声调不同，“遗殃”意思是留下的祸害。"}, {"text": "颐养", "is_correct": false, "explanation": "yǎng（第三声）与 yàng（第四声）声调不同，“颐养”意思是保养身体。"}, {"text": "依样", "is_correct": false, "explanation": "yī（第一声）与 yí（第二声）声调不同，“依样”意思是照着原来的样子。"}], "explanations": {"一样": "正确答案。“一样”读作 yí yàng，表示两者没有差别。", "遗殃": "yāng（第一声）与 yàng（第四声）声调不同，“遗殃”意思是留下的祸害。", "颐养": "yǎng（第三声）与 yàng（第四声）声调不同，“颐养”意思是保养身体。", "依样": "yī（第一声）与 yí（第二声）声调不同，“依样”意思是照着原来的样子。"}, "sentence_index": null, "correct_answer": "一样"}, "level_3": {"options": [{"text": "一样", "is_correct": true, "explanation": "“一样”表示答案完全相同，符合问句的意思。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容人的心情，答案不能高兴。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的体形，不用于答案。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”形容人的性格或习惯，答案不能懒。"}], "explanations": {"一样": "“一样”表示答案完全相同，符合问句的意思。", "高兴": "语义：“高兴”形容人的心情，答案不能高兴。", "瘦": "体貌：“瘦”形容人或动物的体形，不用于答案。", "懒": "语义：“懒”形容人的性格或习惯，答案不能懒。"}, "sentence_index": 6, "correct_answer": "一样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两本书的内容很一样，但我们觉得差别很大。", "explanation": "这里应该用〈不同〉。“一样”说没有差别，差别很大时要用“不同”；这句前后矛盾。"}, {"text": "这间屋子的装修很一样，大家都觉得无聊。", "explanation": "这里应该用〈普通〉。“一样”不表示平常、没有特色，形容装修平庸时要用“普通”。"}, {"text": "我的分数和你的一样，可你比我高出四十分。", "explanation": "这里应该用〈不同〉。“一样”说完全相同，你比我高四十分说明分数不同，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的字比我的一样好看。", "corrected_sentence": "他的字跟我的一样好看。", "error_description": "错误在于“比”不能与“一样”搭配。表示与别人相同要用“跟/和……一样”，应说“他的字跟我的一样好看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跑得我一样快。", "corrected_sentence": "他跑得跟我一样快。", "error_description": "错误在于缺少比较介词“跟”。“一样”要与“跟/和……”连用，应说“他跑得跟我一样快”，不说“他跑得我一样快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
