INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85859, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示否定判断，意思是“并不是”，多用于纠正对方的误解。", "primary_collocate": null, "pronunciation": "bìng fēi", "ipa": "piŋ˥˩ fei˥", "syllable_count": 2, "sentences": [{"text": "这并非他一个人的错。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "成功并非靠运气。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "并非所有人都喜欢吃辣。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事并非你想的那样。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他并非不想去，只是没时间。", "target_word": "并非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "贵的东西并非都是好东西。", "target_word": "并非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好中文并非很难。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他今天没来，并非因为生病。", "target_word": "并非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这并非我第一次来北京。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "并非每个孩子都爱看书。", "target_word": "并非", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "並非", "label": "繁体"}], "register": "书面", "sense_fingerprint": "并非：否定判断，纠正误会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '537c4520-879d-4465-a1a7-51ade1e4b38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDE