INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "并非", "is_correct": true, "explanation": "并非：表示否定判断，纠正误会，这里指“不是他一个人的错”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示得到愉快，与“错”不合。"}, {"text": "犯下", "is_correct": false, "explanation": "配价：“犯下”要求人作施事，“这”不能作主语去犯错。"}, {"text": "赢得", "is_correct": false, "explanation": "语义：“赢得”指取得胜利或好评，与“错”不合。"}], "explanations": {"并非": "并非：表示否定判断，纠正误会，这里指“不是他一个人的错”。", "享受": "语义：“享受”表示得到愉快，与“错”不合。", "犯下": "配价：“犯下”要求人作施事，“这”不能作主语去犯错。", "赢得": "语义：“赢得”指取得胜利或好评，与“错”不合。"}, "sentence_index": 0, "correct_answer": "并非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我并非去过北京，所以不熟悉那里。", "explanation": "这里应该用〈没〉。“并非”用于否定判断，不用于否定动作或经历。"}, {"text": "我并非会游泳，所以不去海边。", "explanation": "这里应该用〈不〉。“并非”不与“会”这类能愿动词连用。"}, {"text": "他并非抽烟，所以身体很好。", "explanation": "这里应该用〈不〉。“并非”不能用来否定“抽烟”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
