INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85861, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "“其中”是说在刚才说的那些东西里面。", "primary_collocate": null, "pronunciation": "qí zhōng", "ipa": "tɕʰi˧˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "我们班有二十人，其中十人是女生。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了很多水果，其中苹果最好吃。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去过三个国家，其中中国最有意思。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有五本书，其中两本是新的。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有很多菜，其中鱼很有名。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学过两种语言，其中一种是汉语。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了十封信，其中三封没寄。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有很多花，其中红花最多。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去了四个城市，其中北京最大。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她养了三只猫，其中一只是白色的。", "target_word": "其中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指刚才提到的那些人或事物之中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa09a39c-1dc4-4f09-8ce9-0310badb768d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85861, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "其中", "is_correct": true, "explanation": "正确答案：其中（qí zhōng），指所说的范围之中。"}, {"text": "期中", "is_correct": false, "explanation": "qī zhōng 与 qí zhōng 第一个音节声调不同，意思是“学期中间”。"}, {"text": "集中", "is_correct": false, "explanation": "jí zhōng 与 qí zhōng 第一个音节声母不同（j 与 q），意思是“集中”。"}, {"text": "起重", "is_correct": false, "explanation": "qǐ zhòng 与 qí zhōng 两个音节声调都不同，意思是“起吊重物”。"}, {"text": "七种", "is_correct": false, "explanation": "qī zhǒng 与 qí zhōng 两个音节声调都不同，意思是“七类”。"}], "explanations": {"其中": "正确答案：其中（qí zhōng），指所说的范围之中。", "期中": "qī zhōng 与 qí zhōng 第一个音节声调不同，意思是“学期中间”。", "集中": "jí zhōng 与 qí zhōng 第一个音节声母不同（j 与 q），意思是“集中”。", "起重": "qǐ zhòng 与 qí zhōng 两个音节声调都不同，意思是“起吊重物”。", "七种": "qī zhǒng 与 qí zhōng 两个音节声调都不同，意思是“七类”。"}, "sentence_index": null, "correct_answer": "其中"}, "level_3": {"options": [{"text": "其中", "is_correct": true, "explanation": "正确答案：“其中”指二十人之中，与“十人是女生”搭配自然。"}, {"text": "以外", "is_correct": false, "explanation": "语义：“以外”指范围之外，“以外十人是女生”与前文二十人的范围矛盾。"}, {"text": "以内", "is_correct": false, "explanation": "语义：“以内”指界限之内，不指群体中的一部分，与前文数量不符。"}, {"text": "之后", "is_correct": false, "explanation": "搭配：“之后”接时间或事件，不接人数范围。"}], "explanations": {"其中": "正确答案：“其中”指二十人之中，与“十人是女生”搭配自然。", "以外": "语义：“以外”指范围之外，“以外十人是女生”与前文二十人的范围矛盾。", "以内": "语义：“以内”指界限之内，不指群体中的一部分，与前文数量不符。", "之后": "搭配：“之后”接时间或事件，不接人数范围。"}, "sentence_index": 0, "correct_answer": "其中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在写作业，其中妈妈在做饭。", "explanation": "这里应该用〈同时〉。“其中”指所说范围之内的部分，表示两件事同时发生不能用“其中”。"}, {"text": "我们今天要做很多事，其中明天还要去上班。", "explanation": "这里应该用〈另外〉。“其中”指“今天要做的事”之中的一部分，“明天要上班”不属于这个范围。"}, {"text": "我买了一只狗，其中很可爱。", "explanation": "这里应该用〈它〉。“其中”指多个成员中的一部分，只有一只狗时指代它应用“它”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其中", "is_correct": true, "explanation": "正确答案：“其中”指十封信之中的一部分，与“三封没寄”搭配自然。"}, {"text": "之外", "is_correct": false, "explanation": "语义：“之外”指范围以外，“之外三封没寄”与前文十封信的范围矛盾。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“之前”指时间上的先后，不指信件中的一部分。"}, {"text": "以下", "is_correct": false, "explanation": "搭配：“以下”多用于数量界限或段落之后，不接“十封信”中的部分。"}], "explanations": {"其中": "正确答案：“其中”指十封信之中的一部分，与“三封没寄”搭配自然。", "之外": "语义：“之外”指范围以外，“之外三封没寄”与前文十封信的范围矛盾。", "之前": "语义：“之前”指时间上的先后，不指信件中的一部分。", "以下": "搭配：“以下”多用于数量界限或段落之后，不接“十封信”中的部分。"}, "sentence_index": 6, "correct_answer": "其中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她养了三只猫，其中之外还有一只狗。", "explanation": "这里应该用〈此外〉。“其中”指范围之内的部分，补充范围之外的事物要用“此外”。"}, {"text": "她养了一只猫，其中一只是白色的。", "explanation": "这里应该用〈这只〉。“其中”要求前文有多个成员组成的范围，只有一只猫时指代它应用“这只”。"}, {"text": "她养了三只猫，其中，她在学习英语。", "explanation": "这里应该用〈同时〉。“其中”指范围之内的部分，不能表示两件事同时进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个班有三十名学生，其中一是男生。", "corrected_sentence": "这个班有三十名学生，其中一个是男生。", "error_description": "错误形式：“其中一是男生”。正确形式：“其中一个是男生”。“一”作数词修饰“其中”所指的成员时需要量词“个”，漏掉后不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区有很多车，其中黑色的其中最多。", "corrected_sentence": "这个小区有很多车，其中黑色的最多。", "error_description": "错误形式：“其中黑色的其中最多”。正确形式：“其中黑色的最多”。“其中”只需出现一次，句中重复使用是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
