, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其中", "is_correct": true, "explanation": "正确答案：“其中”指超市东西之中的一部分，与“水果最便宜”搭配自然。"}, {"text": "之外", "is_correct": false, "explanation": "语义：“之外”指范围以外，“之外水果最便宜”与前文所说的东西范围矛盾。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“之前”指时间上的先后，“之前水果最便宜”不指东西中的一部分。"}, {"text": "以下", "is_correct": false, "explanation": "搭配：“以下”多用于数量界限或段落之后，不接“东西”中的部分。"}], "explanations": {"其中": "正确答案：“其中”指超市东西之中的一部分，与“水果最便宜”搭配自然。", "之外": "语义：“之外”指范围以外，“之外水果最便宜”与前文所说的东西范围矛盾。", "之前": "语义：“之前”指时间上的先后，“之前水果最便宜”不指东西中的一部分。", "以下": "搭配：“以下”多用于数量界限或段落之后，不接“东西”中的部分。"}, "sentence_index": 6, "correct_answer": "其中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国有一个节日，其中很热闹。", "explanation": "这里应该用〈它〉。“其中”要求前文有多个成员组成的范围，只有一个节日时指代它应用“它”。"}, {"text": "中国有很多节日，其中之外还有很多假期。", "explanation": "这里应该用〈此外〉。“其中”指范围之内的部分，补充范围之外的事物要用“此外”。"}, {"text": "中国有很多节日，其中我下周要考试。", "explanation": "这里应该用〈另外〉。“其中”指节日之中的一部分，“下周要考试”不属于节日的范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有很多员工，其中四是经理。", "corrected_sentence": "这家公司有很多员工，其中四人是经理。", "error_description": "错误形式：“其中四是经理”。正确形式：“其中四人是经理”。“四”后指人时需要量词“人”，漏掉后不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市有很多公园，其中北海其中最有名。", "corrected_sentence": "这个城市有很多公园，其中北海最有名。", "error_description": "错误形式：“其中北海其中最有名”。正确形式：“其中北海最有名”。“其中”只需出现一次，句中重复使用是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85863, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "到达", "is_correct": true, "explanation": "到达与“出发”构成反义，指抵达目的地。"}, {"text": "背诵", "is_correct": false, "explanation": "背诵指凭记忆说出内容，与“出发”没有反义关系。"}, {"text": "游览", "is_correct": false, "explanation": "游览指参观风景名胜，与“出发”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理指使东西有序，与“出发”没有反义关系。"}], "correct_answer": "到达", "explanations": {"到达": "到达与“出发”构成反义，指抵达目的地。", "背诵": "背诵指凭记忆说出内容，与“出发”没有反义关系。", "游览": "游览指参观风景名胜，与“出发”没有反义关系。", "整理": "整理指使东西有序，与“出发”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85863, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "到达", "is_correct": true, "explanation": "到达与“出发”构成反义，指抵达目的地。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运指把东西从一处运到另一处，与“出发”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考指用脑子考虑问题，与“出发”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫指清除垃圾和灰尘，与“出发”没有反义关系。"}], "correct_answer": "到达", "explanations": {"到达": "到达与“出发”构成反义，指抵达目的地。", "搬运": "搬运指把东西从一处运到另一处，与“出发”没有反义关系。", "思考": "思考指用脑子考虑问题，与“出发”没有反义关系。", "打扫": "打扫指清除垃圾和灰尘，与“出发”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85863, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出发是从一个地方开始走，去别的地方。", "primary_collocate": null, "pronunciation": "chū fā", "ipa": "ʈʂʰu˥ fa˥", "syllable_count": 2, "sentences": [{"text": "他骑着自行车从家里出发了。", "target_word": "出发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几点出发去公园？", "target_word": "出发", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出发以后，我们走了两个小时。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们背着书包出发去学校。", "target_word": "出发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午两点，我们从学校出发。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气很好，我们决定现在就出发。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们徒步出发，三天后才到山顶。", "target_word": "出发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点儿，我们该出发了！", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你从哪儿出发，我就在哪儿等你。", "target_word": "出发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把行李放好，就准备出发了。", "target_word": "出发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出发了", "label": "体标"}, {"form": "出发过", "label": "体标"}, {"form": "出发地", "label": "复合"}, {"form": "出發", "label": "繁体"}], "register": "通用", "sense_fingerprint": "从一个地方开始走，去别的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f239b726-4c9e-4af2-9b42-8368eb77c8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85863, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出发", "is_correct": true, "explanation": "出发 chū fā：从一个地方开始走，去别的地方。"}, {"text": "除法", "is_correct": false, "explanation": "声调不同：chú（第二声）fǎ（第三声）与 chū fā（第一声）不同，意思是数学中的除法。"}, {"text": "处罚", "is_correct": false, "explanation": "声调不同：chǔ（第三声）fá（第二声）与 chū fā（第一声）不同，意思是处罚。"}, {"text": "触发", "is_correct": false, "explanation": "声调不同：chù（第四声）fā 与 chū（第一声）fā 不同，意思是引起某种反应或动作。"}], "explanations": {"出发": "出发 chū fā：从一个地方开始走，去别的地方。", "除法": "声调不同：chú（第二声）fǎ（第三声）与 chū fā（第一声）不同，意思是数学中的除法。", "处罚": "声调不同：chǔ（第三声）fá（第二声）与 chū fā（第一声）不同，意思是处罚。", "触发": "声调不同：chù（第四声）fā 与 chū（第一声）fā 不同，意思是引起某种反应或动作。"}, "sentence_index": null, "correct_answer": "出发"}, "level_3": {"options": [{"text": "出发", "is_correct": true, "explanation": "出发：从家里开始走，去别的地方，与“骑着自行车”的行进语境相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不表示离开家去别处，与语境矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是停留在原地，与“从家里”离开的语境相反。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”不能与“骑着自行车”构成行进动作，不能表示离家。"}], "explanations": {"出发": "出发：从家里开始走，去别的地方，与“骑着自行车”的行进语境相符。", "唱歌": "语义：唱歌不表示离开家去别处，与语境矛盾。", "睡觉": "语义：睡觉是停留在原地，与“从家里”离开的语境相反。", "吃饭": "搭配：“吃饭”不能与“骑着自行车”构成行进动作，不能表示离家。"}, "sentence_index": 0, "correct_answer": "出发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在北京出发了两天。", "explanation": "这里应该用〈停留〉。出发是离开原地开始行程，在北京待两天要说停留。"}, {"text": "他在公司出发了十年。", "explanation": "这里应该用〈工作〉。出发不表示在某处持续做事，在公司十年要说工作。"}, {"text": "这盘菜已经出发了。", "explanation": "这里应该用〈上桌〉。出发只指人或交通工具动身，菜端上桌不能说出发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出发", "is_correct": true, "explanation": "出发：开始走，去别的地方，与“徒步”和“三天后才到山顶”相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：放弃就不会再走，与“三天后才到山顶”的结果矛盾。"}, {"text": "停止", "is_correct": false, "explanation": "语义：停止行进就到不了山顶，与“三天后才到山顶”矛盾。"}, {"text": "收集", "is_correct": false, "explanation": "搭配：“徒步”修饰行进，不修饰“收集”，搭配不当。"}], "explanations": {"出发": "出发：开始走，去别的地方，与“徒步”和“三天后才到山顶”相符。", "放弃": "语义：放弃就不会再走，与“三天后才到山顶”的结果矛盾。", "停止": "语义：停止行进就到不了山顶，与“三天后才到山顶”矛盾。", "收集": "搭配：“徒步”修饰行进，不修饰“收集”，搭配不当。"}, "sentence_index": 6, "correct_answer": "出发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很累，就出发来休息。", "explanation": "这里应该用〈坐下〉。出发是离开原地去别处，累了想休息应说坐下。"}, {"text": "他生病了，要在床上出发。", "explanation": "这里应该用〈躺着〉。出发表示动身前往别处，生病卧床不说出发。"}, {"text": "这台电脑半夜出发了。", "explanation": "这里应该用〈死机〉。出发只指人或交通工具动身，电脑停止工作不能说出发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们从车站出发着去郊外。", "corrected_sentence": "我们从车站出发去郊外。", "error_description": "“出发”后不能加“着”表示持续，这里说的是动身这一动作，应说“出发去郊外”，“出发着去郊外”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们出发得时候，大家都很兴奋。", "corrected_sentence": "我们出发的时候，大家都很兴奋。", "error_description": "“出发的时候”中的“的”不能换成“得”；“得”用于动词后引出补语，“出发得时候”不成立，应说“出发的时候”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
