INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85865, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“不过”是说后面的话和前面的话不太一样。", "primary_collocate": null, "pronunciation": "bú guò", "ipa": "pu˧˥ kuo˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服很好看，不过有点贵。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去，不过今天没有时间。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很聪明，不过不太努力。", "target_word": "不过", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店不大，不过东西很便宜。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气不错，不过风有点大。", "target_word": "不过", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢这本书，不过它太长了。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜很好吃，不过我吃不完。", "target_word": "不过", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他会说汉语，不过说得不太好。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个主意好，不过要花很多钱。", "target_word": "不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很累，不过心情还不错。", "target_word": "不过", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "转折连词，后半句补充与前半句不太一致的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee9cc0a1-56c1-4470-a8fc-b7afcfb653ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85865, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不过", "is_correct": true, "explanation": "正确答案。“不过”读 bú guò，是转折连词，表示后面的话与前面的话不太一样。"}, {"text": "不够", "is_correct": false, "explanation": "gòu（第四声）与 guò 的韵母不同（ou 与 uo），意思是“不足、不够”。"}, {"text": "不错", "is_correct": false, "explanation": "cuò 与 guò 的声母不同（c 与 g），意思是“还可以”。"}, {"text": "不顾", "is_correct": false, "explanation": "gù 与 guò 的韵母不同（少一个 o），意思是“不管”。"}, {"text": "不怪", "is_correct": false, "explanation": "guài 与 guò 的韵母不同（uai 与 uo），意思是“不责怪”。"}], "explanations": {"不过": "正确答案。“不过”读 bú guò，是转折连词，表示后面的话与前面的话不太一样。", "不够": "gòu（第四声）与 guò 的韵母不同（ou 与 uo），意思是“不足、不够”。", "不错": "cuò 与 guò 的声母不同（c 与 g），意思是“还可以”。", "不顾": "gù 与 guò 的韵母不同（少一个 o），意思是“不管”。", "不怪": "guài 与 guò 的韵母不同（uai 与 uo），意思是“不责怪”。"}, "sentence_index": null, "correct_answer": "不过"}, "level_3": {"options": [{"text": "不过", "is_correct": true, "explanation": "正确。“不过”表示转折：前句说衣服好看，后句“有点贵”与之不一致，语气比“但是”轻。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，这里前后关系颠倒，“有点贵”不是“好看”的原因。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，句中前后并没有先后的关系。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“如果”要与后面的“就”呼应，不能接在“很好看，”之后做转折。"}], "explanations": {"不过": "正确。“不过”表示转折：前句说衣服好看，后句“有点贵”与之不一致，语气比“但是”轻。", "因为": "语义：“因为”引出原因，这里前后关系颠倒，“有点贵”不是“好看”的原因。", "然后": "语义：“然后”表示先后顺序，句中前后并没有先后的关系。", "如果": "搭配：“如果”要与后面的“就”呼应，不能接在“很好看，”之后做转折。"}, "sentence_index": 0, "correct_answer": "不过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先吃饭，不过再看电影。", "explanation": "这里应该用〈然后〉。前后是先后顺序，不是转折，“不过”会让人以为吃饭与看电影之间有对立。"}, {"text": "他会唱歌，不过会跳舞。", "explanation": "这里应该用〈而且〉。前后是并列补充，“不过”表示转折，会让人误以为“会跳舞”与“会唱歌”相反。"}, {"text": "我先写作业，不过复习生词。", "explanation": "这里应该用〈然后〉。“先……然后……”表示先后顺序，“不过”表示转折，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不过", "is_correct": true, "explanation": "正确。“不过”表示转折：前句说菜好吃，后句“我吃不完”与之形成转折。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示由前面引出的动作，“吃不完”不是吃完之后采取的动作。"}, {"text": "况且", "is_correct": false, "explanation": "语域：“况且”偏书面，口语里一般不这样用，且这里前后不是递进补充的关系。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，这里前后并不是两种可以选的情况。"}], "explanations": {"不过": "正确。“不过”表示转折：前句说菜好吃，后句“我吃不完”与之形成转折。", "于是": "语义：“于是”表示由前面引出的动作，“吃不完”不是吃完之后采取的动作。", "况且": "语域：“况且”偏书面，口语里一般不这样用，且这里前后不是递进补充的关系。", "或者": "语义：“或者”表示选择，这里前后并不是两种可以选的情况。"}, "sentence_index": 6, "correct_answer": "不过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "因为下雨，不过比赛取消了。", "explanation": "这里应该用〈所以〉。“因为……”引出原因，后面接结果；“不过”表示转折，与因果关系不符。"}, {"text": "如果明天下雨，不过我们就不去。", "explanation": "这里应该去掉“不过”，说“如果明天下雨，我们就不去”。“如果……就……”表示条件，“不过”表示转折，不能放在条件与结果之间。"}, {"text": "他一边吃饭，不过看书。", "explanation": "这里应该用〈一边〉。“一边……一边……”表示两件事同时进行，不是转折，“不过”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间很大，不过了有点冷。", "corrected_sentence": "这个房间很大，不过有点冷。", "error_description": "“不过”是连词，后面不能加“了”。错误：“不过了有点冷”；正确：“不过有点冷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本词典很厚，但是不过很好用。", "corrected_sentence": "这本词典很厚，不过很好用。", "error_description": "“但是”和“不过”都表示转折，同一个转折处只用一个，应去掉“但是”。错误：“但是不过”；正确：“不过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85866, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
