INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85869, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“至”是说到某个地方或某个时候。", "primary_collocate": null, "pronunciation": "zhì", "ipa": "ʈʂɻ̩⁵¹", "syllable_count": 1, "sentences": [{"text": "从星期一至星期五，我都要上班。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览时间是上午九点至下午五点。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这趟火车从北京至上海要五个小时。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本店营业时间为每天八点至晚上十点。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从一月至三月，这里常常下雪。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁一号线从机场至市中心很方便。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家从第三页至第五页复习课文。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校从七月至八月放假。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从家至公司只要二十分钟。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从早上七点至中午十二点一直在学习。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "介词，书面，表示到某个时间或地点，常与“从”连用：从……至……", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 4 words above tier T1 (max 2): 本店 (Zipf 3.13), 营业时间 (Zipf 3.09), 八点 (Zipf 3.85), 十点 (Zipf 3.73)']::text[], '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85869, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "至", "is_correct": true, "explanation": "正确答案。“至”读作 zhì，表示到某个时间或地点。"}, {"text": "只", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，“只”意思是仅仅。"}, {"text": "是", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），声调相同，“是”表示判断。"}, {"text": "知", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，“知”意思是知道。"}], "explanations": {"至": "正确答案。“至”读作 zhì，表示到某个时间或地点。", "只": "zhǐ（第三声）与 zhì（第四声）声调不同，“只”意思是仅仅。", "是": "shì 与 zhì 声母不同（sh 与 zh），声调相同，“是”表示判断。", "知": "zhī（第一声）与 zhì（第四声）声调不同，“知”意思是知道。"}, "sentence_index": null, "correct_answer": "至"}, "level_3": {"options": [{"text": "至", "is_correct": true, "explanation": "“至”引出时间的终点，与“从”搭配，表示从星期一到星期五。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向或对象，不能表示时间的终点。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者，“从星期一给星期五”没有接受者，不成立。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示目的或对象，不表示时间范围。"}], "explanations": {"至": "“至”引出时间的终点，与“从”搭配，表示从星期一到星期五。", "向": "语义：“向”表示方向或对象，不能表示时间的终点。", "给": "配价：“给”需要接受者，“从星期一给星期五”没有接受者，不成立。", "为": "语义：“为”表示目的或对象，不表示时间范围。"}, "sentence_index": 0, "correct_answer": "至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下班后我至家就开始做饭，很快。", "explanation": "这里应该用〈到〉。“至”作动词单独表示到达，多用于书面；口语说到家要用“到”。"}, {"text": "咱们明天至北京玩吧，很好玩。", "explanation": "这里应该用〈去〉。“至”是书面用语，口语中表示前往某地要用“去”。"}, {"text": "至早上七点，我开始学习。", "explanation": "这里应该用〈从〉。“至”标示终点，表示起点要用“从”，应说“从早上七点，我开始学习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85869, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "至", "is_correct": true, "explanation": "正确答案。“至”读作 zhì，表示到某个时间或地点。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，“直”意思是不弯曲。"}, {"text": "事", "is_correct": false, "explanation": "shì 与 zhì 声母不同，声调相同，“事”意思是事情。"}, {"text": "字", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），声调相同，“字”意思是文字。"}], "explanations": {"至": "正确答案。“至”读作 zhì，表示到某个时间或地点。", "直": "zhí（第二声）与 zhì（第四声）声调不同，“直”意思是不弯曲。", "事": "shì 与 zhì 声母不同，声调相同，“事”意思是事情。", "字": "zì 与 zhì 声母不同（z 与 zh），声调相同，“字”意思是文字。"}, "sentence_index": null, "correct_answer": "至"}, "level_3": {"options": [{"text": "至", "is_correct": true, "explanation": "“至”引出页码的终点，与“从”搭配，表示从第三页到第五页。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，不表示页码的终点。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”后要接宾语再接动词，“把第五页”不能充当范围的终点。"}, {"text": "被", "is_correct": false, "explanation": "配价：“被”引出施事或受事，这里不构成被动结构。"}], "explanations": {"至": "“至”引出页码的终点，与“从”搭配，表示从第三页到第五页。", "对": "语义：“对”引出对象，不表示页码的终点。", "把": "配价：“把”后要接宾语再接动词，“把第五页”不能充当范围的终点。", "被": "配价：“被”引出施事或受事，这里不构成被动结构。"}, "sentence_index": 6, "correct_answer": "至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我至学校，然后去图书馆。", "explanation": "这里应该用〈到〉。“至”作动词表示到达，口语说到某处要用“到”。"}, {"text": "学生至早上七点就开始复习，一直到中午。", "explanation": "这里应该用〈从〉。“至”标示终点，表示起点要用“从”，应说“学生从早上七点开始复习”。"}, {"text": "他至图书馆一直学习到中午。", "explanation": "这里应该用〈在〉。“至”表示到达的终点，不表示动作发生的地点；在某处学习要用“在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "从门口至到教室要走十分钟。", "corrected_sentence": "从门口至教室要走十分钟。", "error_description": "错误在于把“至”和“到”叠用。二者都表示终点，不能连用，应只保留“至”，说“从门口至教室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从七点至到九点学习。", "corrected_sentence": "他从七点至九点学习。", "error_description": "错误在于把“至”和“到”叠用。二者都表示终点，不能连用，应只保留“至”，说“他从七点至九点学习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
