INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85870, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示到达的时间、地点或程度，相当于“到”。", "primary_collocate": null, "pronunciation": "zhì", "ipa": "ʈʂɻ̩⁵¹", "syllable_count": 1, "sentences": [{"text": "这个班少至五人，多至十人。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大至国家，小至家庭，都需要规则。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从早上忙至深夜。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路从城东通至城西。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店每年从三月开至十月。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的天气冷至零下十度。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议从上午十点开至下午两点。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格高至一万元，低至一千元。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我已经读至第五章了。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的人数多至三百人。", "target_word": "至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "介词，书面，动词后或数量前表示到达的时间、地点或程度，相当于“到”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 条路 (Zipf 3.25), 城东 (Zipf 3.22), 城西 (Zipf 3.25)']::text[], '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85870, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "至", "is_correct": true, "explanation": "正确答案。“至”读作 zhì，表示到达的程度或数量。"}, {"text": "只", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，“只”意思是仅仅。"}, {"text": "是", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），声调相同，“是”表示判断。"}, {"text": "知", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，“知”意思是知道。"}], "explanations": {"至": "正确答案。“至”读作 zhì，表示到达的程度或数量。", "只": "zhǐ（第三声）与 zhì（第四声）声调不同，“只”意思是仅仅。", "是": "shì 与 zhì 声母不同（sh 与 zh），声调相同，“是”表示判断。", "知": "zhī（第一声）与 zhì（第四声）声调不同，“知”意思是知道。"}, "sentence_index": null, "correct_answer": "至"}, "level_3": {"options": [{"text": "至", "is_correct": true, "explanation": "“至”引出人数的上限，与“多至”呼应，表示最少到五人。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向或对象，不能用来表示人数达到某个数。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”需要带宾语和动词，“少把五人”不成立。"}, {"text": "被", "is_correct": false, "explanation": "配价：“被”需要施事或受事，“少被五人”不成立。"}], "explanations": {"至": "“至”引出人数的上限，与“多至”呼应，表示最少到五人。", "向": "语义：“向”表示方向或对象，不能用来表示人数达到某个数。", "把": "配价：“把”需要带宾语和动词，“少把五人”不成立。", "被": "配价：“被”需要施事或受事，“少被五人”不成立。"}, "sentence_index": 0, "correct_answer": "至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下班后至家，马上做饭。", "explanation": "这里应该用〈到〉。“至”不作动词单独表示“到家”，说到达某处要用“到”。"}, {"text": "这个问题很至难，我们都不会。", "explanation": "这里不该用“至”。“至”是介词，后面要接时间、地点或数量，不能放在形容词前表示程度；应说“很难”。"}, {"text": "至十点，我开始做饭。", "explanation": "这里应该用〈从〉。“至”标示终点，表示起点要用“从”，应说“从十点起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85870, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "至", "is_correct": true, "explanation": "正确答案。“至”读作 zhì，表示到达的程度或数量。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，“直”意思是不弯曲。"}, {"text": "事", "is_correct": false, "explanation": "shì 与 zhì 声母不同，声调相同，“事”意思是事情。"}, {"text": "字", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），声调相同，“字”意思是文字。"}], "explanations": {"至": "正确答案。“至”读作 zhì，表示到达的程度或数量。", "直": "zhí（第二声）与 zhì（第四声）声调不同，“直”意思是不弯曲。", "事": "shì 与 zhì 声母不同，声调相同，“事”意思是事情。", "字": "zì 与 zhì 声母不同（z 与 zh），声调相同，“字”意思是文字。"}, "sentence_index": null, "correct_answer": "至"}, "level_3": {"options": [{"text": "至", "is_correct": true, "explanation": "“至”引出结束的时间，与“从……开”呼应，表示会议到下午两点为止。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，不表示时间的终点。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者，“开给下午两点”不成立。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”需要宾语和动词，“开把下午两点”不成立。"}], "explanations": {"至": "“至”引出结束的时间，与“从……开”呼应，表示会议到下午两点为止。", "对": "语义：“对”引出对象，不表示时间的终点。", "给": "配价：“给”需要接受者，“开给下午两点”不成立。", "把": "配价：“把”需要宾语和动词，“开把下午两点”不成立。"}, "sentence_index": 6, "correct_answer": "至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我至家里看书，直到十点。", "explanation": "这里应该用〈在〉。“至”表示到达的终点，不表示动作发生的地点；在某处做事要用“在”。"}, {"text": "咱们走路至学校吧，很近。", "explanation": "这里应该用〈去〉。“至”表示到达的终点，口语中说动身前往某处要用“去”。"}, {"text": "这个班人数至很多，每天都很吵。", "explanation": "这里不该用“至”。“至”后要接具体数量或终点，不能接“很多”；应说“人数很多”或“多至五十人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路从北门到至南门很长。", "corrected_sentence": "这条路从北门至南门很长。", "error_description": "错误在于把“到”和“至”叠用。二者都表示终点，不能连用，应只保留“至”，说“从北门至南门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从早上八点至到晚上六点营业。", "corrected_sentence": "我们从早上八点至晚上六点营业。", "error_description": "错误在于把“至”和“到”叠用。二者都表示终点，不能连用，应只保留“至”，说“我们从早上八点至晚上六点营业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
