INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85872, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "讨人喜欢；可爱。", "primary_collocate": null, "pronunciation": "kě rén", "ipa": "kʰɤ˨˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这个小女孩笑起来很可人。", "target_word": "可人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小姑娘扎着两根辫子，模样很可人。", "target_word": "可人", "complexity_tier": "T3", "furigana": "kě rén", "sentence_source": "generated"}, {"text": "小狗圆圆的眼睛特别可人。", "target_word": "可人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的小侄女长得很可人。", "target_word": "可人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，这个孩子又聪明又可人。", "target_word": "可人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的小花十分可人。", "target_word": "可人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着白裙子，样子可人。", "target_word": "可人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢她可人的笑容。", "target_word": "可人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的小脸红红的，很可人。", "target_word": "可人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小猫又小又可人。", "target_word": "可人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "形容人或事物讨人喜欢、可爱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可人", "is_correct": true, "explanation": "正确。“可人”指讨人喜欢，与“笑起来”的讨喜形象相合。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”指神情郑重、不活泼，与“笑起来”的讨喜形象相矛盾。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”指态度不热情，与“笑起来”的亲切形象不相合。"}, {"text": "可怜", "is_correct": false, "explanation": "语义：“可怜”指令人同情，与句中讨人喜欢的意思不符。"}], "explanations": {"可人": "正确。“可人”指讨人喜欢，与“笑起来”的讨喜形象相合。", "严肃": "语义：“严肃”指神情郑重、不活泼，与“笑起来”的讨喜形象相矛盾。", "冷淡": "语义：“冷淡”指态度不热情，与“笑起来”的亲切形象不相合。", "可怜": "语义：“可怜”指令人同情，与句中讨人喜欢的意思不符。"}, "sentence_index": 0, "correct_answer": "可人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子哭得很可人。", "explanation": "这里应该用〈可怜〉。“可人”指讨人喜欢，描写哭泣令人同情的样子应说〈可怜〉。"}, {"text": "她听到消息后很可人。", "explanation": "这里应该用〈伤心〉。“可人”指让人喜欢，描写难过的样子不能用“可人”。"}, {"text": "他的脸色很可人。", "explanation": "这里应该用〈苍白〉。“可人”指讨人喜欢，形容脸色苍白、难看的样子不能用“可人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可人", "is_correct": true, "explanation": "正确。“可人”指讨人喜欢，与“穿着白裙子”的清爽形象相合。"}, {"text": "邋遢", "is_correct": false, "explanation": "语义：“邋遢”指不整洁，与“穿着白裙子”的干净形象相矛盾。"}, {"text": "凌乱", "is_correct": false, "explanation": "语义：“凌乱”指杂乱无序，与“穿着白裙子”的整洁、讨人喜欢的形象相反。"}, {"text": "狼狈", "is_correct": false, "explanation": "语义：“狼狈”指窘迫、困窘的状态，与穿着干净白裙的情景不相合。"}], "explanations": {"可人": "正确。“可人”指讨人喜欢，与“穿着白裙子”的清爽形象相合。", "邋遢": "语义：“邋遢”指不整洁，与“穿着白裙子”的干净形象相矛盾。", "凌乱": "语义：“凌乱”指杂乱无序，与“穿着白裙子”的整洁、讨人喜欢的形象相反。", "狼狈": "语义：“狼狈”指窘迫、困窘的状态，与穿着干净白裙的情景不相合。"}, "sentence_index": 6, "correct_answer": "可人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只毒蛇很可人。", "explanation": "这里应该用〈可怕〉。“可人”指讨人喜欢，毒蛇有毒、令人害怕，应说〈可怕〉，不能用“可人”。"}, {"text": "这个腐烂的水果很可人。", "explanation": "这里应该用〈恶心〉。“可人”指让人喜欢，形容腐烂发臭的水果应说〈恶心〉，不能用“可人”。"}, {"text": "他的怒吼很可人。", "explanation": "这里应该用〈刺耳〉。“可人”指讨人喜欢，形容刺耳的怒吼不能用“可人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个小男孩圆圆的脸很的可人。", "corrected_sentence": "那个小男孩圆圆的脸很可人。", "error_description": "错误：“很”与“可人”之间多了“的”。程度副词“很”直接修饰形容词，应说“很可人”，不能说“很的可人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只小猫很很可人。", "corrected_sentence": "这只小猫很可人。", "error_description": "错误：程度副词“很”重复了。修饰“可人”只需要一个“很”，应说“很可人”，不能说“很很可人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
